from (values
(355188,39466,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend wird er jeden letzten Rest Schaum von seinem Körper ..., das Ende einer Ära!'::text,'abrasiert haben'::text,'abrasieren'::text,'am Abrasieren sein'::text,'Bis heute Abend wird er jeden letzten Rest Schaum von seinem Körper abrasiert haben, das Ende einer Ära!'::text),
(355192,39466,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора він ... з тіла кожен останній шматочок піни. Кінець епохи!'::text,'поголить'::text,'поголить'::text,'голитиме'::text,'До вечора він поголить з тіла кожен останній шматочок піни. Кінець епохи!'::text),
(355191,39466,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para esta noche ... hasta el último resto de espuma de su cuerpo. ¡El fin de una era!'::text,'habrá afeitado'::text,'afeitará'::text,'estará afeitando'::text,'Para esta noche habrá afeitado hasta el último resto de espuma de su cuerpo. ¡El fin de una era!'::text),
(355190,39466,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, il ... la moindre trace de mousse de son corps. La fin d''une époque !'::text,'aura rasé'::text,'rasera'::text,'sera en train de raser'::text,'D''ici ce soir, il aura rasé la moindre trace de mousse de son corps. La fin d''une époque !'::text),
(355193,39466,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar vücudundaki köpüğün son zerresini de ..., bir devrin sonu!'::text,'tıraş etmiş olacak'::text,'tıraş edecek'::text,'tıraş ediyor olacak'::text,'Bu akşama kadar vücudundaki köpüğün son zerresini de tıraş etmiş olacak, bir devrin sonu!'::text),
(355194,39466,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estére ... a testéről az utolsó habcseppet is. Egy korszak vége!'::text,'le fogja borotválni'::text,'le fogja borotválni'::text,'borotválni fogja'::text,'Estére le fogja borotválni a testéről az utolsó habcseppet is. Egy korszak vége!'::text),
(355197,39467,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre ihm der Schaum ausgegangen, ... das ein kompletter Albtraum gewesen!'::text,'wäre'::text,'wird'::text,'war'::text,'Wäre ihm der Schaum ausgegangen, wäre das ein kompletter Albtraum gewesen!'::text),
(355201,39467,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби в нього закінчилася піна, це ... справжнім жахіттям!'::text,'було б'::text,'буде'::text,'було'::text,'Якби в нього закінчилася піна, це було б справжнім жахіттям!'::text),
(355200,39467,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se le hubiera acabado la espuma, ¡esto ... una pesadilla total!'::text,'habría sido'::text,'será'::text,'fue'::text,'Si se le hubiera acabado la espuma, ¡esto habría sido una pesadilla total!'::text),
(355199,39467,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait manqué de mousse, ça ... un vrai cauchemar !'::text,'aurait été'::text,'sera'::text,'était'::text,'S''il avait manqué de mousse, ça aurait été un vrai cauchemar !'::text),
(355202,39467,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpüğü bitseydi, bu tam bir kâbus ...!'::text,'olurdu'::text,'olacak'::text,'oldu'::text,'Köpüğü bitseydi, bu tam bir kâbus olurdu!'::text),
(355203,39467,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha kifogyott volna a habból, ez ... egy teljes rémálom!'::text,'lett volna'::text,'lesz'::text,'volt'::text,'Ha kifogyott volna a habból, ez lett volna egy teljes rémálom!'::text),
(355206,39468,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Barbier bestritt, zu viel Schaum auf seinen Bart ...'::text,'gegeben zu haben'::text,'zu geben'::text,'gegeben'::text,'Der Barbier bestritt, zu viel Schaum auf seinen Bart gegeben zu haben.'::text),
(355210,39468,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перукар заперечив, що ... йому на бороду забагато піни.'::text,'наніс'::text,'наносити'::text,'наніс'::text,'Перукар заперечив, що наніс йому на бороду забагато піни.'::text),
(355209,39468,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El barbero negó ... demasiada espuma en su barba.'::text,'haber puesto'::text,'poner'::text,'puso'::text,'El barbero negó haber puesto demasiada espuma en su barba.'::text),
(355208,39468,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le barbier a nié ... trop de mousse sur sa barbe.'::text,'avoir mis'::text,'mettre'::text,'mis'::text,'Le barbier a nié avoir mis trop de mousse sur sa barbe.'::text),
(355211,39468,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Berber, sakalına çok fazla köpük ... inkâr etti.'::text,'sürdüğünü'::text,'sürmeyi'::text,'sürdü'::text,'Berber, sakalına çok fazla köpük sürdüğünü inkâr etti.'::text),
(355212,39468,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A borbély tagadta, hogy túl sok habot ... a szakállára.'::text,'kent volna'::text,'kenni'::text,'kent'::text,'A borbély tagadta, hogy túl sok habot kent volna a szakállára.'::text),
(355215,39469,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hätte nicht so viel Schaum benutzen ..., denn die Hälfte ist auf dem Boden gelandet.'::text,'sollen'::text,'dürfen'::text,'können'::text,'Er hätte nicht so viel Schaum benutzen sollen, denn die Hälfte ist auf dem Boden gelandet.'::text),
(355219,39469,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... використовувати стільки піни, бо половина опинилася на підлозі.'::text,'не мав'::text,'не смів'::text,'не міг'::text,'Він не мав використовувати стільки піни, бо половина опинилася на підлозі.'::text),
(355218,39469,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... usado tanta espuma, porque la mitad acabó en el suelo.'::text,'No debería haber'::text,'No tenía que haber'::text,'No podía haber'::text,'No debería haber usado tanta espuma, porque la mitad acabó en el suelo.'::text),
(355217,39469,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... utiliser autant de mousse, car la moitié a fini par terre.'::text,'n''aurait pas dû'::text,'ne devait pas'::text,'ne pouvait pas'::text,'Il n''aurait pas dû utiliser autant de mousse, car la moitié a fini par terre.'::text),
(355220,39469,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kadar çok köpük ..., çünkü yarısı yere döküldü.'::text,'kullanmamalıydı'::text,'kullanmamalıydı'::text,'kullanamazdı'::text,'O kadar çok köpük kullanmamalıydı, çünkü yarısı yere döküldü.'::text),
(355221,39469,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem ... ennyi habot használnia, mert a fele a padlón kötött ki.'::text,'kellett volna'::text,'lett volna szabad'::text,'tudott'::text,'Nem kellett volna ennyi habot használnia, mert a fele a padlón kötött ki.'::text),
(355224,39470,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor der Party ließ er sich die Bartlinie vom Barbier mit Schaum und Rasiermesser ...'::text,'rasieren'::text,'zu rasieren'::text,'rasierend'::text,'Vor der Party ließ er sich die Bartlinie vom Barbier mit Schaum und Rasiermesser rasieren.'::text),
(355228,39470,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перед вечіркою він попросив барбера ... йому лінію бороди піною та бритвою.'::text,'підголити'::text,'підголити'::text,'підголювання'::text,'Перед вечіркою він попросив барбера підголити йому лінію бороди піною та бритвою.'::text),
(355227,39470,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de la fiesta, se hizo ... la línea de la barba por un barbero, con espuma y navaja.'::text,'afeitar'::text,'afeitar'::text,'afeitando'::text,'Antes de la fiesta, se hizo afeitar la línea de la barba por un barbero, con espuma y navaja.'::text),
(355226,39470,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant la fête, il s''est fait ... la ligne de barbe par un barbier, avec de la mousse et un rasoir.'::text,'raser'::text,'à raser'::text,'rasant'::text,'Avant la fête, il s''est fait raser la ligne de barbe par un barbier, avec de la mousse et un rasoir.'::text),
(355229,39470,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Partiden önce sakal çizgisini bir berbere köpük ve ustura ile ...'::text,'tıraş ettirdi'::text,'tıraş etmeyi'::text,'tıraş ederek'::text,'Partiden önce sakal çizgisini bir berbere köpük ve ustura ile tıraş ettirdi.'::text),
(355230,39470,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A buli előtt egy borbéllyal habbal és borotvával ... a szakállvonalát.'::text,'borotváltatta ki'::text,'kiborotválni'::text,'borotválva'::text,'A buli előtt egy borbéllyal habbal és borotvával borotváltatta ki a szakállvonalát.'::text),
(355233,39471,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, ich wünschte, mein Barbier ... so viel Schaum, mein Gesicht ist mega trocken, echt jetzt.'::text,'benutzte'::text,'benutzt'::text,'wird benutzen'::text,'Digga, ich wünschte, mein Barbier benutzte so viel Schaum, mein Gesicht ist mega trocken, echt jetzt.'::text),
(355237,39471,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, хотів би я, щоб мій барбер ... стільки піни, в мене таке сухе обличчя, чесно.'::text,'використовував'::text,'використовує'::text,'використовуватиме'::text,'Бро, хотів би я, щоб мій барбер використовував стільки піни, в мене таке сухе обличчя, чесно.'::text),
