(355235,39471,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si seulement mon barbier ... autant de mousse, j''ai le visage trop sec, sérieux.'::text,'utilisait'::text,'utilise'::text,'utilisera'::text,'Frérot, si seulement mon barbier utilisait autant de mousse, j''ai le visage trop sec, sérieux.'::text),
(355238,39471,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, keşke berberim o kadar köpük ..., yüzüm aşırı kuru, cidden.'::text,'kullansa'::text,'kullanıyor'::text,'kullanacak'::text,'Kanka, keşke berberim o kadar köpük kullansa, yüzüm aşırı kuru, cidden.'::text),
(355239,39471,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, bárcsak a borbélyom ... ennyi habot, annyira száraz az arcom, komolyan.'::text,'használna'::text,'használ'::text,'használni fog'::text,'Tesó, bárcsak a borbélyom használna ennyi habot, annyira száraz az arcom, komolyan.'::text),
(355242,39472,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Typ am Pool, ... Arm voller Schaum ist, ist irgendwie komplett durch, Bro.'::text,'dessen'::text,'der'::text,'welcher'::text,'Der Typ am Pool, dessen Arm voller Schaum ist, ist irgendwie komplett durch, Bro.'::text),
(355246,39472,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Той хлопець біля басейну, ... рука вся в піні, трохи з привітом, бро.'::text,'чия'::text,'який'::text,'що'::text,'Той хлопець біля басейну, чия рука вся в піні, трохи з привітом, бро.'::text),
(355245,39472,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El tío de la piscina, ... brazo está lleno de espuma, está medio loco, bro.'::text,'cuyo'::text,'que'::text,'el cual'::text,'El tío de la piscina, cuyo brazo está lleno de espuma, está medio loco, bro.'::text),
(355244,39472,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mec près de la piscine, ... le bras est couvert de mousse, est un peu barge, frérot.'::text,'dont'::text,'qui'::text,'lequel'::text,'Le mec près de la piscine, dont le bras est couvert de mousse, est un peu barge, frérot.'::text),
