(355275,39475,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A folyamat végére a borbély ... az összes habot az alany arcáról.'::text,'el fogja távolítani'::text,'el fogja távolítani'::text,'eltávolítja'::text,'A folyamat végére a borbély el fogja távolítani az összes habot az alany arcáról.'::text),
(379695,42189,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während die Menge für die Registrierung ..., ist der Namensschilddrucker kaputtgegangen! Totaler Albtraum!'::text,'anstand'::text,'anstand'::text,'angestanden hat'::text,'Während die Menge für die Registrierung anstand, ist der Namensschilddrucker kaputtgegangen! Totaler Albtraum!'::text),
(379699,42189,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки натовп ... в черзі на реєстрацію, зламався принтер бейджів! Повний жах!'::text,'стояв'::text,'став'::text,'став'::text,'Поки натовп стояв в черзі на реєстрацію, зламався принтер бейджів! Повний жах!'::text),
