(379701,42189,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a tömeg a regisztrációért ..., elromlott a névkártyanyomtató! Totális rémálom!'::text,'sorban állt'::text,'beállt a sorba'::text,'beállt a sorba'::text,'Miközben a tömeg a regisztrációért sorban állt, elromlott a névkártyanyomtató! Totális rémálom!'::text),
