(379708,42190,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, мені сказали, що вони ... людей на реєстрації з сьомої ранку.'::text,'реєструють'::text,'реєструють'::text,'реєструють'::text,'Слухай, мені сказали, що вони реєструють людей на реєстрації з сьомої ранку.'::text),
