(379706,42190,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, ils m''ont dit qu''ils ... les gens à l''accueil depuis 7 h du matin.'::text,'enregistrent'::text,'sont en train d''enregistrer'::text,'enregistrent'::text,'Écoute, ils m''ont dit qu''ils enregistrent les gens à l''accueil depuis 7 h du matin.'::text),
(379709,42190,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana sabah 7''den beri kayıtta insanları ... söylediler.'::text,'kontrol ettiklerini'::text,'kontrol ettiklerini'::text,'kontrol ettiklerini'::text,'Dinle, bana sabah 7''den beri kayıtta insanları kontrol ettiklerini söylediler.'::text),
(379710,42190,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondták, reggel 7 óta ... be az embereket a regisztrációnál.'::text,'léptetik'::text,'léptetik'::text,'léptetik'::text,'Figyelj, azt mondták, reggel 7 óta léptetik be az embereket a regisztrációnál.'::text),
(379713,42191,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Gast ... gerade seinen Namen ins Anmeldebuch, als das Personal die nächste Person aufrief.'::text,'schrieb'::text,'schrieb'::text,'hat geschrieben'::text,'Ein Gast schrieb gerade seinen Namen ins Anmeldebuch, als das Personal die nächste Person aufrief.'::text),
(379717,42191,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гість ... своє ім''я в реєстраційну книгу, коли персонал покликав наступного.'::text,'писав'::text,'написав'::text,'написав'::text,'Гість писав своє ім''я в реєстраційну книгу, коли персонал покликав наступного.'::text),
(379716,42191,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un invitado ... su nombre en el libro de registro cuando el personal llamó a la siguiente persona.'::text,'estaba escribiendo'::text,'escribió'::text,'ha escrito'::text,'Un invitado estaba escribiendo su nombre en el libro de registro cuando el personal llamó a la siguiente persona.'::text),
(379715,42191,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un invité ... son nom dans le registre quand le personnel a appelé la personne suivante.'::text,'écrivait'::text,'a écrit'::text,'a écrit'::text,'Un invité écrivait son nom dans le registre quand le personnel a appelé la personne suivante.'::text),
(379718,42191,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Personel sıradaki kişiyi çağırdığında bir misafir adını kayıt defterine ...'::text,'yazıyordu'::text,'yazdı'::text,'yazmış'::text,'Personel sıradaki kişiyi çağırdığında bir misafir adını kayıt defterine yazıyordu.'::text),
(379719,42191,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy vendég éppen ... a nevét a regisztrációs könyvbe, amikor a személyzet szólította a következőt.'::text,'írta'::text,'beírta'::text,'beírta'::text,'Egy vendég éppen írta a nevét a regisztrációs könyvbe, amikor a személyzet szólította a következőt.'::text),
(379731,42193,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Registrierung öffnete, ... sich in der Halle schon eine lange Schlange gebildet.'::text,'hatte'::text,'hat'::text,'bildet'::text,'Als die Registrierung öffnete, hatte sich in der Halle schon eine lange Schlange gebildet.'::text),
(379735,42193,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На той час, як відкрилася реєстрація, у залі вже ... довга черга.'::text,'утворилася'::text,'утворилася'::text,'утворюється'::text,'На той час, як відкрилася реєстрація, у залі вже утворилася довга черга.'::text),
(379734,42193,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando abrió el registro, ... una larga cola en el vestíbulo.'::text,'se había formado'::text,'se ha formado'::text,'se forma'::text,'Para cuando abrió el registro, se había formado una larga cola en el vestíbulo.'::text),
(379733,42193,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand l''enregistrement a ouvert, une longue file ... dans le hall.'::text,'s''était formée'::text,'s''est formée'::text,'se forme'::text,'Quand l''enregistrement a ouvert, une longue file s''était formée dans le hall.'::text),
(379736,42193,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kayıt açıldığında salonda uzun bir kuyruk ...'::text,'oluşmuştu'::text,'oluştu'::text,'oluşuyor'::text,'Kayıt açıldığında salonda uzun bir kuyruk oluşmuştu.'::text),
(379737,42193,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire megnyílt a regisztráció, hosszú sor ... a teremben.'::text,'alakult ki'::text,'alakult ki'::text,'alakul ki'::text,'Mire megnyílt a regisztráció, hosszú sor alakult ki a teremben.'::text),
(379740,42194,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, wenn wir uns nicht beeilen, ... die Registrierung, bevor wir unsere Badges haben, ehrlich.'::text,'schließt'::text,'würde schließen'::text,'schloss'::text,'Digga, wenn wir uns nicht beeilen, schließt die Registrierung, bevor wir unsere Badges haben, ehrlich.'::text),
(379744,42194,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якщо не поспішимо, реєстрація ... раніше, ніж ми отримаємо бейджі, чесно.'::text,'закриється'::text,'закрилася б'::text,'закрилася'::text,'Бро, якщо не поспішимо, реєстрація закриється раніше, ніж ми отримаємо бейджі, чесно.'::text),
(379743,42194,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si no nos damos prisa, el registro ... antes de que tengamos las acreditaciones, en serio.'::text,'cerrará'::text,'cerraría'::text,'cerró'::text,'Bro, si no nos damos prisa, el registro cerrará antes de que tengamos las acreditaciones, en serio.'::text),
(379742,42194,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si on ne se dépêche pas, l''enregistrement ... avant qu''on ait nos badges, sérieux.'::text,'fermera'::text,'fermerait'::text,'a fermé'::text,'Frérot, si on ne se dépêche pas, l''enregistrement fermera avant qu''on ait nos badges, sérieux.'::text),
(379745,42194,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, acele etmezsek kayıt, yaka kartlarımızı almadan ..., cidden.'::text,'kapanacak'::text,'kapanırdı'::text,'kapandı'::text,'Kanka, acele etmezsek kayıt, yaka kartlarımızı almadan kapanacak, cidden.'::text),
(379746,42194,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha nem sietünk, a regisztráció ..., mielőtt megkapjuk a kitűzőinket, komolyan.'::text,'bezár'::text,'bezárna'::text,'bezárt'::text,'Tesó, ha nem sietünk, a regisztráció bezár, mielőtt megkapjuk a kitűzőinket, komolyan.'::text),
(379749,42195,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Geschäftsleitung wünscht sich, die Registrierung ... schneller voran, da noch 3.000 Gäste warten.'::text,'ginge'::text,'wird gehen'::text,'geht'::text,'Die Geschäftsleitung wünscht sich, die Registrierung ginge schneller voran, da noch 3.000 Gäste warten.'::text),
(379753,42195,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Керівництво хотіло б, щоб реєстрація ... швидше, бо ще 3000 гостей чекають.'::text,'просувалася'::text,'просуватиметься'::text,'просувається'::text,'Керівництво хотіло б, щоб реєстрація просувалася швидше, бо ще 3000 гостей чекають.'::text),
(379752,42195,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La dirección desearía que el registro ... más rápido, con 3.000 invitados aún esperando.'::text,'avanzara'::text,'avanzará'::text,'avanza'::text,'La dirección desearía que el registro avanzara más rápido, con 3.000 invitados aún esperando.'::text),
(379751,42195,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La direction aimerait que l''enregistrement ... plus vite, avec 3 000 invités qui attendent encore.'::text,'avance'::text,'avancera'::text,'avance'::text,'La direction aimerait que l''enregistrement avance plus vite, avec 3 000 invités qui attendent encore.'::text),
(379754,42195,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yönetim, 3.000 misafir hâlâ beklerken kaydın daha hızlı ... istiyor.'::text,'ilerlemesini'::text,'ilerleyeceğini'::text,'ilerlediğini'::text,'Yönetim, 3.000 misafir hâlâ beklerken kaydın daha hızlı ilerlemesini istiyor.'::text),
(379755,42195,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vezetőség azt szeretné, ha a regisztráció gyorsabban ..., mert még 3000 vendég vár.'::text,'haladna'::text,'fog haladni'::text,'halad'::text,'A vezetőség azt szeretné, ha a regisztráció gyorsabban haladna, mert még 3000 vendég vár.'::text),
(379758,42196,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gast, ... Name schon im Anmeldebuch stand, bekam als Erster sein Namensschild.'::text,'dessen'::text,'der'::text,'welcher'::text,'Der Gast, dessen Name schon im Anmeldebuch stand, bekam als Erster sein Namensschild.'::text),
(379762,42196,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гість, ... ім''я вже було в реєстраційній книзі, отримав бейдж першим.'::text,'чиє'::text,'який'::text,'що'::text,'Гість, чиє ім''я вже було в реєстраційній книзі, отримав бейдж першим.'::text),
(379761,42196,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El invitado, ... nombre ya estaba en el libro de registro, recibió su acreditación el primero.'::text,'cuyo'::text,'que'::text,'el cual'::text,'El invitado, cuyo nombre ya estaba en el libro de registro, recibió su acreditación el primero.'::text),
(379760,42196,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''invité, ... le nom était déjà dans le registre, a reçu son badge en premier.'::text,'dont'::text,'qui'::text,'lequel'::text,'L''invité, dont le nom était déjà dans le registre, a reçu son badge en premier.'::text),
(379763,42196,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İsmi zaten kayıt defterinde olan ... misafir, yaka kartını ilk alan oldu.'::text,''::text,NULL::text,NULL::text,'İsmi zaten kayıt defterinde olan misafir, yaka kartını ilk alan oldu.'::text),
(379764,42196,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vendég, ... neve már benne volt a regisztrációs könyvben, elsőként kapta meg a kitűzőjét.'::text,'akinek a'::text,'aki'::text,'amely'::text,'A vendég, akinek a neve már benne volt a regisztrációs könyvben, elsőként kapta meg a kitűzőjét.'::text),
(379767,42197,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Allgemeinen dauert ... auf großen Kongressen etwa zwei Minuten pro Gast.'::text,'die Registrierung'::text,'eine Registrierung'::text,'die Registrierungen'::text,'Im Allgemeinen dauert die Registrierung auf großen Kongressen etwa zwei Minuten pro Gast.'::text),
(379771,42197,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Загалом ... на великих з''їздах займає приблизно дві хвилини на гостя.'::text,'реєстрація'::text,'реєстрація'::text,'реєстрації'::text,'Загалом реєстрація на великих з''їздах займає приблизно дві хвилини на гостя.'::text),
(379770,42197,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En general, ... en los grandes congresos requiere aproximadamente dos minutos por invitado.'::text,'el registro'::text,'un registro'::text,'los registros'::text,'En general, el registro en los grandes congresos requiere aproximadamente dos minutos por invitado.'::text),
(379769,42197,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En général, ... dans les grands congrès prend environ deux minutes par invité.'::text,'l''enregistrement'::text,'un enregistrement'::text,'les enregistrements'::text,'En général, l''enregistrement dans les grands congrès prend environ deux minutes par invité.'::text),
(379772,42197,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genel olarak büyük kongrelerde ... misafir başına yaklaşık iki dakika sürer.'::text,'kayıt'::text,'bir kayıt'::text,'kayıtlar'::text,'Genel olarak büyük kongrelerde kayıt misafir başına yaklaşık iki dakika sürer.'::text),
(379773,42197,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában ... a nagy kongresszusokon vendégenként nagyjából két percet vesz igénybe.'::text,'a regisztráció'::text,'egy regisztráció'::text,'a regisztrációk'::text,'Általában a regisztráció a nagy kongresszusokon vendégenként nagyjából két percet vesz igénybe.'::text),
(379785,42199,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag wird die Registrierung komplett ..., und niemand sonst wird je ein Namensschild bekommen!'::text,'geschlossen haben'::text,'schließen'::text,'schließt'::text,'Bis Mittag wird die Registrierung komplett geschlossen haben, und niemand sonst wird je ein Namensschild bekommen!'::text),
(379789,42199,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До полудня реєстрація повністю ..., і більше ніхто ніколи не отримає бейдж!'::text,'закриється'::text,'закриється'::text,'закривається'::text,'До полудня реєстрація повністю закриється, і більше ніхто ніколи не отримає бейдж!'::text),
(379788,42199,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para el mediodía, el registro ... por completo y nadie más tendrá nunca una acreditación!'::text,'habrá cerrado'::text,'cerrará'::text,'cierra'::text,'¡Para el mediodía, el registro habrá cerrado por completo y nadie más tendrá nunca una acreditación!'::text),
(379787,42199,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici midi, l''enregistrement ... complètement, et plus personne n''aura jamais de badge !'::text,'aura fermé'::text,'fermera'::text,'ferme'::text,'D''ici midi, l''enregistrement aura fermé complètement, et plus personne n''aura jamais de badge !'::text),
(379790,42199,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar kayıt tamamen ... ve artık kimse asla yaka kartı alamayacak!'::text,'kapanmış olacak'::text,'kapanacak'::text,'kapanıyor'::text,'Öğlene kadar kayıt tamamen kapanmış olacak ve artık kimse asla yaka kartı alamayacak!'::text),
(379791,42199,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre a regisztráció teljesen ..., és soha többé senki nem kap kitűzőt!'::text,'le fog zárulni'::text,'le fog zárulni'::text,'lezárul'::text,'Délre a regisztráció teljesen le fog zárulni, és soha többé senki nem kap kitűzőt!'::text),
(393537,43727,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... gerade einen Klebezettel fürs Lernen, als sie überrascht aufblickte.'::text,'schrieb'::text,'schrieb'::text,'hat geschrieben'::text,'Sie schrieb gerade einen Klebezettel fürs Lernen, als sie überrascht aufblickte.'::text),
(393541,43727,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... стікер для навчання, коли здивовано підвела очі.'::text,'писала'::text,'написала'::text,'написала'::text,'Вона писала стікер для навчання, коли здивовано підвела очі.'::text),
(393540,43727,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... una nota adhesiva para su estudio cuando levantó la vista sorprendida.'::text,'Estaba escribiendo'::text,'Escribió'::text,'Ha escrito'::text,'Estaba escribiendo una nota adhesiva para su estudio cuando levantó la vista sorprendida.'::text),
(393539,43727,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... un post-it pour ses révisions quand elle a levé les yeux, surprise.'::text,'écrivait'::text,'a écrit'::text,'a écrit'::text,'Elle écrivait un post-it pour ses révisions quand elle a levé les yeux, surprise.'::text),
(393542,43727,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şaşkınlıkla başını kaldırdığında ders çalışması için yapışkan bir not ...'::text,'yazıyordu'::text,'yazdı'::text,'yazmış'::text,'Şaşkınlıkla başını kaldırdığında ders çalışması için yapışkan bir not yazıyordu.'::text),
(393543,43727,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp egy cetlit ... a tanuláshoz, amikor meglepetten felnézett.'::text,'írt'::text,'megírt'::text,'megírt'::text,'Épp egy cetlit írt a tanuláshoz, amikor meglepetten felnézett.'::text),
(393546,43728,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie weniger zu lernen hätte, ... die Bücher nicht bis zur Decke.'::text,'reichten'::text,'werden reichen'::text,'reichen'::text,'Wenn sie weniger zu lernen hätte, reichten die Bücher nicht bis zur Decke.'::text),
(393550,43728,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби їй треба було менше вчитися, книжки ... до стелі.'::text,'не сягали б'::text,'не сягатимуть'::text,'не сягають'::text,'Якби їй треба було менше вчитися, книжки не сягали б до стелі.'::text),
(393549,43728,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tuviera menos que estudiar, los libros no ... hasta el techo.'::text,'llegarían'::text,'llegarán'::text,'llegan'::text,'Si tuviera menos que estudiar, los libros no llegarían hasta el techo.'::text),
(393548,43728,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle avait moins à étudier, les livres ... jusqu''au plafond.'::text,'n''arriveraient pas'::text,'n''arriveront pas'::text,'n''arrivent pas'::text,'Si elle avait moins à étudier, les livres n''arriveraient pas jusqu''au plafond.'::text),
(393551,43728,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha az çalışması gerekseydi, kitaplar tavana kadar ...'::text,'ulaşmazdı'::text,'ulaşmayacak'::text,'ulaşmıyor'::text,'Daha az çalışması gerekseydi, kitaplar tavana kadar ulaşmazdı.'::text),
(393552,43728,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha kevesebbet kellene tanulnia, a könyvek nem ... a plafonig.'::text,'érnének fel'::text,'fognak felérni'::text,'érnek fel'::text,'Ha kevesebbet kellene tanulnia, a könyvek nem érnének fel a plafonig.'::text),
(393555,43729,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... jedes Buch fürs Lernen um sie herum auf dem Schreibtisch gestapelt.'::text,'war'::text,'ist'::text,'stapelte'::text,'Gestern war jedes Buch fürs Lernen um sie herum auf dem Schreibtisch gestapelt.'::text),
(393559,43729,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора кожна книжка для її навчання ... на столі навколо неї.'::text,'була складена'::text,'є складена'::text,'склала'::text,'Учора кожна книжка для її навчання була складена на столі навколо неї.'::text),
(393558,43729,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayer, cada libro de su estudio ... en el escritorio a su alrededor.'::text,'estaba apilado'::text,'está apilado'::text,'apiló'::text,'Ayer, cada libro de su estudio estaba apilado en el escritorio a su alrededor.'::text),
(393557,43729,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, chaque livre pour ses études ... sur le bureau autour d''elle.'::text,'était empilé'::text,'est empilé'::text,'a empilé'::text,'Hier, chaque livre pour ses études était empilé sur le bureau autour d''elle.'::text),
(393560,43729,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün çalışması için gereken her kitap etrafındaki masanın üstüne ...'::text,'yığılmıştı'::text,'yığılı'::text,'yığdı'::text,'Dün çalışması için gereken her kitap etrafındaki masanın üstüne yığılmıştı.'::text),
(393561,43729,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap a tanuláshoz szükséges összes könyv ... körülötte az íróasztalon.'::text,'fel volt halmozva'::text,'fel van halmozva'::text,'felhalmozott'::text,'Tegnap a tanuláshoz szükséges összes könyv fel volt halmozva körülötte az íróasztalon.'::text),
(393564,43730,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bücher sind zum Lernen da, also ... sie alle auf ihren Schreibtisch.'::text,'legte'::text,'wurde gelegt'::text,'legend'::text,'Bücher sind zum Lernen da, also legte sie alle auf ihren Schreibtisch.'::text),
(393568,43730,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Книжки для навчання, тому вона ... їх усі на стіл.'::text,'поклала'::text,'була покладена'::text,'кладучи'::text,'Книжки для навчання, тому вона поклала їх усі на стіл.'::text),
(393567,43730,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los libros son para estudiar, así que los ... todos en su escritorio.'::text,'puso'::text,'fue puesto'::text,'poniendo'::text,'Los libros son para estudiar, así que los puso todos en su escritorio.'::text),
(393566,43730,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les livres, c''est pour étudier, alors elle les ... tous sur son bureau.'::text,'a mis'::text,'a été mise'::text,'mettant'::text,'Les livres, c''est pour étudier, alors elle les a mis tous sur son bureau.'::text),
(393569,43730,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kitaplar ders çalışmak içindir, bu yüzden hepsini masasına ...'::text,'koydu'::text,'konuldu'::text,'koyarak'::text,'Kitaplar ders çalışmak içindir, bu yüzden hepsini masasına koydu.'::text),
(393570,43730,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A könyvek tanulásra valók, ezért mindet az asztalára ...'::text,'tette'::text,'lett téve'::text,'téve'::text,'A könyvek tanulásra valók, ezért mindet az asztalára tette.'::text),
(393573,43731,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Angesichts der Bücherwand ... das Lernen Jahre dauern, auch wenn das nicht dokumentiert ist.'::text,'könnte'::text,'muss'::text,'kann nicht'::text,'Angesichts der Bücherwand könnte das Lernen Jahre dauern, auch wenn das nicht dokumentiert ist.'::text),
(393577,43731,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'З огляду на стіну книжок, навчання ... тривати роками, хоча це не задокументовано.'::text,'може'::text,'мусить'::text,'не може'::text,'З огляду на стіну книжок, навчання може тривати роками, хоча це не задокументовано.'::text),
(393576,43731,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dado el muro de libros, el estudio ... llevar años, aunque esto no está documentado.'::text,'puede'::text,'debe de'::text,'no puede'::text,'Dado el muro de libros, el estudio puede llevar años, aunque esto no está documentado.'::text),
(393575,43731,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vu le mur de livres, l''étude ... prendre des années, bien que ce ne soit pas documenté.'::text,'peut'::text,'doit'::text,'ne peut pas'::text,'Vu le mur de livres, l''étude peut prendre des années, bien que ce ne soit pas documenté.'::text),
(393578,43731,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kitap duvarına bakılırsa, çalışma yıllar ..., ancak bu belgelenmemiş.'::text,'sürebilir'::text,'sürmeli'::text,'süremez'::text,'Kitap duvarına bakılırsa, çalışma yıllar sürebilir, ancak bu belgelenmemiş.'::text),
(393579,43731,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A könyvfalat nézve a tanulás évekig ..., bár ez nincs dokumentálva.'::text,'tarthat'::text,'biztosan tart'::text,'nem tarthat'::text,'A könyvfalat nézve a tanulás évekig tarthat, bár ez nincs dokumentálva.'::text),
(393582,43732,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Lernen, ... du in diese Bücher gesteckt hast? Respekt.'::text,'das'::text,'wer'::text,'dessen'::text,'Das Lernen, das du in diese Bücher gesteckt hast? Respekt.'::text),
(393586,43732,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Навчання, ... ти вклала в ці книжки? Респект.'::text,'яке'::text,'хто'::text,'чиє'::text,'Навчання, яке ти вклала в ці книжки? Респект.'::text),
(393585,43732,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿El estudio ... le has metido a estos libros? Respeto.'::text,'que'::text,'quien'::text,'cuyo'::text,'¿El estudio que le has metido a estos libros? Respeto.'::text),
(393584,43732,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''étude ... tu as mise dans ces livres ? Respect.'::text,'que'::text,'qui'::text,'dont'::text,'L''étude que tu as mise dans ces livres ? Respect.'::text),
(393587,43732,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu kitaplara ... harcadığın çalışma mı? Helal olsun.'::text,''::text,NULL::text,NULL::text,'Bu kitaplara harcadığın çalışma mı? Helal olsun.'::text),
(393588,43732,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tanulás, ... ezekbe a könyvekbe beletettél? Respekt.'::text,'amit'::text,'aki'::text,'akinek a'::text,'A tanulás, amit ezekbe a könyvekbe beletettél? Respekt.'::text),
(393591,43733,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast mir gesagt, dein Lernen ... letzte Woche fertig gewesen, aber ehrlich, du gibst immer noch Vollgas.'::text,'sei'::text,'ist'::text,'ist'::text,'Du hast mir gesagt, dein Lernen sei letzte Woche fertig gewesen, aber ehrlich, du gibst immer noch Vollgas.'::text),
(393595,43733,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти казала, що твоє навчання ... завершене минулого тижня, але чесно, ти досі в ділі.'::text,'було'::text,'було'::text,'є'::text,'Ти казала, що твоє навчання було завершене минулого тижня, але чесно, ти досі в ділі.'::text),
(393594,43733,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Me dijiste que tu estudio ... terminado la semana pasada, pero, sinceramente, sigues a tope.'::text,'había quedado'::text,'ha quedado'::text,'está'::text,'Me dijiste que tu estudio había quedado terminado la semana pasada, pero, sinceramente, sigues a tope.'::text),
(393593,43733,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu m''as dit que tes révisions ... finies la semaine dernière, mais franchement, tu tiens toujours la cadence.'::text,'avaient été'::text,'ont été'::text,'sont'::text,'Tu m''as dit que tes révisions avaient été finies la semaine dernière, mais franchement, tu tiens toujours la cadence.'::text),
(393596,43733,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bana çalışmanın geçen hafta ... söyledin ama açıkçası hâlâ tam gaz devam ediyorsun.'::text,'bittiğini'::text,'bittiğini'::text,'bittiğini'::text,'Bana çalışmanın geçen hafta bittiğini söyledin ama açıkçası hâlâ tam gaz devam ediyorsun.'::text),
(393597,43733,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondtad, hogy a tanulásod már múlt héten ..., de őszintén, még mindig teljes gőzzel nyomod.'::text,'befejeződött'::text,'befejeződött'::text,'befejeződik'::text,'Azt mondtad, hogy a tanulásod már múlt héten befejeződött, de őszintén, még mindig teljes gőzzel nyomod.'::text),
(393600,43734,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... das Lernen, und jetzt bist du von Büchern umgeben? Beeindruckt.'::text,'hasstest früher'::text,'hasstest immer'::text,'warst es gewohnt zu hassen'::text,'Du hasstest früher das Lernen, und jetzt bist du von Büchern umgeben? Beeindruckt.'::text),
(393604,43734,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... навчання, а тепер оточена книжками? Вражає.'::text,'колись ненавиділа'::text,'бувало, ненавиділа'::text,'звикла ненавидіти'::text,'Ти колись ненавиділа навчання, а тепер оточена книжками? Вражає.'::text),
(393603,43734,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Tú ... el estudio y ahora estás rodeada de libros? Me impresionas.'::text,'solías odiar'::text,'odiabas'::text,'estabas acostumbrada a odiar'::text,'¿Tú solías odiar el estudio y ahora estás rodeada de libros? Me impresionas.'::text),
(393602,43734,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... les études, et maintenant tu es entourée de livres ? Impressionné.'::text,'détestais avant'::text,'détestais souvent'::text,'avais l''habitude de détester'::text,'Tu détestais avant les études, et maintenant tu es entourée de livres ? Impressionné.'::text),
(393605,43734,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden ders çalışmaktan ..., şimdi de kitaplarla çevrili misin? Etkilendim.'::text,'nefret ederdin'::text,'nefret ederdin'::text,'nefret etmeye alışkındın'::text,'Eskiden ders çalışmaktan nefret ederdin, şimdi de kitaplarla çevrili misin? Etkilendim.'::text),
(393606,43734,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen ... a tanulást, most meg könyvek vesznek körül? Lenyűgöző.'::text,'utáltad'::text,'utáltad'::text,'hozzá voltál szokva utálni'::text,'Régen utáltad a tanulást, most meg könyvek vesznek körül? Lenyűgöző.'::text),
(393618,43736,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... ihr Lernen etwa 2.000 Bücher. Leichte Lektüre, offensichtlich.'::text,'umfasst'::text,'umfasst gerade'::text,'hat umfasst'::text,'Gerade umfasst ihr Lernen etwa 2.000 Bücher. Leichte Lektüre, offensichtlich.'::text),
(393622,43736,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зараз її навчання ... близько 2000 книжок. Легке читання, звісно.'::text,'охоплює'::text,'охоплює'::text,'охопило'::text,'Зараз її навчання охоплює близько 2000 книжок. Легке читання, звісно.'::text),
(393621,43736,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo su estudio ... unos 2.000 libros. Lectura ligera, obviamente.'::text,'abarca'::text,'está abarcando'::text,'ha abarcado'::text,'Ahora mismo su estudio abarca unos 2.000 libros. Lectura ligera, obviamente.'::text),
(393620,43736,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, ses révisions ... environ 2 000 livres. Une lecture légère, évidemment.'::text,'comprennent'::text,'sont en train de comprendre'::text,'ont compris'::text,'En ce moment, ses révisions comprennent environ 2 000 livres. Une lecture légère, évidemment.'::text),
(393623,43736,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda çalışması yaklaşık 2.000 kitabı ..., hafif bir okuma tabii.'::text,'kapsıyor'::text,'kapsıyor'::text,'kapsadı'::text,'Şu anda çalışması yaklaşık 2.000 kitabı kapsıyor, hafif bir okuma tabii.'::text),
(393624,43736,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most a tanulása ... nagyjából 2000 könyvet. Könnyű olvasmány, nyilván.'::text,'felölel'::text,'felölel'::text,'felölelt'::text,'Épp most a tanulása felölel nagyjából 2000 könyvet. Könnyű olvasmány, nyilván.'::text),
(373971,41553,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, er ... angeblich seit einem Monat jeden Morgen von dem Steg.'::text,'springt'::text,'springt gerade'::text,'springt'::text,'Bestie, er springt angeblich seit einem Monat jeden Morgen von dem Steg.'::text),
(373975,41553,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він уже місяць щоранку ... з того пірса.'::text,'стрибає'::text,'стрибає'::text,'стрибає'::text,'Подруго, кажуть, він уже місяць щоранку стрибає з того пірса.'::text),
(373974,41553,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer ... desde ese muelle todas las mañanas desde hace un mes.'::text,'lleva tirándose'::text,'se está tirando'::text,'se tira'::text,'Amiga, al parecer lleva tirándose desde ese muelle todas las mañanas desde hace un mes.'::text),
(373973,41553,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment il ... de ce ponton tous les matins depuis un mois.'::text,'plonge'::text,'est en train de plonger'::text,'plonge'::text,'Ma belle, apparemment il plonge de ce ponton tous les matins depuis un mois.'::text),
(373976,41553,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre bir aydır her sabah o iskeleden ...'::text,'atlıyormuş'::text,'atlıyormuş'::text,'atlarmış'::text,'Kanka, duyduğuma göre bir aydır her sabah o iskeleden atlıyormuş.'::text),
(373977,41553,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag egy hónapja minden reggel ... arról a mólóról.'::text,'ugrál'::text,'ugrál'::text,'ugrik'::text,'Csajszi, állítólag egy hónapja minden reggel ugrál arról a mólóról.'::text),
(373980,41554,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... gerade vom Steg, als ihm fast die Shorts runterrutschten. Ein makelloser Sprung.'::text,'sprang'::text,'sprang'::text,'ist gesprungen'::text,'Er sprang gerade vom Steg, als ihm fast die Shorts runterrutschten. Ein makelloser Sprung.'::text),
(373984,41554,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... з пірса, коли з нього мало не злетіли шорти. Бездоганний стрибок.'::text,'стрибав'::text,'стрибнув'::text,'стрибнув'::text,'Він стрибав з пірса, коли з нього мало не злетіли шорти. Бездоганний стрибок.'::text),
(373983,41554,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... desde el muelle cuando casi se le caen los pantalones cortos. Un salto impecable.'::text,'Estaba saltando'::text,'Saltó'::text,'Ha saltado'::text,'Estaba saltando desde el muelle cuando casi se le caen los pantalones cortos. Un salto impecable.'::text),
(373982,41554,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... du ponton quand son short a failli tomber. Un plongeon parfait.'::text,'plongeait'::text,'a plongé'::text,'a plongé'::text,'Il plongeait du ponton quand son short a failli tomber. Un plongeon parfait.'::text),
(373985,41554,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şortu neredeyse çıktığı anda o iskeleden ..., kusursuz bir atlayış.'::text,'atlıyordu'::text,'atladı'::text,'atlamış'::text,'Şortu neredeyse çıktığı anda o iskeleden atlıyordu, kusursuz bir atlayış.'::text),
(373986,41554,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... a mólóról, amikor majdnem lecsúszott róla a rövidnadrág. Hibátlan ugrás.'::text,'ugrott'::text,'leugrott'::text,'leugrott'::text,'Épp ugrott a mólóról, amikor majdnem lecsúszott róla a rövidnadrág. Hibátlan ugrás.'::text),
(373989,41555,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich ein entspannter Morgen: Er ... bisher neunmal vom Steg gesprungen.'::text,'ist'::text,'ist'::text,'springt'::text,'Offensichtlich ein entspannter Morgen: Er ist bisher neunmal vom Steg gesprungen.'::text),
(373993,41555,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно розслабляючий ранок: він уже ... з пірса дев''ять разів.'::text,'стрибнув'::text,'стрибав'::text,'стрибає'::text,'Явно розслабляючий ранок: він уже стрибнув з пірса дев''ять разів.'::text),
(373992,41555,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una mañana relajante, obviamente: ... del muelle nueve veces hasta ahora.'::text,'se ha tirado'::text,'lleva tirándose'::text,'se está tirando'::text,'Una mañana relajante, obviamente: se ha tirado del muelle nueve veces hasta ahora.'::text),
(373991,41555,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une matinée reposante, évidemment : il ... du ponton neuf fois jusqu''ici.'::text,'a plongé'::text,'a plongé'::text,'plonge'::text,'Une matinée reposante, évidemment : il a plongé du ponton neuf fois jusqu''ici.'::text),
(373994,41555,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki rahatlatıcı bir sabah: şu ana kadar iskeleden dokuz kez ...'::text,'atladı'::text,'atlıyor'::text,'atlıyor'::text,'Belli ki rahatlatıcı bir sabah: şu ana kadar iskeleden dokuz kez atladı.'::text),
(373995,41555,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván egy pihentető reggel: eddig kilencszer ... a mólóról.'::text,'ugrott le'::text,'ugrált'::text,'ugrál'::text,'Nyilván egy pihentető reggel: eddig kilencszer ugrott le a mólóról.'::text),
(374007,41557,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, wenn die ganze Crowd gleichzeitig von dem Steg springt, ... der Platscher krass, ehrlich.'::text,'wird'::text,'wäre'::text,'war'::text,'Yo, wenn die ganze Crowd gleichzeitig von dem Steg springt, wird der Platscher krass, ehrlich.'::text),
(374011,41557,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, якщо весь натовп разом стрибне з того пірса, сплеск ... шалений, чесно.'::text,'буде'::text,'був би'::text,'був'::text,'Йо, якщо весь натовп разом стрибне з того пірса, сплеск буде шалений, чесно.'::text),
(374010,41557,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, si toda la gente salta de ese muelle a la vez, el chapuzón ... una locura, en serio.'::text,'será'::text,'sería'::text,'fue'::text,'Oye, si toda la gente salta de ese muelle a la vez, el chapuzón será una locura, en serio.'::text),
(374009,41557,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, si toute la foule saute de ce ponton en même temps, les éclaboussures ... dingues, sérieux.'::text,'seront'::text,'seraient'::text,'étaient'::text,'Yo, si toute la foule saute de ce ponton en même temps, les éclaboussures seront dingues, sérieux.'::text),
(374012,41557,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bütün kalabalık aynı anda o iskeleden atlarsa su sıçraması çılgınca ..., cidden.'::text,'olacak'::text,'olurdu'::text,'oldu'::text,'Kanka, bütün kalabalık aynı anda o iskeleden atlarsa su sıçraması çılgınca olacak, cidden.'::text),
(374013,41557,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha az egész tömeg egyszerre ugrik le arról a mólóról, a csobbanás őrült ..., komolyan.'::text,'lesz'::text,'lenne'::text,'volt'::text,'Tesó, ha az egész tömeg egyszerre ugrik le arról a mólóról, a csobbanás őrült lesz, komolyan.'::text),
(374016,41558,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre der Steg 20 Meter länger, ... auch der Umsatz des Resorts.'::text,'stiege'::text,'wird steigen'::text,'steigt'::text,'Wäre der Steg 20 Meter länger, stiege auch der Umsatz des Resorts.'::text),
(374020,41558,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби пірс був на 20 метрів довшим, дохід курорту також ...'::text,'зріс би'::text,'зросте'::text,'зростає'::text,'Якби пірс був на 20 метрів довшим, дохід курорту також зріс би.'::text),
(374019,41558,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el muelle fuera 20 metros más largo, los ingresos del resort también ...'::text,'crecerían'::text,'crecerán'::text,'crecen'::text,'Si el muelle fuera 20 metros más largo, los ingresos del resort también crecerían.'::text),
(374018,41558,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le ponton faisait 20 mètres de plus, le chiffre d''affaires du complexe ... aussi.'::text,'augmenterait'::text,'augmentera'::text,'augmente'::text,'Si le ponton faisait 20 mètres de plus, le chiffre d''affaires du complexe augmenterait aussi.'::text),
(374021,41558,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İskele 20 metre daha uzun olsaydı, tesisin geliri de ...'::text,'artardı'::text,'artacak'::text,'artıyor'::text,'İskele 20 metre daha uzun olsaydı, tesisin geliri de artardı.'::text),
(374022,41558,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a móló 20 méterrel hosszabb lenne, az üdülő bevétele is ...'::text,'nőne'::text,'nőni fog'::text,'nő'::text,'Ha a móló 20 méterrel hosszabb lenne, az üdülő bevétele is nőne.'::text),
(374025,41559,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der lange Holzsteg ... vor vielen Jahren über dem Wasser gebaut.'::text,'wurde'::text,'wird'::text,'baute'::text,'Der lange Holzsteg wurde vor vielen Jahren über dem Wasser gebaut.'::text),
(374029,41559,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Довгий дерев''яний пірс ... над водою багато років тому.'::text,'був збудований'::text,'будується'::text,'збудував'::text,'Довгий дерев''яний пірс був збудований над водою багато років тому.'::text),
(374028,41559,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El largo muelle de madera ... sobre el agua hace muchos años.'::text,'fue construido'::text,'es construido'::text,'construyó'::text,'El largo muelle de madera fue construido sobre el agua hace muchos años.'::text),
(374027,41559,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le long ponton en bois ... au-dessus de l''eau il y a de nombreuses années.'::text,'a été construit'::text,'est construit'::text,'a construit'::text,'Le long ponton en bois a été construit au-dessus de l''eau il y a de nombreuses années.'::text),
(374030,41559,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uzun ahşap iskele yıllar önce suyun üzerine ...'::text,'inşa edildi'::text,'inşa ediliyor'::text,'inşa etti'::text,'Uzun ahşap iskele yıllar önce suyun üzerine inşa edildi.'::text),
(374031,41559,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hosszú fa mólót sok évvel ezelőtt ... a víz fölé.'::text,'építették'::text,'építik'::text,'épített'::text,'A hosszú fa mólót sok évvel ezelőtt építették a víz fölé.'::text),
(374034,41560,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dutzende Schwimmer ... gleichzeitig vom Steg ins türkisfarbene Wasser.'::text,'sprangen'::text,'sprangen'::text,'springend'::text,'Dutzende Schwimmer sprangen gleichzeitig vom Steg ins türkisfarbene Wasser.'::text),
(374038,41560,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Десятки плавців одночасно ... з пірса в бірюзову воду.'::text,'стрибнули'::text,'стрибнули'::text,'стрибаючи'::text,'Десятки плавців одночасно стрибнули з пірса в бірюзову воду.'::text),
(374037,41560,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Decenas de nadadores ... a la vez del muelle al agua turquesa.'::text,'saltaron'::text,'saltaron'::text,'saltando'::text,'Decenas de nadadores saltaron a la vez del muelle al agua turquesa.'::text),
(374036,41560,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Des dizaines de nageurs ... en même temps du ponton dans l''eau turquoise.'::text,'ont sauté'::text,'ont sauté'::text,'sautant'::text,'Des dizaines de nageurs ont sauté en même temps du ponton dans l''eau turquoise.'::text),
(374039,41560,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlarca yüzücü aynı anda iskeleden turkuaz suya ...'::text,'atladı'::text,'atladı'::text,'atlayarak'::text,'Onlarca yüzücü aynı anda iskeleden turkuaz suya atladı.'::text),
(374040,41560,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tucatnyi úszó egyszerre ... a mólóról a türkiz vízbe.'::text,'ugrott'::text,'ugrott'::text,'ugorva'::text,'Tucatnyi úszó egyszerre ugrott a mólóról a türkiz vízbe.'::text),
(374043,41561,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Wasser unter dem Steg ... tief sein, weil die Leute kopfüber hineinspringen.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Das Wasser unter dem Steg muss tief sein, weil die Leute kopfüber hineinspringen.'::text),
(374047,41561,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вода під пірсом ... бути глибокою, бо люди стрибають у неї головою вниз.'::text,'має'::text,'не може'::text,'не повинна'::text,'Вода під пірсом має бути глибокою, бо люди стрибають у неї головою вниз.'::text),
(374046,41561,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El agua bajo el muelle ... ser profunda, porque la gente se tira de cabeza.'::text,'debe de'::text,'no puede'::text,'no debe'::text,'El agua bajo el muelle debe de ser profunda, porque la gente se tira de cabeza.'::text),
(374045,41561,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''eau sous le ponton ... être profonde, car les gens y plongent la tête la première.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'L''eau sous le ponton doit être profonde, car les gens y plongent la tête la première.'::text),
(374048,41561,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İskelenin altındaki su derin ..., çünkü insanlar oraya baş aşağı atlıyor.'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'İskelenin altındaki su derin olmalı, çünkü insanlar oraya baş aşağı atlıyor.'::text),
(374049,41561,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A móló alatt a víznek mélynek ... lennie, mert az emberek fejest ugranak bele.'::text,'kell'::text,'nem lehet'::text,'nem szabad'::text,'A móló alatt a víznek mélynek kell lennie, mert az emberek fejest ugranak bele.'::text),
(374052,41562,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also der Typ, ... als Erster vom Steg gesprungen ist, hat das angeblich schon hundertmal gemacht.'::text,'der'::text,'was'::text,'dessen'::text,'Okay, also der Typ, der als Erster vom Steg gesprungen ist, hat das angeblich schon hundertmal gemacht.'::text),
(374056,41562,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, хлопець, ... першим стрибнув з пірса, вже робив це сотню разів, кажуть.'::text,'який'::text,'що'::text,'чий'::text,'Коротше, хлопець, який першим стрибнув з пірса, вже робив це сотню разів, кажуть.'::text),
(374055,41562,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues el chico ... se tiró primero del muelle lo ha hecho cien veces, al parecer.'::text,'que'::text,'el cual'::text,'cuyo'::text,'Vale, pues el chico que se tiró primero del muelle lo ha hecho cien veces, al parecer.'::text),
(374054,41562,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, alors le mec ... a plongé du ponton en premier l''a déjà fait cent fois, apparemment.'::text,'qui'::text,'lequel'::text,'dont'::text,'Bon, alors le mec qui a plongé du ponton en premier l''a déjà fait cent fois, apparemment.'::text),
(374057,41562,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, iskeleden ilk atlayan ... çocuk bunu yüz kez yapmış güya.'::text,''::text,NULL::text,NULL::text,'Tamam, iskeleden ilk atlayan çocuk bunu yüz kez yapmış güya.'::text),
(374058,41562,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval az a srác, ... elsőként ugrott le a mólóról, állítólag már százszor csinálta.'::text,'aki'::text,'amely'::text,'akinek a'::text,'Szóval az a srác, aki elsőként ugrott le a mólóról, állítólag már százszor csinálta.'::text),
(374061,41563,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir gesagt, das Wasser am Steg ... eiskalt.'::text,'sei'::text,'werde gerade'::text,'seien'::text,'Hör zu, er hat mir gesagt, das Wasser am Steg sei eiskalt.'::text),
(374065,41563,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що вода біля пірса ... крижана.'::text,'була'::text,'є'::text,'були'::text,'Слухай, він сказав мені, що вода біля пірса була крижана.'::text),
(374064,41563,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que el agua cerca del muelle ... helada.'::text,'estaba'::text,'está siendo'::text,'estaban'::text,'Oye, me dijo que el agua cerca del muelle estaba helada.'::text),
(374063,41563,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit que l''eau près du ponton ... glaciale.'::text,'était'::text,'est en train d''être'::text,'étaient'::text,'Écoute, il m''a dit que l''eau près du ponton était glaciale.'::text),
(374066,41563,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana iskelenin yanındaki suyun buz gibi ... söyledi.'::text,'olduğunu'::text,'olmakta olduğunu'::text,'olduklarını'::text,'Dinle, bana iskelenin yanındaki suyun buz gibi olduğunu söyledi.'::text),
(374067,41563,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy a mólónál a víz jéghideg ...'::text,'volt'::text,NULL::text,'voltak'::text,'Figyelj, azt mondta, hogy a mólónál a víz jéghideg volt.'::text),
(341598,37956,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie das Auto hebt, ... sie den Wettkampf.'::text,'gewinnt'::text,'würde gewinnen'::text,'gewann'::text,'Wenn sie das Auto hebt, gewinnt sie den Wettkampf.'::text),
(341602,37956,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона підніме машину, то ... змагання.'::text,'виграє'::text,'виграла б'::text,'виграла'::text,'Якщо вона підніме машину, то виграє змагання.'::text),
(341601,37956,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si levanta el coche, ... la competición.'::text,'ganará'::text,'ganaría'::text,'ganó'::text,'Si levanta el coche, ganará la competición.'::text),
(341600,37956,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle soulève la voiture, elle ... la compétition.'::text,'gagnera'::text,'gagnerait'::text,'a gagné'::text,'Si elle soulève la voiture, elle gagnera la compétition.'::text),
(341603,37956,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arabayı kaldırırsa yarışmayı ...'::text,'kazanacak'::text,'kazanırdı'::text,'kazandı'::text,'Arabayı kaldırırsa yarışmayı kazanacak.'::text),
(341604,37956,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha felemeli az autót, ... a versenyt.'::text,'megnyeri'::text,'megnyerné'::text,'megnyerte'::text,'Ha felemeli az autót, megnyeri a versenyt.'::text),
(341607,37957,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte der Wettkampf kein Publikum, ... er viel ruhiger.'::text,'wäre'::text,'wird'::text,'ist'::text,'Hätte der Wettkampf kein Publikum, wäre er viel ruhiger.'::text),
(341611,37957,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби на змаганні не було глядачів, воно ... набагато тихішим.'::text,'було б'::text,'буде'::text,'є'::text,'Якби на змаганні не було глядачів, воно було б набагато тихішим.'::text),
(341610,37957,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la competición no tuviera público, ... mucho más tranquila.'::text,'sería'::text,'será'::text,'es'::text,'Si la competición no tuviera público, sería mucho más tranquila.'::text),
(341609,37957,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la compétition n''avait pas de public, elle ... beaucoup plus calme.'::text,'serait'::text,'sera'::text,'est'::text,'Si la compétition n''avait pas de public, elle serait beaucoup plus calme.'::text),
(341612,37957,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarışmada seyirci olmasaydı, çok daha sessiz ...'::text,'olurdu'::text,'olacak'::text,NULL::text,'Yarışmada seyirci olmasaydı, çok daha sessiz olurdu.'::text),
(341613,37957,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a versenyen nem lenne közönség, sokkal csendesebb ...'::text,'lenne'::text,'lesz'::text,NULL::text,'Ha a versenyen nem lenne közönség, sokkal csendesebb lenne.'::text),
(341616,37958,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Wettkampf wird draußen auf einem Hebepodest ...'::text,'ausgetragen'::text,'austragen'::text,'gehalten'::text,'Der Wettkampf wird draußen auf einem Hebepodest ausgetragen.'::text),
(341620,37958,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Змагання ... надворі на помості для важкої атлетики.'::text,'проводять'::text,'проводить'::text,'проведене'::text,'Змагання проводять надворі на помості для важкої атлетики.'::text),
(341619,37958,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La competición ... al aire libre sobre una plataforma de levantamiento.'::text,'se celebra'::text,'celebra'::text,'celebrada'::text,'La competición se celebra al aire libre sobre una plataforma de levantamiento.'::text),
(341618,37958,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La compétition ... en plein air sur une plateforme d''haltérophilie.'::text,'est organisée'::text,'organise'::text,'organisée'::text,'La compétition est organisée en plein air sur une plateforme d''haltérophilie.'::text),
(341621,37958,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarışma açık havada bir kaldırma platformunda ...'::text,'düzenleniyor'::text,'düzenliyor'::text,'düzenlendi'::text,'Yarışma açık havada bir kaldırma platformunda düzenleniyor.'::text),
(341622,37958,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A versenyt a szabadban, egy emelőpódiumon ...'::text,'rendezik'::text,'rendez'::text,'rendezett'::text,'A versenyt a szabadban, egy emelőpódiumon rendezik.'::text),
(341625,37959,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... während des Wettkampfs einen Stein über den Kopf.'::text,'stemmte'::text,'wurde gestemmt'::text,'stemmend'::text,'Sie stemmte während des Wettkampfs einen Stein über den Kopf.'::text),
(341629,37959,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Під час змагання вона ... камінь над головою.'::text,'виштовхнула'::text,'була виштовхнута'::text,'штовхаючи'::text,'Під час змагання вона виштовхнула камінь над головою.'::text),
(341628,37959,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Durante la competición, ... una piedra por encima de la cabeza.'::text,'empujó'::text,'fue empujada'::text,'empujando'::text,'Durante la competición, empujó una piedra por encima de la cabeza.'::text),
(341627,37959,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant la compétition, elle ... une pierre au-dessus de sa tête.'::text,'a poussé'::text,'a été poussée'::text,'poussant'::text,'Pendant la compétition, elle a poussé une pierre au-dessus de sa tête.'::text),
(341630,37959,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarışma sırasında bir taşı başının üstüne ...'::text,'itti'::text,'itildi'::text,'iterek'::text,'Yarışma sırasında bir taşı başının üstüne itti.'::text),
(341631,37959,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A verseny alatt egy követ ... a feje fölé.'::text,'nyomott'::text,'lett nyomva'::text,'nyomva'::text,'A verseny alatt egy követ nyomott a feje fölé.'::text),
(341634,37960,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... sehr stark sein, wenn sie in diesem Wettkampf ein Auto hebt.'::text,'muss'::text,'kann nicht'::text,'muss nicht'::text,'Sie muss sehr stark sein, wenn sie in diesem Wettkampf ein Auto hebt.'::text),
(341638,37960,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... бути дуже сильною, щоб піднімати машину на цьому змаганні.'::text,'має'::text,'не може'::text,'не мусить'::text,'Вона має бути дуже сильною, щоб піднімати машину на цьому змаганні.'::text),
(341637,37960,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ser muy fuerte para levantar un coche en esta competición.'::text,'Debe de'::text,'No puede'::text,'No necesita'::text,'Debe de ser muy fuerte para levantar un coche en esta competición.'::text),
(341636,37960,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... être très forte pour soulever une voiture dans cette compétition.'::text,'doit'::text,'ne peut pas'::text,'n''a pas besoin de'::text,'Elle doit être très forte pour soulever une voiture dans cette compétition.'::text),
(341639,37960,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu yarışmada araba kaldırmak için çok güçlü ...'::text,'olmalı'::text,'olamaz'::text,'olması gerekmez'::text,'Bu yarışmada araba kaldırmak için çok güçlü olmalı.'::text),
(341640,37960,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon erősnek ... lennie, hogy autót emeljen ezen a versenyen.'::text,'kell'::text,'nem lehet'::text,'nem kell'::text,'Nagyon erősnek kell lennie, hogy autót emeljen ezen a versenyen.'::text),
(341643,37961,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Wettkampf, ... sie bestreitet, umfasst einen Stein, einen Baumstamm und ein Auto.'::text,'den'::text,'wer'::text,'dessen'::text,'Der Wettkampf, den sie bestreitet, umfasst einen Stein, einen Baumstamm und ein Auto.'::text),
(341647,37961,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Змагання, ... вона проходить, включає камінь, стовбур дерева й машину.'::text,'яке'::text,'хто'::text,'чиє'::text,'Змагання, яке вона проходить, включає камінь, стовбур дерева й машину.'::text),
(341646,37961,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La competición ... está haciendo incluye una piedra, un tronco y un coche.'::text,'que'::text,'quien'::text,'cuya'::text,'La competición que está haciendo incluye una piedra, un tronco y un coche.'::text),
(341645,37961,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La compétition ... elle participe comprend une pierre, un tronc d''arbre et une voiture.'::text,'à laquelle'::text,'qui'::text,'dont'::text,'La compétition à laquelle elle participe comprend une pierre, un tronc d''arbre et une voiture.'::text),
(341648,37961,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katıldığı ... yarışma bir taş, bir ağaç gövdesi ve bir araba içeriyor.'::text,''::text,NULL::text,NULL::text,'Katıldığı yarışma bir taş, bir ağaç gövdesi ve bir araba içeriyor.'::text),
(341649,37961,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A verseny, ... csinál, egy követ, egy fatörzset és egy autót tartalmaz.'::text,'amit'::text,'aki'::text,'akinek a'::text,'A verseny, amit csinál, egy követ, egy fatörzset és egy autót tartalmaz.'::text),
(341652,37962,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kampfrichter sagte, dass der Wettkampf in zehn Minuten ...'::text,'enden würde'::text,'enden wird'::text,'endet'::text,'Der Kampfrichter sagte, dass der Wettkampf in zehn Minuten enden würde.'::text),
(341656,37962,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Суддя сказав, що змагання ... за десять хвилин.'::text,'закінчиться'::text,'закінчиться'::text,'закінчується'::text,'Суддя сказав, що змагання закінчиться за десять хвилин.'::text),
(341655,37962,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El juez dijo que la competición ... en diez minutos.'::text,'terminaría'::text,'terminará'::text,'termina'::text,'El juez dijo que la competición terminaría en diez minutos.'::text),
(341654,37962,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le juge a dit que la compétition ... dans dix minutes.'::text,'se terminerait'::text,'se terminera'::text,'se termine'::text,'Le juge a dit que la compétition se terminerait dans dix minutes.'::text),
(341657,37962,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hakem, yarışmanın on dakika içinde ... söyledi.'::text,'biteceğini'::text,'biteceğini'::text,'bittiğini'::text,'Hakem, yarışmanın on dakika içinde biteceğini söyledi.'::text),
(341658,37962,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bíró azt mondta, hogy a verseny tíz perc múlva ...'::text,'véget ér'::text,'véget fog érni'::text,'véget ér'::text,'A bíró azt mondta, hogy a verseny tíz perc múlva véget ér.'::text),
(341661,37963,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor diesem Wettkampf ... Angst vor schweren Gewichten. Offensichtlich.'::text,'hatte sie früher'::text,'hatte sie immer wieder'::text,'war sie es gewohnt'::text,'Vor diesem Wettkampf hatte sie früher Angst vor schweren Gewichten. Offensichtlich.'::text),
(341665,37963,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До цього змагання вона ... важких ваг. Очевидно.'::text,'колись боялася'::text,'бувало, боялася'::text,'звикла боятися'::text,'До цього змагання вона колись боялася важких ваг. Очевидно.'::text),
(341664,37963,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de esta competición, ... miedo a los grandes pesos. Obviamente.'::text,'solía tener'::text,'tenía'::text,'estaba acostumbrada a tener'::text,'Antes de esta competición, solía tener miedo a los grandes pesos. Obviamente.'::text),
(341663,37963,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant cette compétition, elle ... peur des charges lourdes. Évidemment.'::text,'avait'::text,'avait souvent'::text,'avait l''habitude d''avoir'::text,'Avant cette compétition, elle avait peur des charges lourdes. Évidemment.'::text),
(341666,37963,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu yarışmadan önce ağır ağırlıklardan ..., belli ki.'::text,'korkardı'::text,'korkardı'::text,'korkmaya alışkındı'::text,'Bu yarışmadan önce ağır ağırlıklardan korkardı, belli ki.'::text),
(341667,37963,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'E verseny előtt ... a nehéz súlyoktól. Nyilván.'::text,'régen félt'::text,'félt'::text,'hozzá volt szokva félni'::text,'E verseny előtt régen félt a nehéz súlyoktól. Nyilván.'::text),
(341670,37964,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie willigte ein, beim Wettkampf ein kleines Auto ..., ein etwas schwerer Abschluss.'::text,'zu heben'::text,'Heben'::text,'heben'::text,'Sie willigte ein, beim Wettkampf ein kleines Auto zu heben, ein etwas schwerer Abschluss.'::text),
(341674,37964,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона погодилася ... невелику машину на змаганні. Трохи важкий фінал.'::text,'підняти'::text,'піднімання'::text,'підняти'::text,'Вона погодилася підняти невелику машину на змаганні. Трохи важкий фінал.'::text),
(341673,37964,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aceptó ... un coche pequeño en la competición. Un final un poco pesado.'::text,'levantar'::text,'levantando'::text,'levantar'::text,'Aceptó levantar un coche pequeño en la competición. Un final un poco pesado.'::text),
(341672,37964,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a accepté ... une petite voiture à la compétition. Une fin un peu lourde.'::text,'de soulever'::text,'soulevant'::text,'soulever'::text,'Elle a accepté de soulever une petite voiture à la compétition. Une fin un peu lourde.'::text),
(341675,37964,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarışmada küçük bir araba ... kabul etti. Biraz ağır bir final.'::text,'kaldırmayı'::text,'kaldırmayı'::text,'kaldırmak'::text,'Yarışmada küçük bir araba kaldırmayı kabul etti. Biraz ağır bir final.'::text),
(341676,37964,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beleegyezett, hogy a versenyen ... egy kis autót. Kicsit nehéz befejezés.'::text,'felemeljen'::text,'felemelés'::text,'felemel'::text,'Beleegyezett, hogy a versenyen felemeljen egy kis autót. Kicsit nehéz befejezés.'::text),
(329583,36621,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während das Team das Flugzeug ..., bewegte es sich, weil sie es zogen.'::text,'zog'::text,'zog'::text,'gezogen hat'::text,'Während das Team das Flugzeug zog, bewegte es sich, weil sie es zogen.'::text),
(329587,36621,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки команда ... літак, він рухався, бо його тягнули.'::text,'тягнула'::text,'потягнула'::text,'потягнула'::text,'Поки команда тягнула літак, він рухався, бо його тягнули.'::text),
(329586,36621,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras el equipo ... el avión, este se movió porque lo arrastraban.'::text,'arrastraba'::text,'arrastró'::text,'ha arrastrado'::text,'Mientras el equipo arrastraba el avión, este se movió porque lo arrastraban.'::text),
(329585,36621,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que l''équipe ... l''avion, il a bougé parce qu''ils le tiraient.'::text,'tirait'::text,'a tiré'::text,'a tiré'::text,'Pendant que l''équipe tirait l''avion, il a bougé parce qu''ils le tiraient.'::text),
(329588,36621,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekip uçağı ..., uçak hareket etti çünkü onu çektiler.'::text,'çekerken'::text,'çekti'::text,'çekmiş'::text,'Ekip uçağı çekerken, uçak hareket etti çünkü onu çektiler.'::text),
(329589,36621,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a csapat ... a repülőt, az megmozdult, mert húzták.'::text,'húzta'::text,'meghúzta'::text,'meghúzta'::text,'Miközben a csapat húzta a repülőt, az megmozdult, mert húzták.'::text),
(329592,36622,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Team ... das Flugzeug seit etwa zwei Minuten, und es rollt weiter.'::text,'zieht'::text,'zieht gerade'::text,'zieht'::text,'Das Team zieht das Flugzeug seit etwa zwei Minuten, und es rollt weiter.'::text),
(329596,36622,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Команда ... літак приблизно дві хвилини, і він продовжує котитися.'::text,'тягне'::text,'тягне'::text,'тягне'::text,'Команда тягне літак приблизно дві хвилини, і він продовжує котитися.'::text),
(329595,36622,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El equipo ... el avión desde hace unos dos minutos, y sigue rodando.'::text,'lleva arrastrando'::text,'está arrastrando'::text,'arrastra'::text,'El equipo lleva arrastrando el avión desde hace unos dos minutos, y sigue rodando.'::text),
(329594,36622,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''équipe ... l''avion depuis environ deux minutes, et il continue de rouler.'::text,'tire'::text,'est en train de tirer'::text,'tire'::text,'L''équipe tire l''avion depuis environ deux minutes, et il continue de rouler.'::text),
(329597,36622,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekip yaklaşık iki dakikadır uçağı ... ve uçak yuvarlanmaya devam ediyor.'::text,'çekiyor'::text,'çekiyor'::text,'çeker'::text,'Ekip yaklaşık iki dakikadır uçağı çekiyor ve uçak yuvarlanmaya devam ediyor.'::text),
(329598,36622,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csapat nagyjából két perce ... a repülőt, és az tovább gurul.'::text,'húzza'::text,'húzza'::text,'húzza'::text,'A csapat nagyjából két perce húzza a repülőt, és az tovább gurul.'::text),
(329601,36623,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Flugzeug ... langsam, als das Team die Kamera erreichte.'::text,'rollte'::text,'rollte'::text,'ist gerollt'::text,'Das Flugzeug rollte langsam, als das Team die Kamera erreichte.'::text),
(329605,36623,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Літак повільно ..., коли команда дісталася до камери.'::text,'котився'::text,'покотився'::text,'покотився'::text,'Літак повільно котився, коли команда дісталася до камери.'::text),
(329604,36623,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El avión ... despacio cuando el equipo llegó a la cámara.'::text,'rodaba'::text,'rodó'::text,'ha rodado'::text,'El avión rodaba despacio cuando el equipo llegó a la cámara.'::text),
(329603,36623,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''avion ... lentement quand l''équipe a atteint la caméra.'::text,'roulait'::text,'a roulé'::text,'a roulé'::text,'L''avion roulait lentement quand l''équipe a atteint la caméra.'::text),
(329606,36623,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekip kameraya ulaştığında uçak yavaşça ...'::text,'ilerliyordu'::text,'ilerledi'::text,'ilerlemiş'::text,'Ekip kameraya ulaştığında uçak yavaşça ilerliyordu.'::text),
(329607,36623,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A repülő lassan ..., amikor a csapat a kamerához ért.'::text,'gurult'::text,'elgurult'::text,'elgurult'::text,'A repülő lassan gurult, amikor a csapat a kamerához ért.'::text),
(329610,36624,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bisher ... das Team das Flugzeug zehn Meter weit gezogen.'::text,'hat'::text,'hat'::text,'zieht'::text,'Bisher hat das Team das Flugzeug zehn Meter weit gezogen.'::text),
(329614,36624,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Досі команда ... літак на десять метрів.'::text,'протягнула'::text,'тягнула'::text,'тягне'::text,'Досі команда протягнула літак на десять метрів.'::text),
(329613,36624,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasta ahora, el equipo ... el avión diez metros.'::text,'ha arrastrado'::text,'lleva arrastrando'::text,'arrastra'::text,'Hasta ahora, el equipo ha arrastrado el avión diez metros.'::text),
(329612,36624,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jusqu''ici, l''équipe ... l''avion sur dix mètres.'::text,'a tiré'::text,'tire'::text,'tire'::text,'Jusqu''ici, l''équipe a tiré l''avion sur dix mètres.'::text),
(329615,36624,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu ana kadar ekip uçağı on metre ...'::text,'çekti'::text,'çekiyor'::text,'çekiyor'::text,'Şu ana kadar ekip uçağı on metre çekti.'::text),
(329616,36624,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eddig a csapat tíz méteren át ... a repülőt.'::text,'húzta'::text,'húzta'::text,'húzza'::text,'Eddig a csapat tíz méteren át húzta a repülőt.'::text),
(329619,36625,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor sie das Flugzeug zogen, ... das Team ein Auto über ein Feld geschleppt.'::text,'hatte'::text,'hat'::text,'schleppt'::text,'Bevor sie das Flugzeug zogen, hatte das Team ein Auto über ein Feld geschleppt.'::text),
(329623,36625,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перед тим як тягнути літак, команда ... машину через поле.'::text,'протягнула'::text,'протягнула'::text,'тягне'::text,'Перед тим як тягнути літак, команда протягнула машину через поле.'::text),
(329622,36625,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de tirar del avión, el equipo ... un coche por un campo.'::text,'había arrastrado'::text,'ha arrastrado'::text,'arrastra'::text,'Antes de tirar del avión, el equipo había arrastrado un coche por un campo.'::text),
(329621,36625,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant de tirer l''avion, l''équipe ... une voiture à travers un champ.'::text,'avait traîné'::text,'a traîné'::text,'traîne'::text,'Avant de tirer l''avion, l''équipe avait traîné une voiture à travers un champ.'::text),
(329624,36625,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uçağı çekmeden önce ekip bir arabayı bir tarlada ...'::text,'sürüklemişti'::text,'sürükledi'::text,'sürüklüyor'::text,'Uçağı çekmeden önce ekip bir arabayı bir tarlada sürüklemişti.'::text),
(329625,36625,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt a repülőt húzták volna, a csapat egy autót ... át egy mezőn.'::text,'vonszolt'::text,'vonszolt'::text,'vonszol'::text,'Mielőtt a repülőt húzták volna, a csapat egy autót vonszolt át egy mezőn.'::text),
(329628,36626,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, nächste Woche um diese Zeit ... du ein noch größeres Flugzeug, ich sag''s, wie''s ist.'::text,'ziehst gerade'::text,'wirst ziehen'::text,'ziehst'::text,'Ehrlich, nächste Woche um diese Zeit ziehst gerade du ein noch größeres Flugzeug, ich sag''s, wie''s ist.'::text),
(329632,36626,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, наступного тижня в цей час ти ... ще більший літак, не збрешу.'::text,'тягнутимеш'::text,'потягнеш'::text,'тягнеш'::text,'Чесно, наступного тижня в цей час ти тягнутимеш ще більший літак, не збрешу.'::text),
(329631,36626,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, la semana que viene a esta hora ... un avión aún más grande, no te voy a mentir.'::text,'estarás arrastrando'::text,'arrastrarás'::text,'arrastras'::text,'Sinceramente, la semana que viene a esta hora estarás arrastrando un avión aún más grande, no te voy a mentir.'::text),
(329630,36626,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, la semaine prochaine à la même heure, tu ... un avion encore plus gros, je vais pas mentir.'::text,'seras en train de tirer'::text,'tireras'::text,'tires'::text,'Franchement, la semaine prochaine à la même heure, tu seras en train de tirer un avion encore plus gros, je vais pas mentir.'::text),
(329633,36626,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, gelecek hafta bu saatlerde daha da büyük bir uçak ..., yalan yok.'::text,'çekiyor olacaksın'::text,'çekeceksin'::text,'çekiyorsun'::text,'Açıkçası, gelecek hafta bu saatlerde daha da büyük bir uçak çekiyor olacaksın, yalan yok.'::text),
(329634,36626,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, jövő héten ilyenkor egy még nagyobb repülőt ..., nem hazudok.'::text,'fogsz húzni'::text,'fogsz húzni'::text,'húzol'::text,'Őszintén, jövő héten ilyenkor egy még nagyobb repülőt fogsz húzni, nem hazudok.'::text),
(329637,36627,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich glaube, sie ... das Flugzeug locker. Eindeutig ein leichtes Flugzeug.'::text,'ziehen'::text,'werden gerade ziehen'::text,'ziehen gerade'::text,'Ich glaube, sie ziehen das Flugzeug locker. Eindeutig ein leichtes Flugzeug.'::text),
(329641,36627,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Думаю, вони ... літак легко. Очевидно, легенький літачок.'::text,'потягнуть'::text,'тягнутимуть'::text,'тягнуть'::text,'Думаю, вони потягнуть літак легко. Очевидно, легенький літачок.'::text),
(329640,36627,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Creo que ... el avión fácilmente. Está claro que es un avión ligero.'::text,'arrastrarán'::text,'estarán arrastrando'::text,'están arrastrando'::text,'Creo que arrastrarán el avión fácilmente. Está claro que es un avión ligero.'::text),
(329639,36627,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je pense qu''ils ... l''avion facilement. Clairement un avion léger.'::text,'tireront'::text,'seront en train de tirer'::text,'tirent'::text,'Je pense qu''ils tireront l''avion facilement. Clairement un avion léger.'::text),
(329642,36627,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bence uçağı kolayca ..., belli ki hafif bir uçak.'::text,'çekecekler'::text,'çekiyor olacaklar'::text,'çekiyorlar'::text,'Bence uçağı kolayca çekecekler, belli ki hafif bir uçak.'::text),
(329643,36627,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szerintem könnyedén ... a repülőt. Nyilván egy pehelykönnyű gép.'::text,'elhúzzák'::text,'húzni fogják'::text,'húzzák'::text,'Szerintem könnyedén elhúzzák a repülőt. Nyilván egy pehelykönnyű gép.'::text),
(329655,36629,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, wenn sie das Seil loslassen, ... das Flugzeug auf zu rollen, ohne Witz.'::text,'hört'::text,'würde aufhören'::text,'hörte'::text,'Digga, wenn sie das Seil loslassen, hört das Flugzeug auf zu rollen, ohne Witz.'::text),
(329659,36629,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якщо вони відпустять канат, літак ... котитися, без брехні.'::text,'перестане'::text,'перестав би'::text,'перестав'::text,'Бро, якщо вони відпустять канат, літак перестане котитися, без брехні.'::text),
(329658,36629,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si sueltan la cuerda, el avión ... de rodar, sin mentira.'::text,'dejará'::text,'dejaría'::text,'dejó'::text,'Bro, si sueltan la cuerda, el avión dejará de rodar, sin mentira.'::text),
(329657,36629,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, s''ils lâchent la corde, l''avion ... de rouler, sans mentir.'::text,'arrêtera'::text,'arrêterait'::text,'a arrêté'::text,'Frérot, s''ils lâchent la corde, l''avion arrêtera de rouler, sans mentir.'::text),
(329660,36629,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ipi bırakırlarsa uçak yuvarlanmayı ..., yalan yok.'::text,'bırakacak'::text,'bırakırdı'::text,'bıraktı'::text,'Kanka, ipi bırakırlarsa uçak yuvarlanmayı bırakacak, yalan yok.'::text),
(329661,36629,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha elengedik a kötelet, a repülő ... a gurulást, nem kamu.'::text,'abbahagyja'::text,'abbahagyná'::text,'abbahagyta'::text,'Tesó, ha elengedik a kötelet, a repülő abbahagyja a gurulást, nem kamu.'::text),
(329664,36630,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, wenn ich so ein Flugzeug ziehen würde, ich ... vor dem ganzen Gym, ehrlich.'::text,'würde flexen'::text,'werde flexen'::text,'flexe'::text,'Yo, wenn ich so ein Flugzeug ziehen würde, ich würde flexen vor dem ganzen Gym, ehrlich.'::text),
(329668,36630,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, якби я тягнув такий літак, я ... перед усім спортзалом, чесно.'::text,'хизувався б'::text,'хизуватимусь'::text,'хизуюся'::text,'Йо, якби я тягнув такий літак, я хизувався б перед усім спортзалом, чесно.'::text),
(329667,36630,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, si yo arrastrara un avión así, ... delante de todo el gimnasio, en serio.'::text,'presumiría'::text,'presumiré'::text,'presumo'::text,'Oye, si yo arrastrara un avión así, presumiría delante de todo el gimnasio, en serio.'::text),
(329666,36630,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, si je tirais un avion comme ça, je ... devant toute ma salle, sérieux.'::text,'me la péterais'::text,'me la péterai'::text,'me la pète'::text,'Yo, si je tirais un avion comme ça, je me la péterais devant toute ma salle, sérieux.'::text),
(329669,36630,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, öyle bir uçak çekseydim bütün spor salonuna ..., cidden.'::text,'hava atardım'::text,'hava atacağım'::text,'hava atıyorum'::text,'Kanka, öyle bir uçak çekseydim bütün spor salonuna hava atardım, cidden.'::text),
(329670,36630,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha ilyen repülőt húznék, az egész edzőteremnek ..., komolyan.'::text,'villognék'::text,'villogni fogok'::text,'villogok'::text,'Tesó, ha ilyen repülőt húznék, az egész edzőteremnek villognék, komolyan.'::text),
(391827,43537,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, der Weg, ... er hochklettert, ist so steil, das ist echt irre.'::text,'den'::text,'wer'::text,'wo'::text,'Digga, der Weg, den er hochklettert, ist so steil, das ist echt irre.'::text),
(391831,43537,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, стежка, ... він підіймається, така крута, що це, чесно, жесть.'::text,'якою'::text,'хто'::text,'де'::text,'Бро, стежка, якою він підіймається, така крута, що це, чесно, жесть.'::text),
(391830,43537,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, el camino ... está subiendo es tan empinado que es una locura, la verdad.'::text,'que'::text,'quien'::text,'donde'::text,'Bro, el camino que está subiendo es tan empinado que es una locura, la verdad.'::text),
(391829,43537,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, le sentier ... il grimpe est tellement raide, c''est un peu dingue.'::text,'sur lequel'::text,'qui'::text,'où'::text,'Frérot, le sentier sur lequel il grimpe est tellement raide, c''est un peu dingue.'::text),
(391832,43537,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ... tırmandığı yol o kadar dik ki resmen delilik.'::text,''::text,NULL::text,NULL::text,'Kanka, tırmandığı yol o kadar dik ki resmen delilik.'::text),
(391833,43537,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az ösvény, ... felmászik, annyira meredek, hogy kicsit őrület.'::text,'amelyen'::text,'aki'::text,'ahol'::text,'Tesó, az ösvény, amelyen felmászik, annyira meredek, hogy kicsit őrület.'::text),
(391836,43538,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In der Info zur Route stand, der letzte Abschnitt ... 30 % steiler als der Rest.'::text,'sei'::text,'ist'::text,'werde'::text,'In der Info zur Route stand, der letzte Abschnitt sei 30 % steiler als der Rest.'::text),
(391840,43538,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У довідці до маршруту зазначалося, що остання ділянка ... на 30 % крутіша за решту.'::text,'була'::text,'є'::text,'буде'::text,'У довідці до маршруту зазначалося, що остання ділянка була на 30 % крутіша за решту.'::text),
(391839,43538,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La nota de la ruta decía que el último tramo ... un 30 % más empinado que el resto.'::text,'era'::text,'es'::text,'será'::text,'La nota de la ruta decía que el último tramo era un 30 % más empinado que el resto.'::text),
(391838,43538,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La note sur le sentier indiquait que le dernier tronçon ... 30 % plus raide que le reste.'::text,'était'::text,'est'::text,'sera'::text,'La note sur le sentier indiquait que le dernier tronçon était 30 % plus raide que le reste.'::text),
(391841,43538,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rota notunda son bölümün diğer kısımlardan %30 daha dik ... yazıyordu.'::text,'olduğu'::text,'olduğu'::text,'olacağı'::text,'Rota notunda son bölümün diğer kısımlardan %30 daha dik olduğu yazıyordu.'::text),
(391842,43538,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az útvonal-tájékoztató szerint az utolsó szakasz 30%-kal meredekebb ..., mint a többi.'::text,'volt'::text,NULL::text,'lesz'::text,'Az útvonal-tájékoztató szerint az utolsó szakasz 30%-kal meredekebb volt, mint a többi.'::text),
(391845,43539,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... flache Wege, aber dieser ist steil, weil er auf einen Berg führt.'::text,'mochte früher'::text,'mochte gewöhnlich'::text,'war gewohnt zu mögen'::text,'Er mochte früher flache Wege, aber dieser ist steil, weil er auf einen Berg führt.'::text),
(391849,43539,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... рівні стежки, але ця крута, бо веде на гору.'::text,'колись любив'::text,'любив, бувало'::text,'звик любити'::text,'Він колись любив рівні стежки, але ця крута, бо веде на гору.'::text),
(391848,43539,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... los caminos llanos, pero este es empinado porque sube a una montaña.'::text,'Solían gustarle'::text,'Le gustaban'::text,'Estaba acostumbrado a que le gustaran'::text,'Solían gustarle los caminos llanos, pero este es empinado porque sube a una montaña.'::text),
(391847,43539,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, il ... les chemins plats, mais celui-ci est raide parce qu''il monte sur une montagne.'::text,'aimait'::text,'aimait'::text,'avait l''habitude d''aimer'::text,'Avant, il aimait les chemins plats, mais celui-ci est raide parce qu''il monte sur une montagne.'::text),
(391850,43539,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden düz yolları ..., ama bu yol dik çünkü bir dağa çıkıyor.'::text,'severdi'::text,'severdi'::text,'sevmeye alışkındı'::text,'Eskiden düz yolları severdi, ama bu yol dik çünkü bir dağa çıkıyor.'::text),
(391851,43539,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen ... a sík utakat, de ez meredek, mert felmegy egy hegyre.'::text,'szerette'::text,'szerette'::text,'hozzá volt szokva szeretni'::text,'Régen szerette a sík utakat, de ez meredek, mert felmegy egy hegyre.'::text),
(391854,43540,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In steilem Gelände vermeiden Wanderer typischerweise aufrechtes ... und lehnen sich stattdessen nach vorn.'::text,'Stehen'::text,'zu stehen'::text,'stehen'::text,'In steilem Gelände vermeiden Wanderer typischerweise aufrechtes Stehen und lehnen sich stattdessen nach vorn.'::text),
(391858,43540,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На крутому рельєфі туристи зазвичай уникають ... прямо і натомість нахиляються вперед.'::text,'стояння'::text,'стояти'::text,'стояти'::text,'На крутому рельєфі туристи зазвичай уникають стояння прямо і натомість нахиляються вперед.'::text),
(391857,43540,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En terreno empinado, los excursionistas suelen evitar ... erguidos y se inclinan hacia delante.'::text,'mantenerse'::text,'mantenerse'::text,'mantenerse'::text,'En terreno empinado, los excursionistas suelen evitar mantenerse erguidos y se inclinan hacia delante.'::text),
(391856,43540,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En terrain raide, les randonneurs évitent généralement de ... droits et se penchent plutôt en avant.'::text,'se tenir'::text,'se tenir'::text,'se tenir'::text,'En terrain raide, les randonneurs évitent généralement de se tenir droits et se penchent plutôt en avant.'::text),
(391859,43540,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dik arazide yürüyüşçüler genellikle dik ... kaçınır ve bunun yerine öne eğilir.'::text,'durmaktan'::text,'durmaktan'::text,'durmak'::text,'Dik arazide yürüyüşçüler genellikle dik durmaktan kaçınır ve bunun yerine öne eğilir.'::text),
(391860,43540,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meredek terepen a túrázók jellemzően kerülik az egyenes ..., és inkább előredőlnek.'::text,'állást'::text,'állni'::text,'áll'::text,'Meredek terepen a túrázók jellemzően kerülik az egyenes állást, és inkább előredőlnek.'::text),
(391863,43541,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du hast diesen steilen Weg leicht aussehen lassen, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Ehrlich, du hast diesen steilen Weg leicht aussehen lassen, oder?'::text),
(391867,43541,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, з тобою ця крута стежка здавалася легкою, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Чесно, з тобою ця крута стежка здавалася легкою, правда?'::text),
(391866,43541,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, hiciste que ese camino empinado pareciera fácil, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Sinceramente, hiciste que ese camino empinado pareciera fácil, ¿verdad?'::text),
(391865,43541,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu as fait paraître ce chemin raide facile, ... ?'::text,'pas vrai'::text,'pas vrai'::text,'pas vrai'::text,'Franchement, tu as fait paraître ce chemin raide facile, pas vrai ?'::text),
(391868,43541,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası o dik yolu kolay gösterdin, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Açıkçası o dik yolu kolay gösterdin, değil mi?'::text),
(391869,43541,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, könnyűnek tüntetted fel azt a meredek ösvényt, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Őszintén, könnyűnek tüntetted fel azt a meredek ösvényt, ugye?'::text),
(391872,43542,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du liebst steile Anstiege, und ich sag''s, wie''s ist, ...'::text,'ich auch'::text,'ich auch'::text,'ich auch'::text,'Du liebst steile Anstiege, und ich sag''s, wie''s ist, ich auch.'::text),
(391876,43542,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти обожнюєш круті підйоми, і не збрешу, ...'::text,'я теж'::text,'я теж'::text,'я теж'::text,'Ти обожнюєш круті підйоми, і не збрешу, я теж.'::text),
(391875,43542,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te encantan las subidas empinadas y, no te voy a mentir, ...'::text,'a mí también'::text,'a mí también'::text,'a mí también'::text,'Te encantan las subidas empinadas y, no te voy a mentir, a mí también.'::text),
(391874,43542,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu adores les montées raides, et je vais pas mentir, ...'::text,'moi aussi'::text,'moi aussi'::text,'moi aussi'::text,'Tu adores les montées raides, et je vais pas mentir, moi aussi.'::text),
(391877,43542,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dik tırmanışlara bayılıyorsun ve yalan yok, ...'::text,'ben de'::text,'ben de'::text,'ben de'::text,'Dik tırmanışlara bayılıyorsun ve yalan yok, ben de.'::text),
(391878,43542,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Imádod a meredek emelkedőket, és nem hazudok, ...'::text,'én is'::text,'én is'::text,'én is'::text,'Imádod a meredek emelkedőket, és nem hazudok, én is.'::text),
(391881,43543,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, du ... stundenlang diesen steilen Weg hinauf, bevor sich das Tal endlich öffnete.'::text,'stiegst'::text,'steigst'::text,'stiegst'::text,'Respekt, du stiegst stundenlang diesen steilen Weg hinauf, bevor sich das Tal endlich öffnete.'::text),
(391885,43543,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, ти ... тією крутою стежкою годинами, поки долина нарешті не відкрилася.'::text,'підіймався'::text,'підіймаєшся'::text,'підіймався'::text,'Респект, ти підіймався тією крутою стежкою годинами, поки долина нарешті не відкрилася.'::text),
(391884,43543,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto, ... horas subiendo ese camino empinado antes de que por fin se abriera el valle.'::text,'llevabas'::text,'llevas'::text,'estabas'::text,'Respeto, llevabas horas subiendo ese camino empinado antes de que por fin se abriera el valle.'::text),
(391883,43543,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect, tu ... ce chemin raide depuis des heures quand la vallée s''est enfin ouverte.'::text,'montais'::text,'montes'::text,'montais'::text,'Respect, tu montais ce chemin raide depuis des heures quand la vallée s''est enfin ouverte.'::text),
(391886,43543,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Helal, vadi sonunda açılmadan önce saatlerdir o dik yoldan ...'::text,'tırmanıyordun'::text,'tırmanıyorsun'::text,'tırmanıyordun'::text,'Helal, vadi sonunda açılmadan önce saatlerdir o dik yoldan tırmanıyordun.'::text),
(391887,43543,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, órák óta ... azon a meredek ösvényen, mire végre kinyílt a völgy.'::text,'másztál'::text,'mászol'::text,'másztál'::text,'Respekt, órák óta másztál azon a meredek ösvényen, mire végre kinyílt a völgy.'::text),
(391899,43545,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonnenuntergang wird er neun Stunden lang steile Wege ...'::text,'hochgelaufen sein'::text,'hochlaufen'::text,'hochgelaufen'::text,'Bis Sonnenuntergang wird er neun Stunden lang steile Wege hochgelaufen sein.'::text),
(391903,43545,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця він ... крутими стежками вгору дев''ять годин.'::text,'йтиме'::text,'йтиме'::text,'іде'::text,'До заходу сонця він йтиме крутими стежками вгору дев''ять годин.'::text),
(391902,43545,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la puesta de sol, ... nueve horas subiendo caminos empinados.'::text,'llevará'::text,'estará'::text,'lleva'::text,'Para la puesta de sol, llevará nueve horas subiendo caminos empinados.'::text),
(391901,43545,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au coucher du soleil, il ... neuf heures sur des sentiers raides.'::text,'aura marché'::text,'marchera'::text,'a marché'::text,'Au coucher du soleil, il aura marché neuf heures sur des sentiers raides.'::text),
(391904,43545,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımında dik yollarda dokuz saattir ...'::text,'yürüyor olacak'::text,'yürüyor olacak'::text,'yürüyor'::text,'Gün batımında dik yollarda dokuz saattir yürüyor olacak.'::text),
(391905,43545,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Naplementére már kilenc órája ... felfelé a meredek ösvényeken.'::text,'fog gyalogolni'::text,'fog gyalogolni'::text,'gyalogol'::text,'Naplementére már kilenc órája fog gyalogolni felfelé a meredek ösvényeken.'::text),
(391908,43546,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre der Weg nicht so steil gewesen, ... er seine Stöcke nicht gebraucht.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wäre der Weg nicht so steil gewesen, hätte er seine Stöcke nicht gebraucht.'::text),
(391912,43546,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби стежка не була такою крутою, йому ... палиці.'::text,'не знадобилися б'::text,'не знадобляться'::text,'не знадобилися'::text,'Якби стежка не була такою крутою, йому не знадобилися б палиці.'::text),
(391911,43546,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el camino no hubiera sido tan empinado, no ... sus bastones.'::text,'habría necesitado'::text,'necesitará'::text,'necesitó'::text,'Si el camino no hubiera sido tan empinado, no habría necesitado sus bastones.'::text),
(391910,43546,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le chemin n''avait pas été si raide, il ... de ses bâtons.'::text,'n''aurait pas eu besoin'::text,'n''aura pas besoin'::text,'n''a pas eu besoin'::text,'Si le chemin n''avait pas été si raide, il n''aurait pas eu besoin de ses bâtons.'::text),
(391913,43546,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yol o kadar dik olmasaydı, batonlarına ...'::text,'ihtiyaç duymazdı'::text,'ihtiyaç duymayacak'::text,'ihtiyaç duymadı'::text,'Yol o kadar dik olmasaydı, batonlarına ihtiyaç duymazdı.'::text),
(391914,43546,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az ösvény nem lett volna ilyen meredek, nem ... a botjaira.'::text,'lett volna szüksége'::text,'lesz szüksége'::text,'volt szüksége'::text,'Ha az ösvény nem lett volna ilyen meredek, nem lett volna szüksége a botjaira.'::text),
(370452,41162,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... um 9 Uhr gerade den schmalen Pfad hinunter, als das Teammeeting ohne ihn begann.'::text,'kletterte'::text,'kletterte'::text,'ist geklettert'::text,'Er kletterte um 9 Uhr gerade den schmalen Pfad hinunter, als das Teammeeting ohne ihn begann.'::text),
(370456,41162,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'О 9:00 він ... вузькою стежкою вниз, коли командна нарада почалася без нього.'::text,'спускався'::text,'спустився'::text,'спустився'::text,'О 9:00 він спускався вузькою стежкою вниз, коли командна нарада почалася без нього.'::text),
(370455,41162,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A las 9:00 ... por el sendero estrecho cuando la reunión del equipo empezó sin él.'::text,'estaba bajando'::text,'bajó'::text,'ha bajado'::text,'A las 9:00 estaba bajando por el sendero estrecho cuando la reunión del equipo empezó sin él.'::text),
(370454,41162,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À 9 h, il ... le sentier étroit quand la réunion d''équipe a commencé sans lui.'::text,'descendait'::text,'a descendu'::text,'a descendu'::text,'À 9 h, il descendait le sentier étroit quand la réunion d''équipe a commencé sans lui.'::text),
(370457,41162,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 9''da ekip toplantısı onsuz başladığında dar patikadan aşağı ...'::text,'iniyordu'::text,'indi'::text,'inmiş'::text,'Saat 9''da ekip toplantısı onsuz başladığında dar patikadan aşağı iniyordu.'::text),
(370458,41162,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Reggel 9-kor épp ... a keskeny ösvényen, amikor a csapatmegbeszélés nélküle elkezdődött.'::text,'mászott lefelé'::text,'lemászott'::text,'lemászott'::text,'Reggel 9-kor épp mászott lefelé a keskeny ösvényen, amikor a csapatmegbeszélés nélküle elkezdődött.'::text),
(370461,41163,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Weg ... seit einer Stunde schmaler, deshalb ist er nicht breit.'::text,'wird'::text,'wird gerade'::text,'wird'::text,'Der Weg wird seit einer Stunde schmaler, deshalb ist er nicht breit.'::text),
(370465,41163,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стежка вже годину ... вужчою, тому вона й не широка.'::text,'стає'::text,'стає'::text,'стає'::text,'Стежка вже годину стає вужчою, тому вона й не широка.'::text),
(370464,41163,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El camino ... más estrecho desde hace una hora, por eso no es ancho.'::text,'se ha ido volviendo'::text,'se está volviendo'::text,'se vuelve'::text,'El camino se ha ido volviendo más estrecho desde hace una hora, por eso no es ancho.'::text),
(370463,41163,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chemin ... plus étroit depuis une heure, c''est pour ça qu''il n''est pas large.'::text,'devient'::text,'est en train de devenir'::text,'devient'::text,'Le chemin devient plus étroit depuis une heure, c''est pour ça qu''il n''est pas large.'::text),
(370466,41163,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Patika bir saattir ..., o yüzden geniş değil.'::text,'daralıyor'::text,'daralıyor'::text,'daralır'::text,'Patika bir saattir daralıyor, o yüzden geniş değil.'::text),
(370467,41163,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ösvény egy órája ..., ezért nem széles.'::text,'keskenyedik'::text,'keskenyedik'::text,'keskenyedik'::text,'Az ösvény egy órája keskenyedik, ezért nem széles.'::text),
(370470,41164,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während der Wanderer die schmalen Felsvorsprünge ..., stützte er sich am Felsen ab, wie beobachtet wurde.'::text,'hinabstieg'::text,'hinabstieg'::text,'hinabgestiegen ist'::text,'Während der Wanderer die schmalen Felsvorsprünge hinabstieg, stützte er sich am Felsen ab, wie beobachtet wurde.'::text),
(370474,41164,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки турист ... вузькими уступами вниз, він спирався на скелю, як було помічено.'::text,'спускався'::text,'спустився'::text,'спустився'::text,'Поки турист спускався вузькими уступами вниз, він спирався на скелю, як було помічено.'::text),
(370473,41164,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras el excursionista ... por las estrechas cornisas, se apoyaba en la roca, según se observó.'::text,'bajaba'::text,'bajó'::text,'ha bajado'::text,'Mientras el excursionista bajaba por las estrechas cornisas, se apoyaba en la roca, según se observó.'::text),
(370472,41164,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que le randonneur ... les corniches étroites, il s''appuyait sur la roche, comme observé.'::text,'descendait'::text,'a descendu'::text,'a descendu'::text,'Pendant que le randonneur descendait les corniches étroites, il s''appuyait sur la roche, comme observé.'::text),
(370475,41164,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yürüyüşçü dar çıkıntılardan aşağı ..., gözlemlendiği üzere kayaya tutunarak dengesini sağladı.'::text,'inerken'::text,'indi'::text,'inmiş'::text,'Yürüyüşçü dar çıkıntılardan aşağı inerken, gözlemlendiği üzere kayaya tutunarak dengesini sağladı.'::text),
(370476,41164,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a túrázó lefelé ... a keskeny párkányokon, megtámaszkodott a sziklán, ahogy megfigyelték.'::text,'lépkedett'::text,'lépett'::text,'lépett'::text,'Miközben a túrázó lefelé lépkedett a keskeny párkányokon, megtámaszkodott a sziklán, ahogy megfigyelték.'::text),
(370479,41165,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... schon drei schmale Felsvorsprünge runtergeklettert, ohne auszurutschen.'::text,'bist'::text,'bist'::text,'kletterst'::text,'Ehrlich, du bist schon drei schmale Felsvorsprünge runtergeklettert, ohne auszurutschen.'::text),
(370483,41165,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти вже ... трьома вузькими уступами вниз і ні разу не послизнувся.'::text,'спустився'::text,'спускався'::text,'спускаєшся'::text,'Чесно, ти вже спустився трьома вузькими уступами вниз і ні разу не послизнувся.'::text),
(370482,41165,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, ya ... tres cornisas estrechas sin resbalarte.'::text,'has bajado'::text,'llevas bajando'::text,'estás bajando'::text,'Sinceramente, ya has bajado tres cornisas estrechas sin resbalarte.'::text),
(370481,41165,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... déjà trois corniches étroites sans glisser.'::text,'as descendu'::text,'descends'::text,'descends'::text,'Franchement, tu as descendu déjà trois corniches étroites sans glisser.'::text),
(370484,41165,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, hiç kaymadan şimdiden üç dar çıkıntıdan ...'::text,'indin'::text,'iniyorsun'::text,'iniyorsun'::text,'Açıkçası, hiç kaymadan şimdiden üç dar çıkıntıdan indin.'::text),
(370485,41165,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, már három keskeny párkányon ... anélkül, hogy megcsúsztál volna.'::text,'másztál le'::text,'másztál lefelé'::text,'mászol le'::text,'Őszintén, már három keskeny párkányon másztál le anélkül, hogy megcsúsztál volna.'::text),
(370488,41166,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der Weg so schmal wurde, ... du schon den halben Canyon durchquert, Respekt.'::text,'hattest'::text,'hast'::text,'durchquerst'::text,'Als der Weg so schmal wurde, hattest du schon den halben Canyon durchquert, Respekt.'::text),
(370492,41166,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На той час, як стежка стала такою вузькою, ти вже ... пів каньйону, респект.'::text,'перетнув'::text,'перетнув'::text,'перетинаєш'::text,'На той час, як стежка стала такою вузькою, ти вже перетнув пів каньйону, респект.'::text),
(370491,41166,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando el camino se volvió tan estrecho, ya ... medio cañón, respeto.'::text,'habías cruzado'::text,'has cruzado'::text,'cruzas'::text,'Para cuando el camino se volvió tan estrecho, ya habías cruzado medio cañón, respeto.'::text),
(370490,41166,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le chemin est devenu aussi étroit, tu ... déjà la moitié du canyon, respect.'::text,'avais traversé'::text,'as traversé'::text,'traverses'::text,'Quand le chemin est devenu aussi étroit, tu avais traversé déjà la moitié du canyon, respect.'::text),
(370493,41166,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Patika bu kadar daraldığında kanyonun yarısını çoktan ..., helal.'::text,'geçmiştin'::text,'geçtin'::text,'geçiyorsun'::text,'Patika bu kadar daraldığında kanyonun yarısını çoktan geçmiştin, helal.'::text),
(370494,41166,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire az ösvény ilyen keskeny lett, már ... a kanyon felét, respekt.'::text,'átszelted'::text,'átszelted'::text,'átszeled'::text,'Mire az ösvény ilyen keskeny lett, már átszelted a kanyon felét, respekt.'::text),
(370497,41167,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... du wieder diesen schmalen Pfad, und ehrlich, Respekt.'::text,'läufst gerade'::text,'wirst laufen'::text,'läufst'::text,'Morgen um diese Zeit läufst gerade du wieder diesen schmalen Pfad, und ehrlich, Respekt.'::text),
(370501,41167,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час ти знову ... тією вузькою стежкою, і чесно, респект.'::text,'йтимеш'::text,'пройдеш'::text,'ідеш'::text,'Завтра в цей час ти знову йтимеш тією вузькою стежкою, і чесно, респект.'::text),
(370500,41167,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora ... otra vez por ese sendero estrecho y, sinceramente, respeto.'::text,'estarás caminando'::text,'caminarás'::text,'caminas'::text,'Mañana a esta hora estarás caminando otra vez por ese sendero estrecho y, sinceramente, respeto.'::text),
(370499,41167,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, tu ... encore ce sentier étroit, et franchement, respect.'::text,'seras en train de parcourir'::text,'parcourras'::text,'parcours'::text,'Demain à la même heure, tu seras en train de parcourir encore ce sentier étroit, et franchement, respect.'::text),
(370502,41167,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde yine o dar patikada ..., ve açıkçası helal.'::text,'yürüyor olacaksın'::text,'yürüyeceksin'::text,'yürüyorsun'::text,'Yarın bu saatlerde yine o dar patikada yürüyor olacaksın, ve açıkçası helal.'::text),
(370503,41167,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor megint azon a keskeny ösvényen ..., és őszintén, respekt.'::text,'fogsz túrázni'::text,'fogsz túrázni'::text,'túrázol'::text,'Holnap ilyenkor megint azon a keskeny ösvényen fogsz túrázni, és őszintén, respekt.'::text),
(370506,41168,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich verspreche, er ... auf diesem schmalen Pfad sicher. Was soll schon schiefgehen, offensichtlich.'::text,'bleibt'::text,'wird bleiben'::text,'bleibt gerade'::text,'Ich verspreche, er bleibt auf diesem schmalen Pfad sicher. Was soll schon schiefgehen, offensichtlich.'::text),
(370510,41168,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Обіцяю, він ... в безпеці на цій вузькій стежці. Нічого не може піти не так, очевидно.'::text,'залишиться'::text,'залишатиметься'::text,'залишається'::text,'Обіцяю, він залишиться в безпеці на цій вузькій стежці. Нічого не може піти не так, очевидно.'::text),
(370509,41168,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te prometo que ... a salvo en este sendero estrecho. Nada podría salir mal, obviamente.'::text,'se quedará'::text,'se estará quedando'::text,'se queda'::text,'Te prometo que se quedará a salvo en este sendero estrecho. Nada podría salir mal, obviamente.'::text),
(370508,41168,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je te promets qu''il ... en sécurité sur ce sentier étroit. Rien ne pourrait mal tourner, évidemment.'::text,'restera'::text,'sera en train de rester'::text,'reste'::text,'Je te promets qu''il restera en sécurité sur ce sentier étroit. Rien ne pourrait mal tourner, évidemment.'::text),
(370511,41168,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Söz veriyorum, bu dar patikada güvende ..., hiçbir şey ters gidemez, tabii ki.'::text,'kalacak'::text,'kalıyor olacak'::text,'kalıyor'::text,'Söz veriyorum, bu dar patikada güvende kalacak, hiçbir şey ters gidemez, tabii ki.'::text),
(370512,41168,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megígérem, hogy ... biztonságban ezen a keskeny ösvényen. Semmi sem sülhet el rosszul, nyilván.'::text,'marad'::text,'maradni fog'::text,'marad'::text,'Megígérem, hogy marad biztonságban ezen a keskeny ösvényen. Semmi sem sülhet el rosszul, nyilván.'::text),
(370515,41169,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... schmale Pfade, und schau ihn dir jetzt an. Ein echter Profi.'::text,'hasste früher'::text,'hasste immer'::text,'war es gewohnt zu hassen'::text,'Er hasste früher schmale Pfade, und schau ihn dir jetzt an. Ein echter Profi.'::text),
(370519,41169,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... вузькі стежки, а глянь на нього зараз. Справжній профі.'::text,'колись ненавидів'::text,'бувало, ненавидів'::text,'звик ненавидіти'::text,'Він колись ненавидів вузькі стежки, а глянь на нього зараз. Справжній профі.'::text),
(370518,41169,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... los senderos estrechos, y míralo ahora. Todo un profesional.'::text,'Solía odiar'::text,'Odiaba'::text,'Estaba acostumbrado a odiar'::text,'Solía odiar los senderos estrechos, y míralo ahora. Todo un profesional.'::text),
(370517,41169,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... les sentiers étroits, et regarde-le maintenant. Un vrai pro.'::text,'détestait avant'::text,'détestait souvent'::text,'avait l''habitude de détester'::text,'Il détestait avant les sentiers étroits, et regarde-le maintenant. Un vrai pro.'::text),
(370520,41169,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden dar patikalardan ..., şimdi ona bir bak. Gerçek bir profesyonel.'::text,'nefret ederdi'::text,'nefret ederdi'::text,'nefret etmeye alışkındı'::text,'Eskiden dar patikalardan nefret ederdi, şimdi ona bir bak. Gerçek bir profesyonel.'::text),
(370521,41169,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen ... a keskeny ösvényeket, és most nézz rá. Igazi profi.'::text,'utálta'::text,'utálta'::text,'hozzá volt szokva utálni'::text,'Régen utálta a keskeny ösvényeket, és most nézz rá. Igazi profi.'::text),
(370533,41171,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... der Wanderer einen schmalen Pfad zwischen den Felswänden hinunter.'::text,'läuft'::text,'läuft'::text,'ist gelaufen'::text,'Gerade läuft der Wanderer einen schmalen Pfad zwischen den Felswänden hinunter.'::text),
(370537,41171,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зараз турист ... вниз вузькою стежкою між скелястими стінами.'::text,'іде'::text,'іде'::text,'пройшов'::text,'Зараз турист іде вниз вузькою стежкою між скелястими стінами.'::text),
(370536,41171,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo, el excursionista ... por un sendero estrecho entre las paredes de roca.'::text,'está bajando'::text,'baja'::text,'ha bajado'::text,'Ahora mismo, el excursionista está bajando por un sendero estrecho entre las paredes de roca.'::text),
(370535,41171,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, le randonneur ... un sentier étroit entre les parois rocheuses.'::text,'descend'::text,'descend'::text,'a descendu'::text,'En ce moment, le randonneur descend un sentier étroit entre les parois rocheuses.'::text),
(370538,41171,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda yürüyüşçü kaya duvarları arasındaki dar bir patikadan aşağı ...'::text,'yürüyor'::text,'yürür'::text,'yürüdü'::text,'Şu anda yürüyüşçü kaya duvarları arasındaki dar bir patikadan aşağı yürüyor.'::text),
(370539,41171,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most a túrázó egy keskeny ösvényen ... lefelé a sziklafalak között.'::text,'megy'::text,'megy'::text,'ment'::text,'Épp most a túrázó egy keskeny ösvényen megy lefelé a sziklafalak között.'::text),
(333876,37098,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fußabdrücke werden auf nassem Sand typischerweise von Barfußläufern ...'::text,'hinterlassen'::text,'hinterlassen'::text,'hinterlassend'::text,'Fußabdrücke werden auf nassem Sand typischerweise von Barfußläufern hinterlassen.'::text),
(333880,37098,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сліди на мокрому піску зазвичай ... босоногими перехожими.'::text,'залишаються'::text,'залишати'::text,'залишаючи'::text,'Сліди на мокрому піску зазвичай залишаються босоногими перехожими.'::text),
(333879,37098,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las huellas suelen ser ... por quienes caminan descalzos sobre la arena mojada.'::text,'dejadas'::text,'dejar'::text,'dejando'::text,'Las huellas suelen ser dejadas por quienes caminan descalzos sobre la arena mojada.'::text),
(333878,37098,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les empreintes sont généralement ... par des marcheurs pieds nus sur le sable mouillé.'::text,'laissées'::text,'laisser'::text,'laissant'::text,'Les empreintes sont généralement laissées par des marcheurs pieds nus sur le sable mouillé.'::text),
(333881,37098,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayak izleri genellikle ıslak kumda yalınayak yürüyenler tarafından ...'::text,'bırakılır'::text,'bırakmak'::text,'bırakarak'::text,'Ayak izleri genellikle ıslak kumda yalınayak yürüyenler tarafından bırakılır.'::text),
(333882,37098,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lábnyomokat jellemzően mezítlábas sétálók ... a nedves homokon.'::text,'hagyják'::text,'hagyni'::text,'hagyva'::text,'A lábnyomokat jellemzően mezítlábas sétálók hagyják a nedves homokon.'::text),
(333894,37100,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Barfuß unter diesem blauen Himmel ... sie absolut nicht frieren!'::text,'kann'::text,'darf'::text,'sollte'::text,'Barfuß unter diesem blauen Himmel kann sie absolut nicht frieren!'::text),
(333898,37100,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вона йде босоніж під тим блакитним небом, їй абсолютно ... бути холодно!'::text,'не може'::text,'не можна'::text,'не повинно'::text,'Коли вона йде босоніж під тим блакитним небом, їй абсолютно не може бути холодно!'::text),
(333897,37100,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Caminando descalza bajo ese cielo azul, ... tener frío en absoluto!'::text,'no puede'::text,'no debe'::text,'no debería'::text,'¡Caminando descalza bajo ese cielo azul, no puede tener frío en absoluto!'::text),
(333896,37100,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pieds nus sous ce ciel bleu, elle ... pas du tout avoir froid !'::text,'ne peut'::text,'ne doit'::text,'ne devrait'::text,'Pieds nus sous ce ciel bleu, elle ne peut pas du tout avoir froid !'::text),
(333899,37100,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O mavi gökyüzünün altında yalınayak yürürken kesinlikle üşüyor ...!'::text,'olamaz'::text,'olmamalı'::text,'olmamalı'::text,'O mavi gökyüzünün altında yalınayak yürürken kesinlikle üşüyor olamaz!'::text),
(333900,37100,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahogy mezítláb sétál a kék ég alatt, egyszerűen ... fáznia!'::text,'nem lehet'::text,'nem szabad'::text,'nem kellene'::text,'Ahogy mezítláb sétál a kék ég alatt, egyszerűen nem lehet fáznia!'::text),
(333903,37101,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau, ... barfuß geht, hinterlässt Spuren, die das Meer für immer zerstört!'::text,'die'::text,'was'::text,'deren'::text,'Die Frau, die barfuß geht, hinterlässt Spuren, die das Meer für immer zerstört!'::text),
(333907,37101,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка, ... йде босоніж, залишає сліди, які море назавжди знищує!'::text,'яка'::text,'що'::text,'чия'::text,'Жінка, яка йде босоніж, залишає сліди, які море назавжди знищує!'::text),
(333906,37101,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La mujer ... camina descalza deja huellas que el mar destruye para siempre!'::text,'que'::text,'la cual'::text,'cuya'::text,'¡La mujer que camina descalza deja huellas que el mar destruye para siempre!'::text),
(333905,37101,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme ... marche pieds nus laisse des empreintes que la mer détruit pour toujours !'::text,'qui'::text,'laquelle'::text,'dont'::text,'La femme qui marche pieds nus laisse des empreintes que la mer détruit pour toujours !'::text),
(333908,37101,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalınayak yürüyen ... kadın, denizin sonsuza dek sileceği izler bırakıyor!'::text,''::text,NULL::text,NULL::text,'Yalınayak yürüyen kadın, denizin sonsuza dek sileceği izler bırakıyor!'::text),
(333909,37101,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő, ... mezítláb sétál, olyan lábnyomokat hagy, amelyeket a tenger örökre eltöröl!'::text,'aki'::text,'amely'::text,'akinek a'::text,'A nő, aki mezítláb sétál, olyan lábnyomokat hagy, amelyeket a tenger örökre eltöröl!'::text),
(333912,37102,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, sie hat mir erzählt, sie ... ihre Schuhe zu Hause gelassen, um barfuß zu laufen.'::text,'habe'::text,'hat'::text,'lässt'::text,'Bestie, sie hat mir erzählt, sie habe ihre Schuhe zu Hause gelassen, um barfuß zu laufen.'::text),
(333916,37102,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала мені, що ... взуття вдома, щоб ходити босоніж.'::text,'залишила'::text,'залишила'::text,'залишає'::text,'Подруго, вона сказала мені, що залишила взуття вдома, щоб ходити босоніж.'::text),
(333915,37102,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijo que ... los zapatos en casa para andar descalza.'::text,'había dejado'::text,'ha dejado'::text,'deja'::text,'Amiga, me dijo que había dejado los zapatos en casa para andar descalza.'::text),
(333914,37102,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle m''a dit qu''elle ... ses chaussures à la maison pour marcher pieds nus.'::text,'avait laissé'::text,'a laissé'::text,'laisse'::text,'Ma belle, elle m''a dit qu''elle avait laissé ses chaussures à la maison pour marcher pieds nus.'::text),
(333917,37102,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bana yalınayak yürümek için ayakkabılarını evde ... söyledi.'::text,'bıraktığını'::text,'bıraktığını'::text,'bıraktığını'::text,'Kanka, bana yalınayak yürümek için ayakkabılarını evde bıraktığını söyledi.'::text),
(333918,37102,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy otthon ... a cipőjét, hogy mezítláb sétálhasson.'::text,'hagyta'::text,'hagyta'::text,'hagyja'::text,'Csajszi, azt mondta, hogy otthon hagyta a cipőjét, hogy mezítláb sétálhasson.'::text),
(333921,37103,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, angeblich ... sie es früher, barfuß über Sand zu laufen.'::text,'hasste'::text,'hasste immer'::text,'war gewohnt zu hassen'::text,'Hör mal, angeblich hasste sie es früher, barfuß über Sand zu laufen.'::text),
(333925,37103,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, вона ... ходити босоніж по піску.'::text,'колись ненавиділа'::text,'бувало, ненавиділа'::text,'звикла ненавидіти'::text,'Слухай, кажуть, вона колись ненавиділа ходити босоніж по піску.'::text),
(333924,37103,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer ... andar descalza por la arena.'::text,'solía odiar'::text,'odiaba'::text,'estaba acostumbrada a odiar'::text,'Oye, al parecer solía odiar andar descalza por la arena.'::text),
(333923,37103,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment elle ... marcher pieds nus sur le sable.'::text,'détestait'::text,'détestait souvent'::text,'avait l''habitude de détester'::text,'Écoute, apparemment elle détestait marcher pieds nus sur le sable.'::text),
(333926,37103,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre eskiden kumda yalınayak yürümekten ...'::text,'nefret edermiş'::text,'nefret edermiş'::text,'nefret etmeye alışkınmış'::text,'Dinle, duyduğuma göre eskiden kumda yalınayak yürümekten nefret edermiş.'::text),
(333927,37103,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag régen ... mezítláb járni a homokon.'::text,'utált'::text,'utált'::text,'hozzá volt szokva utálni'::text,'Figyelj, állítólag régen utált mezítláb járni a homokon.'::text),
(333930,37104,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, angeblich vermeidet sie es, am Strand Schuhe zu ..., deshalb läuft sie barfuß.'::text,'tragen'::text,'tragen'::text,'tragen'::text,'Girl, angeblich vermeidet sie es, am Strand Schuhe zu tragen, deshalb läuft sie barfuß.'::text),
(333934,37104,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона уникає ... взуття на пляжі, тому ходить босоніж.'::text,'носіння'::text,'носити'::text,'носити'::text,'Подруго, кажуть, вона уникає носіння взуття на пляжі, тому ходить босоніж.'::text),
(333933,37104,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer evita ... zapatos en la playa, así que va descalza.'::text,'llevar'::text,'llevar'::text,'llevar'::text,'Tía, al parecer evita llevar zapatos en la playa, así que va descalza.'::text),
(333932,37104,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle évite de ... des chaussures à la plage, alors elle marche pieds nus.'::text,'porter'::text,'porter'::text,'porter'::text,'Meuf, apparemment elle évite de porter des chaussures à la plage, alors elle marche pieds nus.'::text),
