(340353,37817,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, a fotós állítólag megkérdezte, miért ... kör alakú.'::text,'volt a színpad'::text,'a színpad volt'::text,'a színpad'::text,'Figyelj, a fotós állítólag megkérdezte, miért volt a színpad kör alakú.'::text),
(340356,37818,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... geübt haben, weil du dich auf dieser runden Bühne so geschmeidig drehst.'::text,'musst'::text,'kannst nicht'::text,'solltest nicht'::text,'Ehrlich, du musst geübt haben, weil du dich auf dieser runden Bühne so geschmeidig drehst.'::text),
(340360,37818,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... тренувалася, бо так плавно крутишся на тій круглій сцені.'::text,'напевно'::text,'навряд чи'::text,'даремно'::text,'Чесно, ти напевно тренувалася, бо так плавно крутишся на тій круглій сцені.'::text),
(340359,37818,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, ... estado practicando, porque giras con mucha soltura en ese escenario circular.'::text,'debes de haber'::text,'no puedes haber'::text,'no deberías haber'::text,'Sinceramente, debes de haber estado practicando, porque giras con mucha soltura en ese escenario circular.'::text),
(340358,37818,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... t''entraîner, parce que tu tournes si bien sur cette scène circulaire.'::text,'as dû'::text,'n''as pas pu'::text,'n''aurais pas dû'::text,'Franchement, tu as dû t''entraîner, parce que tu tournes si bien sur cette scène circulaire.'::text),
(340361,37818,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, çalışıyor ..., çünkü o yuvarlak sahnede çok akıcı dönüyorsun.'::text,'olmalısın'::text,'olamazsın'::text,'olmamalıydın'::text,'Açıkçası, çalışıyor olmalısın, çünkü o yuvarlak sahnede çok akıcı dönüyorsun.'::text),
(340362,37818,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te ... gyakoroltál, mert olyan simán pörögsz azon a kör alakú színpadon.'::text,'biztosan'::text,'biztosan nem'::text,'nem kellett volna'::text,'Őszintén, te biztosan gyakoroltál, mert olyan simán pörögsz azon a kör alakú színpadon.'::text),
(340374,37820,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fotograf ließ die Crew eine runde Plattform im Studio ...'::text,'bauen'::text,'zu bauen'::text,'gebaut'::text,'Der Fotograf ließ die Crew eine runde Plattform im Studio bauen.'::text),
(340378,37820,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Фотограф доручив команді ... круглу платформу в студії.'::text,'збудувати'::text,'збудувати'::text,'збудовану'::text,'Фотограф доручив команді збудувати круглу платформу в студії.'::text),
(340377,37820,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El fotógrafo hizo que el equipo ... una plataforma circular en el estudio.'::text,'construyera'::text,'construyera'::text,'construida'::text,'El fotógrafo hizo que el equipo construyera una plataforma circular en el estudio.'::text),
(340376,37820,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le photographe a demandé à l''équipe de ... une plateforme circulaire dans le studio.'::text,'construire'::text,'construire'::text,'construite'::text,'Le photographe a demandé à l''équipe de construire une plateforme circulaire dans le studio.'::text),
(340379,37820,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fotoğrafçı ekibe stüdyoda yuvarlak bir platform ...'::text,'inşa ettirdi'::text,'inşa etmeyi'::text,'inşa edilmiş'::text,'Fotoğrafçı ekibe stüdyoda yuvarlak bir platform inşa ettirdi.'::text),
(340380,37820,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fotós a stábbal ... egy kör alakú platformot a stúdióban.'::text,'építtetett'::text,'építeni'::text,'épített'::text,'A fotós a stábbal építtetett egy kör alakú platformot a stúdióban.'::text),
(340383,37821,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau auf dem Stuhl wünscht sich, die runde Bühne ... größer.'::text,'wäre'::text,'ist'::text,'wird'::text,'Die Frau auf dem Stuhl wünscht sich, die runde Bühne wäre größer.'::text),
(340387,37821,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка на стільці хоче, щоб кругла сцена ... більшою.'::text,'була'::text,'є'::text,'буде'::text,'Жінка на стільці хоче, щоб кругла сцена була більшою.'::text),
(340386,37821,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer de la silla desearía que el escenario circular ... más grande.'::text,'fuera'::text,'es'::text,'será'::text,'La mujer de la silla desearía que el escenario circular fuera más grande.'::text),
(340385,37821,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme sur la chaise aimerait que la scène circulaire ... plus grande.'::text,'soit'::text,'est'::text,'sera'::text,'La femme sur la chaise aimerait que la scène circulaire soit plus grande.'::text),
(340388,37821,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sandalyedeki kadın yuvarlak sahnenin daha büyük ... istiyor.'::text,'olmasını'::text,'olduğunu'::text,'olacağını'::text,'Sandalyedeki kadın yuvarlak sahnenin daha büyük olmasını istiyor.'::text),
(340389,37821,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A széken ülő nő azt szeretné, ha a kör alakú színpad nagyobb ...'::text,'lenne'::text,NULL::text,'lesz'::text,'A széken ülő nő azt szeretné, ha a kör alakú színpad nagyobb lenne.'::text),
(340392,37822,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Plattform, ... runde Form von oben erkennbar ist, trägt Dutzende Individuen.'::text,'deren'::text,'welche'::text,'die'::text,'Die Plattform, deren runde Form von oben erkennbar ist, trägt Dutzende Individuen.'::text),
(340396,37822,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Платформа, ... кругла форма помітна згори, вміщує десятки осіб.'::text,'чия'::text,'яка'::text,'що'::text,'Платформа, чия кругла форма помітна згори, вміщує десятки осіб.'::text),
(340395,37822,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La plataforma, ... forma circular se observa desde arriba, sostiene a decenas de individuos.'::text,'cuya'::text,'la cual'::text,'que'::text,'La plataforma, cuya forma circular se observa desde arriba, sostiene a decenas de individuos.'::text),
(340394,37822,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La plateforme, ... la forme circulaire est visible d''en haut, accueille des dizaines d''individus.'::text,'dont'::text,'laquelle'::text,'que'::text,'La plateforme, dont la forme circulaire est visible d''en haut, accueille des dizaines d''individus.'::text),
(340397,37822,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yuvarlak şekli yukarıdan ... gözlemlenebilen platform düzinelerce bireyi taşıyor.'::text,''::text,NULL::text,NULL::text,'Yuvarlak şekli yukarıdan gözlemlenebilen platform düzinelerce bireyi taşıyor.'::text),
(340398,37822,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A platform, ... kör alakja felülről is megfigyelhető, több tucat egyént tart meg.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'A platform, amelynek a kör alakja felülről is megfigyelhető, több tucat egyént tart meg.'::text),
(340401,37823,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Menge dreht sich weiter, ... die runde Bühne komplett voll ist!'::text,'obwohl'::text,'trotz'::text,'falls'::text,'Die Menge dreht sich weiter, obwohl die runde Bühne komplett voll ist!'::text),
(340405,37823,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Натовп і далі крутиться, ... кругла сцена повністю заповнена!'::text,'хоча'::text,'попри'::text,'на випадок, якщо'::text,'Натовп і далі крутиться, хоча кругла сцена повністю заповнена!'::text),
(340404,37823,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La multitud sigue girando ... el escenario circular está completamente lleno!'::text,'aunque'::text,'a pesar de'::text,'por si'::text,'¡La multitud sigue girando aunque el escenario circular está completamente lleno!'::text),
(340403,37823,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La foule continue de tourner ... la scène circulaire est complètement pleine !'::text,'même si'::text,'malgré'::text,'au cas où'::text,'La foule continue de tourner même si la scène circulaire est complètement pleine !'::text),
(340406,37823,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yuvarlak sahne tamamen dolu ... kalabalık dönmeye devam ediyor!'::text,'olmasına rağmen'::text,'rağmen'::text,'olursa diye'::text,'Yuvarlak sahne tamamen dolu olmasına rağmen kalabalık dönmeye devam ediyor!'::text),
(340407,37823,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tömeg tovább pörög, ... a kör alakú színpad teljesen tele van!'::text,'pedig'::text,'annak ellenére'::text,'arra az esetre, ha'::text,'A tömeg tovább pörög, pedig a kör alakú színpad teljesen tele van!'::text),
(340194,37800,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, angeblich, während der Junge um den Kreisel ..., haben alle anderen mitgemacht.'::text,'kreiste'::text,'kreiste'::text,'gekreist ist'::text,'Girl, angeblich, während der Junge um den Kreisel kreiste, haben alle anderen mitgemacht.'::text),
(340198,37800,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, поки хлопець ... навколо дзиґи, всі інші приєдналися.'::text,'кружляв'::text,'обійшов'::text,'обійшов'::text,'Подруго, кажуть, поки хлопець кружляв навколо дзиґи, всі інші приєдналися.'::text),
(340197,37800,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer, mientras el chico ... alrededor de la peonza, todos los demás se unieron.'::text,'daba vueltas'::text,'dio vueltas'::text,'ha dado vueltas'::text,'Tía, al parecer, mientras el chico daba vueltas alrededor de la peonza, todos los demás se unieron.'::text),
(340196,37800,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment pendant que le garçon ... autour de la toupie, tous les autres s''y sont mis.'::text,'tournait'::text,'a tourné'::text,'a tourné'::text,'Meuf, apparemment pendant que le garçon tournait autour de la toupie, tous les autres s''y sont mis.'::text),
(340199,37800,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre çocuk topacın etrafında ..., herkes katılmış.'::text,'dönerken'::text,'döndü'::text,'dönmüş'::text,'Kızım, duyduğuma göre çocuk topacın etrafında dönerken, herkes katılmış.'::text),
(340200,37800,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag miközben a srác ... a pörgettyű körül, mindenki más is beszállt.'::text,'körözött'::text,'körbement'::text,'körbement'::text,'Csajszi, állítólag miközben a srác körözött a pörgettyű körül, mindenki más is beszállt.'::text),
(340203,37801,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Menge ... jetzt schon seit zehn Minuten um den Kreisel. Ein leicht repetitives Hobby.'::text,'kreist'::text,'kreist gerade'::text,'kreist'::text,'Die Menge kreist jetzt schon seit zehn Minuten um den Kreisel. Ein leicht repetitives Hobby.'::text),
(340207,37801,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Натовп уже десять хвилин ... навколо тієї дзиґи. Трохи одноманітне хобі.'::text,'кружляє'::text,'кружляє'::text,'кружляє'::text,'Натовп уже десять хвилин кружляє навколо тієї дзиґи. Трохи одноманітне хобі.'::text),
(340206,37801,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gente ... alrededor de esa peonza desde hace diez minutos. Una afición un poco repetitiva.'::text,'lleva dando vueltas'::text,'está dando vueltas'::text,'da vueltas'::text,'La gente lleva dando vueltas alrededor de esa peonza desde hace diez minutos. Una afición un poco repetitiva.'::text),
(340205,37801,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La foule ... autour de cette toupie depuis dix minutes. Un passe-temps un peu répétitif.'::text,'tourne'::text,'est en train de tourner'::text,'tourne'::text,'La foule tourne autour de cette toupie depuis dix minutes. Un passe-temps un peu répétitif.'::text),
(340208,37801,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalabalık on dakikadır o topacın etrafında ..., biraz tekdüze bir hobi.'::text,'dönüyor'::text,'dönüyor'::text,'döner'::text,'Kalabalık on dakikadır o topacın etrafında dönüyor, biraz tekdüze bir hobi.'::text),
(340209,37801,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tömeg már tíz perce ... a pörgettyű körül. Kicsit egyhangú hobbi.'::text,'köröz'::text,'köröz'::text,'köröz'::text,'A tömeg már tíz perce köröz a pörgettyű körül. Kicsit egyhangú hobbi.'::text),
(340212,37802,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Sonne ... gerade unter, als die Menge anfing, um den Kreisel zu laufen. Tolles Timing, offensichtlich.'::text,'ging'::text,'ging'::text,'ist'::text,'Die Sonne ging gerade unter, als die Menge anfing, um den Kreisel zu laufen. Tolles Timing, offensichtlich.'::text),
(340216,37802,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сонце ..., коли натовп почав кружляти навколо дзиґи. Чудовий таймінг, звісно.'::text,'сідало'::text,'сіло'::text,'сіло'::text,'Сонце сідало, коли натовп почав кружляти навколо дзиґи. Чудовий таймінг, звісно.'::text),
(340215,37802,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sol ... cuando la gente empezó a dar vueltas alrededor de la peonza. Qué buen momento, obviamente.'::text,'se estaba poniendo'::text,'se puso'::text,'se ha puesto'::text,'El sol se estaba poniendo cuando la gente empezó a dar vueltas alrededor de la peonza. Qué buen momento, obviamente.'::text),
(340214,37802,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le soleil ... quand la foule a commencé à tourner autour de la toupie. Super timing, évidemment.'::text,'se couchait'::text,'s''est couché'::text,'s''est couché'::text,'Le soleil se couchait quand la foule a commencé à tourner autour de la toupie. Super timing, évidemment.'::text),
(340217,37802,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalabalık topacın etrafında dönmeye başladığında güneş ..., harika zamanlama tabii.'::text,'batıyordu'::text,'battı'::text,'batmış'::text,'Kalabalık topacın etrafında dönmeye başladığında güneş batıyordu, harika zamanlama tabii.'::text),
(340218,37802,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... a nap, amikor a tömeg elkezdett körözni a pörgettyű körül. Remek időzítés, nyilván.'::text,'lemenőben volt'::text,'lement'::text,'lement'::text,'Épp lemenőben volt a nap, amikor a tömeg elkezdett körözni a pörgettyű körül. Remek időzítés, nyilván.'::text),
(340221,37803,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, die sind schon so fünfzigmal um den Kreisel ..., irgendwie ikonisch.'::text,'gelaufen'::text,'gelaufen'::text,'liefen'::text,'Digga, die sind schon so fünfzigmal um den Kreisel gelaufen, irgendwie ikonisch.'::text),
(340225,37803,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вони вже ... ту дзиґу разів п''ятдесят, реально культово.'::text,'оббігли'::text,'оббігали'::text,'оббігли'::text,'Бро, вони вже оббігли ту дзиґу разів п''ятдесят, реально культово.'::text),
(340224,37803,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ya ... esa peonza como cincuenta veces, medio icónico.'::text,'han rodeado'::text,'llevan rodeando'::text,'rodearon'::text,'Bro, ya han rodeado esa peonza como cincuenta veces, medio icónico.'::text),
(340223,37803,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, ils ... cette toupie genre cinquante fois déjà, un peu iconique.'::text,'ont fait le tour de'::text,'font le tour de'::text,'firent le tour de'::text,'Frérot, ils ont fait le tour de cette toupie genre cinquante fois déjà, un peu iconique.'::text),
(340226,37803,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o topacın etrafında şimdiden elli kez falan ..., bayağı ikonik.'::text,'döndüler'::text,'dönüyorlar'::text,'döndüler'::text,'Kanka, o topacın etrafında şimdiden elli kez falan döndüler, bayağı ikonik.'::text),
(340227,37803,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, már vagy ötvenszer ... azt a pörgettyűt, eléggé ikonikus.'::text,'körbefutották'::text,'körbefutkározták'::text,'körbefutották'::text,'Tesó, már vagy ötvenszer körbefutották azt a pörgettyűt, eléggé ikonikus.'::text),
(340239,37805,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn mehr Leute kommen, ... sie den Kreisel in einem größeren Ring.'::text,'umkreisen'::text,'würden umkreisen'::text,'umkreisten'::text,'Wenn mehr Leute kommen, umkreisen sie den Kreisel in einem größeren Ring.'::text),
(340243,37805,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо прийде більше людей, вони ... навколо дзиґи ширшим колом.'::text,'кружлятимуть'::text,'кружляли б'::text,'кружляли'::text,'Якщо прийде більше людей, вони кружлятимуть навколо дзиґи ширшим колом.'::text),
(340242,37805,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si viene más gente, ... alrededor de la peonza en un círculo más amplio.'::text,'girarán'::text,'girarían'::text,'giraron'::text,'Si viene más gente, girarán alrededor de la peonza en un círculo más amplio.'::text),
(340241,37805,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si plus de gens arrivent, ils ... autour de la toupie en formant un cercle plus large.'::text,'tourneront'::text,'tourneraient'::text,'ont tourné'::text,'Si plus de gens arrivent, ils tourneront autour de la toupie en formant un cercle plus large.'::text),
(340244,37805,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha çok insan gelirse topacın etrafında daha geniş bir halkada ...'::text,'dönecekler'::text,'dönerlerdi'::text,'döndüler'::text,'Daha çok insan gelirse topacın etrafında daha geniş bir halkada dönecekler.'::text),
(340245,37805,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha többen jönnek, szélesebb körben ... a pörgettyű körül.'::text,'fognak körözni'::text,'köröznének'::text,'köröztek'::text,'Ha többen jönnek, szélesebb körben fognak körözni a pörgettyű körül.'::text),
(340248,37806,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Kreisel aufhören würde, sich zu drehen, ... die Menge ihn nicht mehr.'::text,'umkreiste'::text,'wird umkreisen'::text,'umkreiste'::text,'Wenn der Kreisel aufhören würde, sich zu drehen, umkreiste die Menge ihn nicht mehr.'::text),
(340252,37806,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби дзиґа перестала крутитися, натовп більше ... навколо неї.'::text,'не кружляв би'::text,'не кружлятиме'::text,'не кружляв'::text,'Якби дзиґа перестала крутитися, натовп більше не кружляв би навколо неї.'::text),
(340251,37806,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la peonza dejara de girar, la gente ya no ... a su alrededor.'::text,'daría vueltas'::text,'dará vueltas'::text,'dio vueltas'::text,'Si la peonza dejara de girar, la gente ya no daría vueltas a su alrededor.'::text),
(340250,37806,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la toupie arrêtait de tourner, la foule ... plus autour d''elle.'::text,'ne tournerait'::text,'ne tournera'::text,'ne tournait'::text,'Si la toupie arrêtait de tourner, la foule ne tournerait plus autour d''elle.'::text),
(340253,37806,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Topaç dönmeyi bıraksaydı, kalabalık artık etrafında ...'::text,'dönmezdi'::text,'dönmeyecek'::text,'dönmedi'::text,'Topaç dönmeyi bıraksaydı, kalabalık artık etrafında dönmezdi.'::text),
(340254,37806,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a pörgettyű abbahagyná a pörgést, a tömeg többé nem ... körülötte.'::text,'körözne'::text,'fog körözni'::text,'körözött'::text,'Ha a pörgettyű abbahagyná a pörgést, a tömeg többé nem körözne körülötte.'::text),
(340257,37807,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kreisel ... bei Sonnenuntergang von Dutzenden Läufern umkreist.'::text,'wird'::text,'kreist'::text,'umkreiste'::text,'Der Kreisel wird bei Sonnenuntergang von Dutzenden Läufern umkreist.'::text),
(340261,37807,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дзиґу на заході сонця ... десятки бігунів.'::text,'оббігають'::text,'оббігає'::text,'оббігли'::text,'Дзиґу на заході сонця оббігають десятки бігунів.'::text),
(340260,37807,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La peonza ... por decenas de corredores al atardecer.'::text,'es rodeada'::text,'rodea'::text,'rodeó'::text,'La peonza es rodeada por decenas de corredores al atardecer.'::text),
(340259,37807,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La toupie ... par des dizaines de coureurs au coucher du soleil.'::text,'est encerclée'::text,'encercle'::text,'encerclait'::text,'La toupie est encerclée par des dizaines de coureurs au coucher du soleil.'::text),
(340262,37807,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Topacın etrafı gün batımında onlarca koşucu tarafından ...'::text,'dolanılıyor'::text,'dolanıyor'::text,'dolandı'::text,'Topacın etrafı gün batımında onlarca koşucu tarafından dolanılıyor.'::text),
(340263,37807,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pörgettyűt naplementekor tucatnyi futó ...'::text,'körbefutja'::text,'körbefut'::text,'körbefutotta'::text,'A pörgettyűt naplementekor tucatnyi futó körbefutja.'::text),
(340266,37808,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Menge ... schon ewig um diesen Kreisel, und jetzt kann niemand mehr aufhören!'::text,'kreist'::text,'kreist gerade'::text,'kreist'::text,'Die Menge kreist schon ewig um diesen Kreisel, und jetzt kann niemand mehr aufhören!'::text),
(340270,37808,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Натовп уже цілу вічність ... навколо тієї дзиґи, і тепер ніхто не може зупинитися!'::text,'кружляє'::text,'кружляє'::text,'кружляє'::text,'Натовп уже цілу вічність кружляє навколо тієї дзиґи, і тепер ніхто не може зупинитися!'::text),
(340269,37808,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La gente ... alrededor de esa peonza desde hace siglos y ahora nadie puede parar!'::text,'lleva dando vueltas'::text,'está dando vueltas'::text,'da vueltas'::text,'¡La gente lleva dando vueltas alrededor de esa peonza desde hace siglos y ahora nadie puede parar!'::text),
(340268,37808,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La foule ... autour de cette toupie depuis une éternité, et plus personne ne peut s''arrêter !'::text,'tourne'::text,'est en train de tourner'::text,'tourne'::text,'La foule tourne autour de cette toupie depuis une éternité, et plus personne ne peut s''arrêter !'::text),
(340271,37808,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalabalık çok uzun zamandır o topacın etrafında ... ve artık kimse duramıyor!'::text,'dönüyor'::text,'dönüyor'::text,'döner'::text,'Kalabalık çok uzun zamandır o topacın etrafında dönüyor ve artık kimse duramıyor!'::text),
(340272,37808,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tömeg már ezer éve ... a pörgettyű körül, és most már senki sem tud megállni!'::text,'köröz'::text,'köröz'::text,'köröz'::text,'A tömeg már ezer éve köröz a pörgettyű körül, és most már senki sem tud megállni!'::text),
(340284,37810,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also ich hab gehört, bis Mitternacht werden sie den Kreisel tausendmal ...'::text,'umrundet haben'::text,'umrunden'::text,'umrunden'::text,'Okay, also ich hab gehört, bis Mitternacht werden sie den Kreisel tausendmal umrundet haben.'::text),
(340288,37810,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, я чула, що до півночі вони ... ту дзиґу тисячу разів.'::text,'оббіжать'::text,'оббіжать'::text,'оббігають'::text,'Коротше, я чула, що до півночі вони оббіжать ту дзиґу тисячу разів.'::text),
(340287,37810,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues he oído que para medianoche ... esa peonza mil veces.'::text,'habrán rodeado'::text,'rodearán'::text,'rodean'::text,'Vale, pues he oído que para medianoche habrán rodeado esa peonza mil veces.'::text),
(340286,37810,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, alors j''ai entendu qu''à minuit, ils ... le tour de cette toupie mille fois.'::text,'auront fait'::text,'feront'::text,'font'::text,'Bon, alors j''ai entendu qu''à minuit, ils auront fait le tour de cette toupie mille fois.'::text),
(340289,37810,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, duyduğuma göre gece yarısına kadar o topacın etrafında bin kez ...'::text,'dönmüş olacaklar'::text,'dönecekler'::text,'dönüyorlar'::text,'Tamam, duyduğuma göre gece yarısına kadar o topacın etrafında bin kez dönmüş olacaklar.'::text),
(340290,37810,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, azt hallottam, hogy éjfélig ezerszer ... azt a pörgettyűt.'::text,'körbe fogják futni'::text,'körbe fogják futni'::text,'körbefutják'::text,'Szóval, azt hallottam, hogy éjfélig ezerszer körbe fogják futni azt a pörgettyűt.'::text),
(344964,38330,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nächste Woche um diese Zeit ... sie wieder in diesem überfüllten Stadion. Sie hasst Menschenmengen, ganz klar.'::text,'sitzt gerade'::text,'wird sitzen'::text,'sitzt'::text,'Nächste Woche um diese Zeit sitzt gerade sie wieder in diesem überfüllten Stadion. Sie hasst Menschenmengen, ganz klar.'::text),
(344968,38330,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наступного тижня в цей час вона знову ... на цьому переповненому стадіоні. Очевидно, вона ненавидить натовпи.'::text,'сидітиме'::text,'сидітиме'::text,'сидить'::text,'Наступного тижня в цей час вона знову сидітиме на цьому переповненому стадіоні. Очевидно, вона ненавидить натовпи.'::text),
(344967,38330,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La semana que viene a esta hora, ... otra vez en este estadio abarrotado. Está claro que odia las multitudes.'::text,'estará sentada'::text,'se sentará'::text,'se sienta'::text,'La semana que viene a esta hora, estará sentada otra vez en este estadio abarrotado. Está claro que odia las multitudes.'::text),
(344966,38330,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La semaine prochaine à la même heure, elle ... encore dans ce stade bondé. Clairement, elle déteste la foule.'::text,'sera assise'::text,'s''assiéra'::text,'s''assied'::text,'La semaine prochaine à la même heure, elle sera assise encore dans ce stade bondé. Clairement, elle déteste la foule.'::text),
(344969,38330,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gelecek hafta bu saatlerde yine bu kalabalık stadyumda ..., belli ki kalabalıklardan nefret ediyor.'::text,'oturuyor olacak'::text,'oturacak'::text,'oturuyor'::text,'Gelecek hafta bu saatlerde yine bu kalabalık stadyumda oturuyor olacak, belli ki kalabalıklardan nefret ediyor.'::text),
(344970,38330,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jövő héten ilyenkor megint ... ebben a zsúfolt stadionban. Nyilván utálja a tömeget.'::text,'fog ülni'::text,'fog ülni'::text,'ül'::text,'Jövő héten ilyenkor megint fog ülni ebben a zsúfolt stadionban. Nyilván utálja a tömeget.'::text),
(344973,38331,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, ich wette, das Stadion ... nach der Pause noch voller, ehrlich.'::text,'wird'::text,'wird gerade'::text,'wird'::text,'Digga, ich wette, das Stadion wird nach der Pause noch voller, ehrlich.'::text),
(344977,38331,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, б''юся об заклад, що після перерви стадіон ... ще більш переповненим, чесно.'::text,'стане'::text,'ставатиме'::text,'стає'::text,'Бро, б''юся об заклад, що після перерви стадіон стане ще більш переповненим, чесно.'::text),
(344976,38331,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, apuesto a que el estadio ... todavía más lleno después del descanso, en serio.'::text,'se pondrá'::text,'se estará poniendo'::text,'se está poniendo'::text,'Bro, apuesto a que el estadio se pondrá todavía más lleno después del descanso, en serio.'::text),
(344975,38331,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, je parie que le stade ... encore plus bondé après la pause, sérieux.'::text,'sera'::text,'sera en train de devenir'::text,'devient'::text,'Frérot, je parie que le stade sera encore plus bondé après la pause, sérieux.'::text),
(344978,38331,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bahse girerim stadyum aradan sonra daha da ..., cidden.'::text,'kalabalıklaşacak'::text,'kalabalıklaşıyor olacak'::text,'kalabalıklaşıyor'::text,'Kanka, bahse girerim stadyum aradan sonra daha da kalabalıklaşacak, cidden.'::text),
(344979,38331,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, lefogadom, hogy a szünet után a stadion még zsúfoltabb ..., komolyan.'::text,'lesz'::text,'lesz'::text,'lesz'::text,'Tesó, lefogadom, hogy a szünet után a stadion még zsúfoltabb lesz, komolyan.'::text),
(344982,38332,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Heimmannschaft spielt, ... das Stadion voll.'::text,'wird'::text,'wurde'::text,'wird'::text,'Wenn die Heimmannschaft spielt, wird das Stadion voll.'::text),
(344986,38332,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли грає домашня команда, стадіон ... переповненим.'::text,'стає'::text,'став'::text,'стане'::text,'Коли грає домашня команда, стадіон стає переповненим.'::text),
(344985,38332,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si juega el equipo local, el estadio ... hasta arriba.'::text,'se llena'::text,'se llenó'::text,'se llenará'::text,'Si juega el equipo local, el estadio se llena hasta arriba.'::text),
(344984,38332,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand l''équipe locale joue, le stade ... bondé.'::text,'devient'::text,'est devenu'::text,'deviendra'::text,'Quand l''équipe locale joue, le stade devient bondé.'::text),
(344987,38332,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ev sahibi takım oynadığında stadyum ...'::text,'dolar'::text,'doldu'::text,'dolacak'::text,'Ev sahibi takım oynadığında stadyum dolar.'::text),
(344988,38332,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a hazai csapat játszik, a stadion ...'::text,'megtelik'::text,'megtelt'::text,'meg fog telni'::text,'Ha a hazai csapat játszik, a stadion megtelik.'::text),
(344991,38333,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die überfüllten Tribünen ... von Tausenden Fans gefüllt.'::text,'werden'::text,'füllen'::text,'füllend'::text,'Die überfüllten Tribünen werden von Tausenden Fans gefüllt.'::text),
(344995,38333,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Переповнені трибуни ... тисячами вболівальників.'::text,'заповнені'::text,'заповнюють'::text,'заповнюючи'::text,'Переповнені трибуни заповнені тисячами вболівальників.'::text),
(344994,38333,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las gradas abarrotadas ... por miles de aficionados.'::text,'están ocupadas'::text,'ocupan'::text,'ocupando'::text,'Las gradas abarrotadas están ocupadas por miles de aficionados.'::text),
(344993,38333,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les tribunes bondées ... par des milliers de fans.'::text,'sont remplies'::text,'remplissent'::text,'remplissant'::text,'Les tribunes bondées sont remplies par des milliers de fans.'::text),
(344996,38333,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalabalık tribünler binlerce taraftar tarafından ...'::text,'dolduruluyor'::text,'dolduruyor'::text,'doldurarak'::text,'Kalabalık tribünler binlerce taraftar tarafından dolduruluyor.'::text),
(344997,38333,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zsúfolt lelátókat több ezer szurkoló ...'::text,'tölti meg'::text,'tölt meg'::text,'megtöltve'::text,'A zsúfolt lelátókat több ezer szurkoló tölti meg.'::text),
(345000,38334,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Spiel ... wichtig sein, weil das Stadion so voll ist.'::text,'muss'::text,'kann nicht'::text,'muss nicht'::text,'Das Spiel muss wichtig sein, weil das Stadion so voll ist.'::text),
(345004,38334,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Матч ... бути важливим, бо стадіон такий переповнений.'::text,'має'::text,'не може'::text,'не мусить'::text,'Матч має бути важливим, бо стадіон такий переповнений.'::text),
(345003,38334,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El partido ... ser importante, porque el estadio está abarrotado.'::text,'debe de'::text,'no puede'::text,'no tiene que'::text,'El partido debe de ser importante, porque el estadio está abarrotado.'::text),
(345002,38334,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le match ... être important, parce que le stade est tellement bondé.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas nécessairement'::text,'Le match doit être important, parce que le stade est tellement bondé.'::text),
(345005,38334,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Maç önemli ..., çünkü stadyum çok kalabalık.'::text,'olmalı'::text,'olamaz'::text,'olmak zorunda değil'::text,'Maç önemli olmalı, çünkü stadyum çok kalabalık.'::text),
(345006,38334,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A meccsnek fontosnak ... lennie, mert annyira zsúfolt a stadion.'::text,'kell'::text,'nem lehet'::text,'nem kell'::text,'A meccsnek fontosnak kell lennie, mert annyira zsúfolt a stadion.'::text),
(345009,38335,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, angeblich liebt die Frau, ... in die Kamera gelächelt hat, volle Stadien.'::text,'die'::text,'was'::text,'deren'::text,'Girl, angeblich liebt die Frau, die in die Kamera gelächelt hat, volle Stadien.'::text),
(345013,38335,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, жінка, ... усміхнулася в камеру, обожнює переповнені стадіони.'::text,'яка'::text,'що'::text,'чия'::text,'Подруго, кажуть, жінка, яка усміхнулася в камеру, обожнює переповнені стадіони.'::text),
(345012,38335,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer, la mujer ... sonrió a la cámara adora los estadios abarrotados.'::text,'que'::text,'la cual'::text,'cuya'::text,'Tía, al parecer, la mujer que sonrió a la cámara adora los estadios abarrotados.'::text),
(345011,38335,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment la femme ... a souri à la caméra adore les stades bondés.'::text,'qui'::text,'laquelle'::text,'dont'::text,'Meuf, apparemment la femme qui a souri à la caméra adore les stades bondés.'::text),
(345014,38335,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre kameraya gülümseyen ... kadın kalabalık stadyumlara bayılıyormuş.'::text,''::text,NULL::text,NULL::text,'Kızım, duyduğuma göre kameraya gülümseyen kadın kalabalık stadyumlara bayılıyormuş.'::text),
(345015,38335,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a nő, ... a kamerába mosolygott, imádja a zsúfolt stadionokat.'::text,'aki'::text,'amely'::text,'akinek a'::text,'Csajszi, állítólag a nő, aki a kamerába mosolygott, imádja a zsúfolt stadionokat.'::text),
(345018,38336,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat mir gesagt, das Stadion ... noch nie so voll gewesen.'::text,'sei'::text,'ist'::text,'ist'::text,'Hör zu, sie hat mir gesagt, das Stadion sei noch nie so voll gewesen.'::text),
(345022,38336,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона сказала мені, що стадіон ще ніколи ... таким переповненим.'::text,'не був'::text,'не був'::text,'не є'::text,'Слухай, вона сказала мені, що стадіон ще ніколи не був таким переповненим.'::text),
(345021,38336,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que el estadio nunca ... tan lleno.'::text,'había estado'::text,'ha estado'::text,'está'::text,'Oye, me dijo que el estadio nunca había estado tan lleno.'::text),
(345020,38336,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle m''a dit que le stade ... aussi bondé.'::text,'n''avait jamais été'::text,'n''a jamais été'::text,'n''est jamais'::text,'Écoute, elle m''a dit que le stade n''avait jamais été aussi bondé.'::text),
(345023,38336,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana stadyumun daha önce hiç bu kadar kalabalık ... söyledi.'::text,'olmadığını'::text,'olmadığını'::text,'olmadığını'::text,'Dinle, bana stadyumun daha önce hiç bu kadar kalabalık olmadığını söyledi.'::text),
(345024,38336,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy a stadion még soha ... ilyen zsúfolt.'::text,'nem volt'::text,'nem volt'::text,'nincs'::text,'Figyelj, azt mondta, hogy a stadion még soha nem volt ilyen zsúfolt.'::text),
(345027,38337,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Echt jetzt, angeblich ... sie volle Orte, bevor sie diese Tickets bekam.'::text,'hasste früher'::text,'hasste immer'::text,'war gewohnt zu hassen'::text,'Echt jetzt, angeblich hasste früher sie volle Orte, bevor sie diese Tickets bekam.'::text),
(345031,38337,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Та ну, кажуть, вона ... людні місця, поки не отримала ці квитки.'::text,'колись ненавиділа'::text,'бувало, ненавиділа'::text,'звикла ненавидіти'::text,'Та ну, кажуть, вона колись ненавиділа людні місця, поки не отримала ці квитки.'::text),
(345030,38337,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué dices, al parecer ... los sitios abarrotados antes de conseguir estas entradas.'::text,'solía odiar'::text,'odiaba'::text,'estaba acostumbrada a odiar'::text,'Qué dices, al parecer solía odiar los sitios abarrotados antes de conseguir estas entradas.'::text),
(345029,38337,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sérieux, apparemment elle ... les endroits bondés avant d''avoir ces billets.'::text,'détestait'::text,'détestait souvent'::text,'avait l''habitude de détester'::text,'Sérieux, apparemment elle détestait les endroits bondés avant d''avoir ces billets.'::text),
(345032,38337,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok artık, duyduğuma göre bu biletleri almadan önce kalabalık yerlerden ...'::text,'nefret edermiş'::text,'nefret edermiş'::text,'nefret etmeye alışkınmış'::text,'Yok artık, duyduğuma göre bu biletleri almadan önce kalabalık yerlerden nefret edermiş.'::text),
(345033,38337,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne már, állítólag régen ... a zsúfolt helyeket, mielőtt megkapta ezeket a jegyeket.'::text,'utálta'::text,'utálta'::text,'hozzá volt szokva utálni'::text,'Ne már, állítólag régen utálta a zsúfolt helyeket, mielőtt megkapta ezeket a jegyeket.'::text),
(345045,38339,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... dieses volle Stadion seit April jede Woche, Respekt.'::text,'besuchst'::text,'besuchst'::text,'besuchst gerade'::text,'Ehrlich, du besuchst dieses volle Stadion seit April jede Woche, Respekt.'::text),
(345049,38339,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... цей переповнений стадіон щотижня з квітня, респект.'::text,'відвідуєш'::text,'відвідуєш'::text,'відвідуєш'::text,'Чесно, ти відвідуєш цей переповнений стадіон щотижня з квітня, респект.'::text),
(345048,38339,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, ... este estadio abarrotado cada semana desde abril, respeto.'::text,'has visitado'::text,'visitas'::text,'estás visitando'::text,'Sinceramente, has visitado este estadio abarrotado cada semana desde abril, respeto.'::text),
(345047,38339,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... ce stade bondé chaque semaine depuis avril, respect.'::text,'fréquentes'::text,'fréquentes'::text,'es en train de fréquenter'::text,'Franchement, tu fréquentes ce stade bondé chaque semaine depuis avril, respect.'::text),
(345050,38339,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası nisandan beri her hafta bu kalabalık stadyuma ..., helal.'::text,'geliyorsun'::text,'geliyorsun'::text,'geliyorsun'::text,'Açıkçası nisandan beri her hafta bu kalabalık stadyuma geliyorsun, helal.'::text),
(345051,38339,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, április óta minden héten ... ebbe a zsúfolt stadionba, respekt.'::text,'eljársz'::text,'eljársz'::text,'jössz'::text,'Őszintén, április óta minden héten eljársz ebbe a zsúfolt stadionba, respekt.'::text),
(372459,41385,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn eine Glasplatte gegen den Rahmen ..., bekommt sie einen Sprung. Makelloses Teamwork, offensichtlich.'::text,'stößt'::text,'stieß'::text,'stoßen wird'::text,'Wenn eine Glasplatte gegen den Rahmen stößt, bekommt sie einen Sprung. Makelloses Teamwork, offensichtlich.'::text),
(372463,41385,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо скляна панель ... об раму, вона тріскається. Бездоганна командна робота, звісно.'::text,'вдаряється'::text,'вдарилася'::text,'вдариться'::text,'Якщо скляна панель вдаряється об раму, вона тріскається. Бездоганна командна робота, звісно.'::text),
(372462,41385,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un panel de vidrio ... contra el marco, se agrieta. Trabajo en equipo impecable, obviamente.'::text,'choca'::text,'chocó'::text,'chocará'::text,'Si un panel de vidrio choca contra el marco, se agrieta. Trabajo en equipo impecable, obviamente.'::text),
(372461,41385,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un panneau de verre ... contre le cadre, il se fissure. Travail d''équipe impeccable, évidemment.'::text,'cogne'::text,'a cogné'::text,'cognera'::text,'Si un panneau de verre cogne contre le cadre, il se fissure. Travail d''équipe impeccable, évidemment.'::text),
(372464,41385,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cam panel çerçeveye ..., çatlar. Kusursuz takım çalışması, belli ki.'::text,'çarparsa'::text,'çarptıysa'::text,'çarpacaksa'::text,'Cam panel çerçeveye çarparsa, çatlar. Kusursuz takım çalışması, belli ki.'::text),
(372465,41385,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy üvegpanel ... a keretnek, megreped. Hibátlan csapatmunka, nyilván.'::text,'nekiütődik'::text,'nekiütődött'::text,'neki fog ütődni'::text,'Ha egy üvegpanel nekiütődik a keretnek, megreped. Hibátlan csapatmunka, nyilván.'::text),
(372468,41386,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie noch eine Platte fallen lassen, ... die Kuppel ein hübsches Open-Air-Design. Super Arbeit.'::text,'bekommt'::text,'würde bekommen'::text,'bekam'::text,'Wenn sie noch eine Platte fallen lassen, bekommt die Kuppel ein hübsches Open-Air-Design. Super Arbeit.'::text),
(372472,41386,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вони впустять ще одну панель, купол ... чудовий дизайн просто неба. Чудова робота.'::text,'отримає'::text,'отримав би'::text,'отримав'::text,'Якщо вони впустять ще одну панель, купол отримає чудовий дизайн просто неба. Чудова робота.'::text),
(372471,41386,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se les cae un panel más, la cúpula ... un precioso diseño al aire libre. Buen trabajo.'::text,'tendrá'::text,'tendría'::text,'tuvo'::text,'Si se les cae un panel más, la cúpula tendrá un precioso diseño al aire libre. Buen trabajo.'::text),
(372470,41386,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils font tomber un panneau de plus, le dôme ... un joli design à ciel ouvert. Bravo.'::text,'aura'::text,'aurait'::text,'a eu'::text,'S''ils font tomber un panneau de plus, le dôme aura un joli design à ciel ouvert. Bravo.'::text),
(372473,41386,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir panel daha düşürürlerse kubbe güzel bir açık hava tasarımına ..., harika iş.'::text,'kavuşacak'::text,'kavuşurdu'::text,'kavuştu'::text,'Bir panel daha düşürürlerse kubbe güzel bir açık hava tasarımına kavuşacak, harika iş.'::text),
(372474,41386,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még egy panelt leejtenek, a kupola ... egy szép szabadtéri dizájnt. Szép munka.'::text,'kap'::text,'kapna'::text,'kapott'::text,'Ha még egy panelt leejtenek, a kupola kap egy szép szabadtéri dizájnt. Szép munka.'::text),
(372477,41387,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, ich ... jede einzelne dieser Glasplatten fallen lassen, wenn ich sie heben müsste, ohne Witz.'::text,'würde'::text,'werde'::text,'lasse'::text,'Digga, ich würde jede einzelne dieser Glasplatten fallen lassen, wenn ich sie heben müsste, ohne Witz.'::text),
(372481,41387,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якби мені довелося піднімати ці скляні панелі, я ... кожну, без брехні.'::text,'впустив би'::text,'впущу'::text,'впускаю'::text,'Бро, якби мені довелося піднімати ці скляні панелі, я впустив би кожну, без брехні.'::text),
(372480,41387,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si tuviera que levantar esos paneles de vidrio, ... todos y cada uno, sin mentira.'::text,'se me caerían'::text,'se me caerán'::text,'se me caen'::text,'Bro, si tuviera que levantar esos paneles de vidrio, se me caerían todos y cada uno, sin mentira.'::text),
(372479,41387,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si je devais soulever ces panneaux de verre, je les ... tous, sans mentir.'::text,'ferais tomber'::text,'ferai tomber'::text,'fais tomber'::text,'Frérot, si je devais soulever ces panneaux de verre, je les ferais tomber tous, sans mentir.'::text),
(372482,41387,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o cam panelleri kaldırmam gerekseydi hepsini tek tek ..., yalan yok.'::text,'düşürürdüm'::text,'düşüreceğim'::text,'düşürüyorum'::text,'Kanka, o cam panelleri kaldırmam gerekseydi hepsini tek tek düşürürdüm, yalan yok.'::text),
(372483,41387,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha nekem kéne emelgetni ezeket az üvegpaneleket, mindegyiket ..., nem kamu.'::text,'leejteném'::text,'le fogom ejteni'::text,'leejtem'::text,'Tesó, ha nekem kéne emelgetni ezeket az üvegpaneleket, mindegyiket leejteném, nem kamu.'::text),
(372495,41389,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Team ... bis zur Deadline 240 Glasplatten in den Kuppelrahmen ein.'::text,'setzte'::text,'wurde gesetzt'::text,'setzend'::text,'Das Team setzte bis zur Deadline 240 Glasplatten in den Kuppelrahmen ein.'::text),
(372499,41389,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Команда ... 240 скляних панелей у каркас купола до дедлайну.'::text,'встановила'::text,'була встановлена'::text,'встановлюючи'::text,'Команда встановила 240 скляних панелей у каркас купола до дедлайну.'::text),
(372498,41389,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El equipo ... 240 paneles de vidrio en la estructura de la cúpula antes de la fecha límite.'::text,'instaló'::text,'fue instalado'::text,'instalando'::text,'El equipo instaló 240 paneles de vidrio en la estructura de la cúpula antes de la fecha límite.'::text),
(372497,41389,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''équipe ... 240 panneaux de verre dans la structure du dôme avant la deadline.'::text,'a posé'::text,'a été posée'::text,'posant'::text,'L''équipe a posé 240 panneaux de verre dans la structure du dôme avant la deadline.'::text),
(372500,41389,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekip, son tarihe kadar kubbe iskeletine 240 cam panel ...'::text,'yerleştirdi'::text,'yerleştirildi'::text,'yerleştirerek'::text,'Ekip, son tarihe kadar kubbe iskeletine 240 cam panel yerleştirdi.'::text),
(372501,41389,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csapat a határidőig 240 üvegpanelt ... be a kupola vázába.'::text,'szerelt'::text,'lett szerelve'::text,'szerelve'::text,'A csapat a határidőig 240 üvegpanelt szerelt be a kupola vázába.'::text),
(372504,41390,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Glasplatten sehen sehr schwer aus, also ... sie viel wiegen.'::text,'müssen'::text,'können nicht'::text,'dürfen nicht'::text,'Die Glasplatten sehen sehr schwer aus, also müssen sie viel wiegen.'::text),
(372508,41390,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Скляні панелі виглядають дуже важкими, тож вони ... багато важити.'::text,'мають'::text,'не можуть'::text,'не повинні'::text,'Скляні панелі виглядають дуже важкими, тож вони мають багато важити.'::text),
(372507,41390,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los paneles de vidrio parecen muy pesados, así que ... pesar mucho.'::text,'deben de'::text,'no pueden'::text,'no deben'::text,'Los paneles de vidrio parecen muy pesados, así que deben de pesar mucho.'::text),
(372506,41390,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les panneaux de verre ont l''air très lourds, alors ils ... peser beaucoup.'::text,'doivent'::text,'ne peuvent pas'::text,'ne doivent pas'::text,'Les panneaux de verre ont l''air très lourds, alors ils doivent peser beaucoup.'::text),
(372509,41390,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cam paneller çok ağır görünüyor, yani çok ağır ...'::text,'olmalılar'::text,'olamazlar'::text,'olmamalılar'::text,'Cam paneller çok ağır görünüyor, yani çok ağır olmalılar.'::text),
(372510,41390,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az üvegpanelek nagyon nehéznek tűnnek, szóval sokat ... nyomniuk.'::text,'kell'::text,'nem lehet'::text,'nem szabad'::text,'Az üvegpanelek nagyon nehéznek tűnnek, szóval sokat kell nyomniuk.'::text),
(372513,41391,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Bauwerk, ... aus Hunderten Glasplatten besteht, befindet sich in einem Wald.'::text,'welches'::text,'das'::text,'wer'::text,'Das Bauwerk, welches aus Hunderten Glasplatten besteht, befindet sich in einem Wald.'::text),
(372517,41391,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Споруда, ... складається із сотень скляних панелей, розташована в лісі.'::text,'яка'::text,'що'::text,'хто'::text,'Споруда, яка складається із сотень скляних панелей, розташована в лісі.'::text),
(372516,41391,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La estructura, ... consta de cientos de paneles de vidrio, se encuentra en un bosque.'::text,'la cual'::text,'que'::text,'quien'::text,'La estructura, la cual consta de cientos de paneles de vidrio, se encuentra en un bosque.'::text),
(372515,41391,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La structure, ... se compose de centaines de panneaux de verre, se trouve dans une forêt.'::text,'qui'::text,'qui'::text,'qui'::text,'La structure, qui se compose de centaines de panneaux de verre, se trouve dans une forêt.'::text),
(372518,41391,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yüzlerce cam panelden oluşan ... yapı bir ormanda bulunuyor.'::text,''::text,NULL::text,NULL::text,'Yüzlerce cam panelden oluşan yapı bir ormanda bulunuyor.'::text),
(372519,41391,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az építmény, ... több száz üvegpanelből áll, egy erdőben található.'::text,'amely'::text,'ami'::text,'aki'::text,'Az építmény, amely több száz üvegpanelből áll, egy erdőben található.'::text),
(372522,41392,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gärtnerin schrie, sie ... nie wieder eine Glasplatte heben!'::text,'würde'::text,'wird'::text,'will'::text,'Die Gärtnerin schrie, sie würde nie wieder eine Glasplatte heben!'::text),
(372526,41392,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Садівниця кричала, що вона більше ніколи ... жодної скляної панелі!'::text,'не підніме'::text,'не підніме'::text,'не хоче піднімати'::text,'Садівниця кричала, що вона більше ніколи не підніме жодної скляної панелі!'::text),
(372525,41392,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La jardinera gritó que nunca más ... otro panel de vidrio!'::text,'levantaría'::text,'levantará'::text,'quiere levantar'::text,'¡La jardinera gritó que nunca más levantaría otro panel de vidrio!'::text),
(372524,41392,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La jardinière a hurlé qu''elle ne ... plus jamais de panneau de verre !'::text,'soulèverait'::text,'soulèvera'::text,'veut soulever'::text,'La jardinière a hurlé qu''elle ne soulèverait plus jamais de panneau de verre !'::text),
(372527,41392,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bahçıvan bir daha asla cam panel ... bağırdı!'::text,'kaldırmayacağını'::text,'kaldırmayacağını'::text,'kaldırmak istemediğini'::text,'Bahçıvan bir daha asla cam panel kaldırmayacağını bağırdı!'::text),
(372528,41392,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kertésznő azt sikította, hogy soha többé nem ... egyetlen üvegpanelt sem!'::text,'emel fel'::text,'fog felemelni'::text,'akar felemelni'::text,'A kertésznő azt sikította, hogy soha többé nem emel fel egyetlen üvegpanelt sem!'::text),
(372531,41393,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor Jahren ... die Gärtner jede Glasplatte eine Leiter hinauf.'::text,'trugen'::text,'trugen'::text,'waren gewohnt zu tragen'::text,'Vor Jahren trugen die Gärtner jede Glasplatte eine Leiter hinauf.'::text),
(372535,41393,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Багато років тому садівники ... кожну скляну панель драбиною нагору.'::text,'носили'::text,'носили'::text,'звикли носити'::text,'Багато років тому садівники носили кожну скляну панель драбиною нагору.'::text),
(372534,41393,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hace años, los jardineros ... cada panel de vidrio escalera arriba.'::text,'subían'::text,'subían'::text,'estaban acostumbrados a subir'::text,'Hace años, los jardineros subían cada panel de vidrio escalera arriba.'::text),
(372533,41393,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il y a des années, les jardiniers ... chaque panneau de verre en haut d''une échelle.'::text,'montaient'::text,'montaient'::text,'avaient l''habitude de monter'::text,'Il y a des années, les jardiniers montaient chaque panneau de verre en haut d''une échelle.'::text),
(372536,41393,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yıllar önce bahçıvanlar her cam paneli merdivenle yukarı ...'::text,'taşırdı'::text,'taşırdı'::text,'taşımaya alışkındı'::text,'Yıllar önce bahçıvanlar her cam paneli merdivenle yukarı taşırdı.'::text),
(372537,41393,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évekkel ezelőtt a kertészek minden üvegpanelt létrán ... fel.'::text,'vitték'::text,'vitték'::text,'hozzá voltak szokva vinni'::text,'Évekkel ezelőtt a kertészek minden üvegpanelt létrán vitték fel.'::text),
(372540,41394,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gärtner beendeten das ... der letzten Glasplatte in den Rahmen.'::text,'Einsetzen'::text,'einzusetzen'::text,'einsetzen'::text,'Die Gärtner beendeten das Einsetzen der letzten Glasplatte in den Rahmen.'::text),
(372544,41394,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Садівники закінчили ... останньої скляної панелі в раму.'::text,'встановлення'::text,'встановити'::text,'встановити'::text,'Садівники закінчили встановлення останньої скляної панелі в раму.'::text),
(372543,41394,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los jardineros terminaron de ... el último panel de vidrio en el marco.'::text,'colocar'::text,'colocar'::text,'colocar'::text,'Los jardineros terminaron de colocar el último panel de vidrio en el marco.'::text),
(372542,41394,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les jardiniers ont fini de ... le dernier panneau de verre dans le cadre.'::text,'poser'::text,'poser'::text,'poser'::text,'Les jardiniers ont fini de poser le dernier panneau de verre dans le cadre.'::text),
(372545,41394,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bahçıvanlar son cam paneli çerçeveye ... bitirdi.'::text,'yerleştirmeyi'::text,'yerleştirmeyi'::text,'yerleştirmek'::text,'Bahçıvanlar son cam paneli çerçeveye yerleştirmeyi bitirdi.'::text),
(372546,41394,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kertészek befejezték az utolsó üvegpanel ... a keretbe.'::text,'beillesztését'::text,'beilleszteni'::text,'beilleszt'::text,'A kertészek befejezték az utolsó üvegpanel beillesztését a keretbe.'::text),
(372549,41395,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Glasplatten sind schwer, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Die Glasplatten sind schwer, oder?'::text),
(372553,41395,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Скляні панелі важкі, ...?'::text,'правда ж'::text,'правда ж'::text,'правда ж'::text,'Скляні панелі важкі, правда ж?'::text),
(372552,41395,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los paneles de vidrio son pesados, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Los paneles de vidrio son pesados, ¿verdad?'::text),
(372551,41395,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les panneaux de verre sont lourds, ... ?'::text,'non'::text,'non'::text,'non'::text,'Les panneaux de verre sont lourds, non ?'::text),
(372554,41395,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cam paneller ağır, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Cam paneller ağır, değil mi?'::text),
(372555,41395,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nehezek az üvegpanelek, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Nehezek az üvegpanelek, ugye?'::text),
(391116,43458,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte der Stapel das Protokoll befolgt, ... die 20 Paletten jetzt noch auf dem Rasen.'::text,'stünden'::text,'hätten gestanden'::text,'werden stehen'::text,'Hätte der Stapel das Protokoll befolgt, stünden die 20 Paletten jetzt noch auf dem Rasen.'::text),
(391120,43458,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби штабель дотримався протоколу, 20 палет ... на газоні досі.'::text,'стояли б'::text,'стояли б'::text,'стоятимуть'::text,'Якби штабель дотримався протоколу, 20 палет стояли б на газоні досі.'::text),
(391119,43458,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la pila hubiera seguido el protocolo, los 20 palés ... en el césped ahora.'::text,'seguirían en pie'::text,'habrían seguido en pie'::text,'seguirán en pie'::text,'Si la pila hubiera seguido el protocolo, los 20 palés seguirían en pie en el césped ahora.'::text),
(391118,43458,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la pile avait respecté le protocole, les 20 palettes ... sur la pelouse maintenant.'::text,'seraient encore debout'::text,'auraient encore tenu'::text,'seront encore debout'::text,'Si la pile avait respecté le protocole, les 20 palettes seraient encore debout sur la pelouse maintenant.'::text),
(391121,43458,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yığın protokole uysaydı, 20 palet şu anda hâlâ çimlerin üzerinde ...'::text,'duruyor olurdu'::text,'durmuş olurdu'::text,'duracak'::text,'Yığın protokole uysaydı, 20 palet şu anda hâlâ çimlerin üzerinde duruyor olurdu.'::text),
(391122,43458,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a rakás betartotta volna a protokollt, a 20 raklap most is ... a gyepen.'::text,'állna'::text,'állt volna'::text,'állni fog'::text,'Ha a rakás betartotta volna a protokollt, a 20 raklap most is állna a gyepen.'::text),
(391125,43459,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der hohe Stapel soll von einer Windböe ...'::text,'umgeworfen worden sein'::text,'umwerfen'::text,'umwerfend'::text,'Der hohe Stapel soll von einer Windböe umgeworfen worden sein.'::text),
(391129,43459,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважається, що високий штабель ... поривом вітру.'::text,'був повалений'::text,'повалити'::text,'повалюючи'::text,'Вважається, що високий штабель був повалений поривом вітру.'::text),
(391128,43459,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que la alta pila ... por una ráfaga de viento.'::text,'fue derribada'::text,'derribar'::text,'derribando'::text,'Se cree que la alta pila fue derribada por una ráfaga de viento.'::text),
(391127,43459,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que la haute pile ... par une rafale de vent.'::text,'a été renversée'::text,'renverser'::text,'renversant'::text,'On pense que la haute pile a été renversée par une rafale de vent.'::text),
(391130,43459,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yüksek yığının bir rüzgâr esintisiyle ... düşünülüyor.'::text,'devrildiği'::text,'devirmek'::text,'devirerek'::text,'Yüksek yığının bir rüzgâr esintisiyle devrildiği düşünülüyor.'::text),
(391131,43459,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy vélik, hogy a magas rakást egy széllökés ...'::text,'döntötte fel'::text,'feldönteni'::text,'feldöntve'::text,'Úgy vélik, hogy a magas rakást egy széllökés döntötte fel.'::text),
(391134,43460,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Beobachter bestritt, den Stapel ..., und gab an, er sei aufgrund seiner eigenen Höhe eingestürzt.'::text,'berührt zu haben'::text,'zu berühren'::text,'berührt'::text,'Der Beobachter bestritt, den Stapel berührt zu haben, und gab an, er sei aufgrund seiner eigenen Höhe eingestürzt.'::text),
(391138,43460,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Спостерігач заперечив, що ... штабеля, і заявив, що той обвалився через власну висоту.'::text,'торкався'::text,'торкатися'::text,'торкався'::text,'Спостерігач заперечив, що торкався штабеля, і заявив, що той обвалився через власну висоту.'::text),
(391137,43460,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El observador negó ... la pila y afirmó que se derrumbó por su propia altura.'::text,'haber tocado'::text,'tocar'::text,'tocó'::text,'El observador negó haber tocado la pila y afirmó que se derrumbó por su propia altura.'::text),
(391136,43460,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''observateur a nié ... la pile, affirmant qu''elle s''était effondrée à cause de sa propre hauteur.'::text,'avoir touché'::text,'toucher'::text,'touché'::text,'L''observateur a nié avoir touché la pile, affirmant qu''elle s''était effondrée à cause de sa propre hauteur.'::text),
(391139,43460,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gözlemci yığına ... inkâr etti ve yığının kendi yüksekliği yüzünden çöktüğünü belirtti.'::text,'dokunduğunu'::text,'dokunmayı'::text,'dokundu'::text,'Gözlemci yığına dokunduğunu inkâr etti ve yığının kendi yüksekliği yüzünden çöktüğünü belirtti.'::text),
(391140,43460,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A megfigyelő tagadta, hogy ... a rakáshoz, és kijelentette, hogy az a saját magassága miatt omlott össze.'::text,'hozzáért volna'::text,'hozzáérni'::text,'hozzáért'::text,'A megfigyelő tagadta, hogy hozzáért volna a rakáshoz, és kijelentette, hogy az a saját magassága miatt omlott össze.'::text),
(391143,43461,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hätten den Stapel nicht so hoch bauen ...! Der ganze Garten ist eine Katastrophe!'::text,'sollen'::text,'dürfen'::text,'können'::text,'Sie hätten den Stapel nicht so hoch bauen sollen! Der ganze Garten ist eine Katastrophe!'::text),
(391147,43461,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... будувати штабель так високо! Увесь сад — катастрофа!'::text,'не мали'::text,'не сміли'::text,'не могли'::text,'Вони не мали будувати штабель так високо! Увесь сад — катастрофа!'::text),
(391146,43461,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No ... construido la pila tan alta! ¡Todo el jardín es un desastre!'::text,'deberían haber'::text,'tenían que haber'::text,'podían haber'::text,'¡No deberían haber construido la pila tan alta! ¡Todo el jardín es un desastre!'::text),
(391145,43461,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... construire la pile aussi haut ! Tout le jardin est un désastre !'::text,'n''auraient pas dû'::text,'ne devaient pas'::text,'ne pouvaient pas'::text,'Ils n''auraient pas dû construire la pile aussi haut ! Tout le jardin est un désastre !'::text),
(391148,43461,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yığını o kadar yüksek ...! Bütün bahçe felaket!'::text,'yapmamalıydılar'::text,'yapmamalıydılar'::text,'yapamazlardı'::text,'Yığını o kadar yüksek yapmamalıydılar! Bütün bahçe felaket!'::text),
(391149,43461,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem ... ilyen magasra építeniük a rakást! Az egész kert egy katasztrófa!'::text,'kellett volna'::text,'lett volna szabad'::text,'tudták'::text,'Nem kellett volna ilyen magasra építeniük a rakást! Az egész kert egy katasztrófa!'::text),
(391152,43462,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaum ... der Stapel aufgebaut, da krachte er in ein totales Chaos!'::text,'war'::text,NULL::text,'war'::text,'Kaum war der Stapel aufgebaut, da krachte er in ein totales Chaos!'::text),
(391156,43462,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ледве штабель ... постав, як обвалився в повний хаос!'::text,''::text,NULL::text,NULL::text,'Ледве штабель постав, як обвалився в повний хаос!'::text),
(391155,43462,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Apenas ... levantado la pila cuando se derrumbó en un caos total!'::text,'se había'::text,NULL::text,'estaba'::text,'¡Apenas se había levantado la pila cuando se derrumbó en un caos total!'::text),
(391154,43462,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À peine la pile ... debout qu''elle s''est écroulée dans un chaos total !'::text,'était'::text,NULL::text,'était'::text,'À peine la pile était debout qu''elle s''est écroulée dans un chaos total !'::text),
(391157,43462,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yığın ... ayağa kalkar kalkmaz tam bir kaosla yıkıldı!'::text,''::text,NULL::text,NULL::text,'Yığın ayağa kalkar kalkmaz tam bir kaosla yıkıldı!'::text),
(391158,43462,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alig ... állt fel a rakás, máris teljes káoszba omlott!'::text,''::text,NULL::text,NULL::text,'Alig állt fel a rakás, máris teljes káoszba omlott!'::text),
(391161,43463,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Wir müssen jemanden holen, der diesen Stapel ..., bevor er den Zaun zerstört!'::text,'wieder aufbaut'::text,'wieder aufbaut'::text,'Wiederaufbauen'::text,'Albtraum! Wir müssen jemanden holen, der diesen Stapel wieder aufbaut, bevor er den Zaun zerstört!'::text),
(391165,43463,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Треба знайти когось, хто ... цей штабель, поки він не зруйнував паркан!'::text,'перебудує'::text,'перебудує'::text,'перебудова'::text,'Жах! Треба знайти когось, хто перебудує цей штабель, поки він не зруйнував паркан!'::text),
(391164,43463,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡Tenemos que conseguir que alguien ... esta pila antes de que destroce la valla!'::text,'vuelva a montar'::text,'vuelva a montar'::text,'volviendo a montar'::text,'¡Pesadilla! ¡Tenemos que conseguir que alguien vuelva a montar esta pila antes de que destroce la valla!'::text),
(391163,43463,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Il faut trouver quelqu''un pour ... cette pile avant qu''elle détruise la clôture !'::text,'reconstruire'::text,'reconstruire'::text,'reconstruisant'::text,'Cauchemar ! Il faut trouver quelqu''un pour reconstruire cette pile avant qu''elle détruise la clôture !'::text),
(391166,43463,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Çiti yıkmadan önce bu yığını birine ... lazım!'::text,'yeniden kurdurmamız'::text,'yeniden kurdurmamız'::text,'yeniden kurarak'::text,'Kâbus! Çiti yıkmadan önce bu yığını birine yeniden kurdurmamız lazım!'::text),
(391167,43463,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! Kerítenünk kell valakit, aki ... ezt a rakást, mielőtt tönkreteszi a kerítést!'::text,'újraépíti'::text,'újraépíti'::text,'újraépítés'::text,'Rémálom! Kerítenünk kell valakit, aki újraépíti ezt a rakást, mielőtt tönkreteszi a kerítést!'::text),
(391170,43464,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann wünscht, der Stapel ... nicht so hoch gewesen.'::text,'wäre'::text,'war'::text,'würde'::text,'Der Mann wünscht, der Stapel wäre nicht so hoch gewesen.'::text),
(391174,43464,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік хотів би, щоб штабель ... таким високим.'::text,'не був'::text,'не був'::text,'не був'::text,'Чоловік хотів би, щоб штабель не був таким високим.'::text),
(391173,43464,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre desearía que la pila no ... tan alta.'::text,'hubiera sido'::text,'fuera'::text,'sería'::text,'El hombre desearía que la pila no hubiera sido tan alta.'::text),
(391172,43464,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme aurait voulu que la pile ... si haute.'::text,'n''ait pas été'::text,'ne soit pas'::text,'ne serait pas'::text,'L''homme aurait voulu que la pile n''ait pas été si haute.'::text),
(391175,43464,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam keşke yığın o kadar yüksek ... diye düşünüyor.'::text,'olmasaydı'::text,'olmasa'::text,'olmayacak'::text,'Adam keşke yığın o kadar yüksek olmasaydı diye düşünüyor.'::text),
(391176,43464,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi azt kívánja, bárcsak a rakás ne ... ilyen magas.'::text,'lett volna'::text,'lenne'::text,'lenne'::text,'A férfi azt kívánja, bárcsak a rakás ne lett volna ilyen magas.'::text),
(391188,43466,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Allgemeinen fallen ... aus Paletten um, wenn sie zu hoch werden.'::text,'Stapel'::text,'die Stapel'::text,'ein Stapel'::text,'Im Allgemeinen fallen Stapel aus Paletten um, wenn sie zu hoch werden.'::text),
(391192,43466,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Загалом ... палет перекидаються, коли стають зависокими.'::text,'штабелі'::text,'штабелі'::text,'штабель'::text,'Загалом штабелі палет перекидаються, коли стають зависокими.'::text),
(391191,43466,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En general, ... de palés se caen cuando son demasiado altas.'::text,'las pilas'::text,'las pilas'::text,'unas pilas'::text,'En general, las pilas de palés se caen cuando son demasiado altas.'::text),
(391190,43466,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En général, ... de palettes tombent quand elles deviennent trop hautes.'::text,'les piles'::text,'les piles'::text,'des piles'::text,'En général, les piles de palettes tombent quand elles deviennent trop hautes.'::text),
(391193,43466,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genel olarak palet ... çok yükseldiğinde devrilir.'::text,'yığınları'::text,'yığınları'::text,'bir yığın'::text,'Genel olarak palet yığınları çok yükseldiğinde devrilir.'::text),
(391194,43466,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában ... feldőlnek, ha túl magasra nőnek.'::text,'a raklaprakások'::text,'a raklaprakások'::text,'egy raklaprakás'::text,'Általában a raklaprakások feldőlnek, ha túl magasra nőnek.'::text),
(391197,43467,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Stapel fiel ... der sorgfältigen Arbeit des Erbauers um.'::text,'trotz'::text,'wegen'::text,'obwohl'::text,'Der Stapel fiel trotz der sorgfältigen Arbeit des Erbauers um.'::text),
(391201,43467,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Штабель перекинувся ... ретельну роботу будівельника.'::text,'попри'::text,'через'::text,'хоча'::text,'Штабель перекинувся попри ретельну роботу будівельника.'::text),
(391200,43467,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pila se cayó ... el cuidadoso trabajo del constructor.'::text,'a pesar de'::text,'debido a'::text,'aunque'::text,'La pila se cayó a pesar de el cuidadoso trabajo del constructor.'::text),
(391199,43467,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pile s''est renversée ... le travail soigné du constructeur.'::text,'malgré'::text,'à cause de'::text,'bien que'::text,'La pile s''est renversée malgré le travail soigné du constructeur.'::text),
(391202,43467,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yığın, yapan kişinin özenli çalışmasına ... devrildi.'::text,'rağmen'::text,'yüzünden'::text,'halde'::text,'Yığın, yapan kişinin özenli çalışmasına rağmen devrildi.'::text),
(391203,43467,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rakás feldőlt az építő gondos munkája ...'::text,'ellenére'::text,'miatt'::text,'bár'::text,'A rakás feldőlt az építő gondos munkája ellenére.'::text),
(391206,43468,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, wir wussten alle, dass der Stapel ..., der war echt viel zu hoch.'::text,'umfallen würde'::text,'umfallen wird'::text,'umfällt'::text,'Digga, wir wussten alle, dass der Stapel umfallen würde, der war echt viel zu hoch.'::text),
(391210,43468,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ми всі знали, що той штабель ..., він був реально зависокий.'::text,'впаде'::text,'впаде'::text,'падає'::text,'Бро, ми всі знали, що той штабель впаде, він був реально зависокий.'::text),
(391209,43468,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, todos sabíamos que esa pila ..., era demasiado alta, la verdad.'::text,'se caería'::text,'se caerá'::text,'se cae'::text,'Bro, todos sabíamos que esa pila se caería, era demasiado alta, la verdad.'::text),
(391208,43468,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, on savait tous que cette pile ..., elle était franchement beaucoup trop haute.'::text,'tomberait'::text,'tombera'::text,'tombe'::text,'Frérot, on savait tous que cette pile tomberait, elle était franchement beaucoup trop haute.'::text),
(391211,43468,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o yığının ... hepimiz biliyorduk, resmen fazla yüksekti.'::text,'devrileceğini'::text,'devrileceğini'::text,'devrildiğini'::text,'Kanka, o yığının devrileceğini hepimiz biliyorduk, resmen fazla yüksekti.'::text),
(391212,43468,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, mind tudtuk, hogy az a rakás ..., eléggé túl magas volt.'::text,'fel fog dőlni'::text,'fel fog dőlni'::text,'feldől'::text,'Tesó, mind tudtuk, hogy az a rakás fel fog dőlni, eléggé túl magas volt.'::text),
(393798,43756,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... fröhlich, als direkt hinter ihnen ein riesiges U-Boot auftauchte! Absoluter Albtraum!'::text,'schwammen'::text,'schwammen'::text,'sind geschwommen'::text,'Sie schwammen fröhlich, als direkt hinter ihnen ein riesiges U-Boot auftauchte! Absoluter Albtraum!'::text),
(393802,43756,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони весело ..., коли просто за ними виринув величезний підводний човен! Абсолютний жах!'::text,'плавали'::text,'попливли'::text,'попливли'::text,'Вони весело плавали, коли просто за ними виринув величезний підводний човен! Абсолютний жах!'::text),
(393801,43756,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... tan tranquilos cuando un submarino gigante emergió justo detrás de ellos! ¡Pesadilla absoluta!'::text,'Estaban nadando'::text,'Nadaron'::text,'Han nadado'::text,'¡Estaban nadando tan tranquilos cuando un submarino gigante emergió justo detrás de ellos! ¡Pesadilla absoluta!'::text),
(393800,43756,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... joyeusement quand un sous-marin géant a surgi juste derrière eux ! Cauchemar absolu !'::text,'nageaient'::text,'ont nagé'::text,'ont nagé'::text,'Ils nageaient joyeusement quand un sous-marin géant a surgi juste derrière eux ! Cauchemar absolu !'::text),
(393803,43756,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tam arkalarında dev bir denizaltı yükseldiğinde mutlu mutlu ...! Tam bir kâbus!'::text,'yüzüyorlardı'::text,'yüzdüler'::text,'yüzmüşler'::text,'Tam arkalarında dev bir denizaltı yükseldiğinde mutlu mutlu yüzüyorlardı! Tam bir kâbus!'::text),
(393804,43756,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vidáman ..., amikor egy óriási tengeralattjáró bukkant fel közvetlenül mögöttük! Abszolút rémálom!'::text,'úszkáltak'::text,'úsztak'::text,'úsztak'::text,'Vidáman úszkáltak, amikor egy óriási tengeralattjáró bukkant fel közvetlenül mögöttük! Abszolút rémálom!'::text),
(393816,43758,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, ich hab gehört, ein Wal ist rausgesprungen, während das U-Boot ...'::text,'auftauchte'::text,'auftauchte'::text,'aufgetaucht ist'::text,'Rate mal, ich hab gehört, ein Wal ist rausgesprungen, während das U-Boot auftauchte.'::text),
(393820,43758,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, я чула, що кит вистрибнув, поки підводний човен ...'::text,'виринав'::text,'виринув'::text,'виринув'::text,'Уяви, я чула, що кит вистрибнув, поки підводний човен виринав.'::text),
(393819,43758,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Sabes qué? Oí que una ballena saltó mientras el submarino ...'::text,'emergía'::text,'emergió'::text,'ha emergido'::text,'¿Sabes qué? Oí que una ballena saltó mientras el submarino emergía.'::text),
(393818,43758,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, j''ai entendu qu''une baleine a sauté pendant que le sous-marin ...'::text,'remontait'::text,'a remonté'::text,'a remonté'::text,'Devine quoi, j''ai entendu qu''une baleine a sauté pendant que le sous-marin remontait.'::text),
(393821,43758,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım ne oldu, denizaltı ... bir balinanın sudan fırladığını duydum.'::text,'yükselirken'::text,'yükseldi'::text,'yükselmiş'::text,'Bil bakalım ne oldu, denizaltı yükselirken bir balinanın sudan fırladığını duydum.'::text),
(393822,43758,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt hallottam, hogy kiugrott egy bálna, miközben a tengeralattjáró ...'::text,'emelkedett fel'::text,'felbukkant'::text,'felbukkant'::text,'Képzeld, azt hallottam, hogy kiugrott egy bálna, miközben a tengeralattjáró emelkedett fel.'::text),
(393825,43759,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, das U-Boot ... diesen Sommer schon zweimal in diesem See aufgetaucht.'::text,'ist'::text,'ist'::text,'taucht'::text,'Hör mal, ich hab gehört, das U-Boot ist diesen Sommer schon zweimal in diesem See aufgetaucht.'::text),
(393829,43759,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що той підводний човен цього літа ... в цьому озері двічі.'::text,'виринав'::text,'виринав'::text,'виринає'::text,'Слухай, я чула, що той підводний човен цього літа виринав в цьому озері двічі.'::text),
(393828,43759,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, he oído que ese submarino ... en este lago dos veces este verano.'::text,'ha salido'::text,'ha estado saliendo'::text,'está saliendo'::text,'Oye, he oído que ese submarino ha salido en este lago dos veces este verano.'::text),
(393827,43759,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu que ce sous-marin ... dans ce lac deux fois cet été.'::text,'a fait surface'::text,'fait surface'::text,'fait surface'::text,'Écoute, j''ai entendu que ce sous-marin a fait surface dans ce lac deux fois cet été.'::text),
(393830,43759,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, o denizaltının bu yaz bu gölde iki kez ... duydum.'::text,'yüzeye çıktığını'::text,'yüzeye çıktığını'::text,'yüzeye çıktığını'::text,'Dinle, o denizaltının bu yaz bu gölde iki kez yüzeye çıktığını duydum.'::text),
(393831,43759,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy az a tengeralattjáró idén nyáron már kétszer ... fel ebben a tóban.'::text,'bukkant'::text,'bukkant'::text,'bukkan'::text,'Figyelj, azt hallottam, hogy az a tengeralattjáró idén nyáron már kétszer bukkant fel ebben a tóban.'::text),
(393834,43760,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der Wal sprang, ... das U-Boot schon aus dem Wasser aufgetaucht.'::text,'war'::text,'ist'::text,'taucht'::text,'Als der Wal sprang, war das U-Boot schon aus dem Wasser aufgetaucht.'::text),
(393838,43760,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли кит вистрибнув, підводний човен уже ... з води.'::text,'виринув'::text,'виринув'::text,'виринає'::text,'Коли кит вистрибнув, підводний човен уже виринув з води.'::text),
(393837,43760,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando la ballena saltó, el submarino ya ... del agua.'::text,'había salido'::text,'ha salido'::text,'sale'::text,'Cuando la ballena saltó, el submarino ya había salido del agua.'::text),
(393836,43760,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand la baleine a sauté, le sous-marin ... de l''eau.'::text,'était déjà sorti'::text,'est déjà sorti'::text,'sort'::text,'Quand la baleine a sauté, le sous-marin était déjà sorti de l''eau.'::text),
(393839,43760,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Balina sıçradığında denizaltı sudan çoktan ...'::text,'çıkmıştı'::text,'çıktı'::text,'çıkıyor'::text,'Balina sıçradığında denizaltı sudan çoktan çıkmıştı.'::text),
(393840,43760,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a bálna kiugrott, a tengeralattjáró már ... a vízből.'::text,'kiemelkedett'::text,'kiemelkedett'::text,'kiemelkedik'::text,'Mire a bálna kiugrott, a tengeralattjáró már kiemelkedett a vízből.'::text),
(393843,43761,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das U-Boot noch näher kommt, ... die Schwimmer aus dem See.'::text,'steigen'::text,'würden steigen'::text,'stiegen'::text,'Wenn das U-Boot noch näher kommt, steigen die Schwimmer aus dem See.'::text),
(393847,43761,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо підводний човен підійде ще ближче, плавці ... з озера.'::text,'вийдуть'::text,'вийшли б'::text,'вийшли'::text,'Якщо підводний човен підійде ще ближче, плавці вийдуть з озера.'::text),
(393846,43761,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el submarino se acerca más, los nadadores ... del lago.'::text,'saldrán'::text,'saldrían'::text,'salieron'::text,'Si el submarino se acerca más, los nadadores saldrán del lago.'::text),
(393845,43761,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le sous-marin s''approche encore, les nageurs ... du lac.'::text,'sortiront'::text,'sortiraient'::text,'sont sortis'::text,'Si le sous-marin s''approche encore, les nageurs sortiront du lac.'::text),
(393848,43761,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Denizaltı biraz daha yaklaşırsa yüzücüler gölden ...'::text,'çıkacak'::text,'çıkarlardı'::text,'çıktı'::text,'Denizaltı biraz daha yaklaşırsa yüzücüler gölden çıkacak.'::text),
(393849,43761,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a tengeralattjáró még közelebb jön, az úszók ... a tóból.'::text,'kijönnek'::text,'kijönnének'::text,'kijöttek'::text,'Ha a tengeralattjáró még közelebb jön, az úszók kijönnek a tóból.'::text),
(393852,43762,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn hier kein U-Boot wäre, ... die Schwimmer in Ruhe.'::text,'schwämmen'::text,'werden schwimmen'::text,'schwimmen'::text,'Wenn hier kein U-Boot wäre, schwämmen die Schwimmer in Ruhe.'::text),
(393856,43762,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби тут не було підводного човна, плавці ... спокійно.'::text,'плавали б'::text,'плаватимуть'::text,'плавають'::text,'Якби тут не було підводного човна, плавці плавали б спокійно.'::text),
(393855,43762,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera un submarino aquí, los nadadores ... en paz.'::text,'nadarían'::text,'nadarán'::text,'nadan'::text,'Si no hubiera un submarino aquí, los nadadores nadarían en paz.'::text),
(393854,43762,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il n''y avait pas de sous-marin ici, les nageurs ... en paix.'::text,'nageraient'::text,'nageront'::text,'nagent'::text,'S''il n''y avait pas de sous-marin ici, les nageurs nageraient en paix.'::text),
(393857,43762,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Burada denizaltı olmasaydı yüzücüler huzur içinde ...'::text,'yüzerdi'::text,'yüzecek'::text,'yüzüyor'::text,'Burada denizaltı olmasaydı yüzücüler huzur içinde yüzerdi.'::text),
(393858,43762,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem lenne itt tengeralattjáró, az úszók nyugodtan ...'::text,'úszkálnának'::text,'úszkálni fognak'::text,'úszkálnak'::text,'Ha nem lenne itt tengeralattjáró, az úszók nyugodtan úszkálnának.'::text),
(393861,43763,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das U-Boot ... im Rahmen eines 3-tägigen Betriebstests hierher geschickt.'::text,'wurde'::text,'wird'::text,'schickte'::text,'Das U-Boot wurde im Rahmen eines 3-tägigen Betriebstests hierher geschickt.'::text),
(393865,43763,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Підводний човен ... сюди в межах 3-денного експлуатаційного тесту.'::text,'був направлений'::text,'направляють'::text,'направив'::text,'Підводний човен був направлений сюди в межах 3-денного експлуатаційного тесту.'::text),
(393864,43763,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El submarino ... aquí como parte de una prueba operativa de 3 días.'::text,'fue enviado'::text,'es enviado'::text,'envió'::text,'El submarino fue enviado aquí como parte de una prueba operativa de 3 días.'::text),
(393863,43763,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sous-marin ... ici dans le cadre d''un test opérationnel de 3 jours.'::text,'a été envoyé'::text,'est envoyé'::text,'a envoyé'::text,'Le sous-marin a été envoyé ici dans le cadre d''un test opérationnel de 3 jours.'::text),
(393866,43763,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Denizaltı 3 günlük bir operasyonel testin parçası olarak buraya ...'::text,'gönderildi'::text,'gönderiliyor'::text,'gönderdi'::text,'Denizaltı 3 günlük bir operasyonel testin parçası olarak buraya gönderildi.'::text),
(393867,43763,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tengeralattjárót egy 3 napos üzemi teszt részeként ... ide.'::text,'küldték'::text,'küldik'::text,'küldött'::text,'A tengeralattjárót egy 3 napos üzemi teszt részeként küldték ide.'::text),
(393870,43764,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... das U-Boot hinter den Schwimmern aus dem Wasser auf.'::text,'taucht'::text,'taucht'::text,'ist'::text,'Gerade taucht das U-Boot hinter den Schwimmern aus dem Wasser auf.'::text),
(393874,43764,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто зараз підводний човен ... з води позаду плавців.'::text,'виринає'::text,'виринає'::text,'виринув'::text,'Просто зараз підводний човен виринає з води позаду плавців.'::text),
(393873,43764,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo, el submarino ... del agua detrás de los nadadores.'::text,'está saliendo'::text,'sale'::text,'ha salido'::text,'Ahora mismo, el submarino está saliendo del agua detrás de los nadadores.'::text),
(393872,43764,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, le sous-marin ... de l''eau derrière les nageurs.'::text,'sort'::text,'sort'::text,'est sorti'::text,'En ce moment, le sous-marin sort de l''eau derrière les nageurs.'::text),
(393875,43764,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda denizaltı yüzücülerin arkasında sudan ...'::text,'yükseliyor'::text,'yükselir'::text,'yükseldi'::text,'Şu anda denizaltı yüzücülerin arkasında sudan yükseliyor.'::text),
(393876,43764,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most ... ki a tengeralattjáró a vízből az úszók mögött.'::text,'emelkedik'::text,'emelkedik'::text,'emelkedett'::text,'Épp most emelkedik ki a tengeralattjáró a vízből az úszók mögött.'::text),
(393888,43766,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend wird jeder vom U-Boot und vom Wal ...! Absolut unglaublich!'::text,'gehört haben'::text,'hören'::text,'hört'::text,'Bis heute Abend wird jeder vom U-Boot und vom Wal gehört haben! Absolut unglaublich!'::text),
(393892,43766,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора всі ... про підводний човен і кита! Абсолютно неймовірно!'::text,'почують'::text,'почують'::text,'чують'::text,'До вечора всі почують про підводний човен і кита! Абсолютно неймовірно!'::text),
(393891,43766,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para esta noche, todo el mundo ... del submarino y la ballena! ¡Absolutamente increíble!'::text,'habrá oído hablar'::text,'oirá hablar'::text,'oye hablar'::text,'¡Para esta noche, todo el mundo habrá oído hablar del submarino y la ballena! ¡Absolutamente increíble!'::text),
(393890,43766,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, tout le monde ... parler du sous-marin et de la baleine ! Absolument incroyable !'::text,'aura entendu'::text,'entendra'::text,'entend'::text,'D''ici ce soir, tout le monde aura entendu parler du sous-marin et de la baleine ! Absolument incroyable !'::text),
(393893,43766,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar herkes denizaltıyı ve balinayı ...! Kesinlikle inanılmaz!'::text,'duymuş olacak'::text,'duyacak'::text,'duyuyor'::text,'Bu akşama kadar herkes denizaltıyı ve balinayı duymuş olacak! Kesinlikle inanılmaz!'::text),
(393894,43766,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estére mindenki ... a tengeralattjáróról és a bálnáról! Teljesen hihetetlen!'::text,'hallani fog'::text,'hallani fog'::text,'hall'::text,'Estére mindenki hallani fog a tengeralattjáróról és a bálnáról! Teljesen hihetetlen!'::text),
(344847,38317,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, die Leute drängen sich jeden Mittag auf diesen Platz, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Hör mal, ich hab gehört, die Leute drängen sich jeden Mittag auf diesen Platz, oder?'::text),
(344851,38317,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що люди щодня опівдні юрмляться на тій площі, ...?'::text,'так'::text,'так'::text,'так'::text,'Слухай, я чула, що люди щодня опівдні юрмляться на тій площі, так?'::text),
(344850,38317,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, he oído que la gente se apiña en esa plaza cada mediodía, ¿...?'::text,'no'::text,'no'::text,'no'::text,'Oye, he oído que la gente se apiña en esa plaza cada mediodía, ¿no?'::text),
(344849,38317,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu que les gens s''entassent sur cette place tous les midis, ... ?'::text,'c''est ça'::text,'c''est ça'::text,'c''est ça'::text,'Écoute, j''ai entendu que les gens s''entassent sur cette place tous les midis, c''est ça ?'::text),
(344852,38317,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, insanlar her öğlen o meydana doluşuyormuş, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Dinle, insanlar her öğlen o meydana doluşuyormuş, değil mi?'::text),
(344853,38317,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy minden délben tömegek zsúfolódnak arra a térre, ...?'::text,'nem'::text,'nem'::text,'nem'::text,'Figyelj, azt hallottam, hogy minden délben tömegek zsúfolódnak arra a térre, nem?'::text),
(344865,38319,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich werden sich die Leute bis ein Uhr in jede Ecke des Platzes ...'::text,'gedrängt haben'::text,'drängen'::text,'am Drängen sein'::text,'Bestie, angeblich werden sich die Leute bis ein Uhr in jede Ecke des Platzes gedrängt haben.'::text),
(344869,38319,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, до першої люди ... в кожен куток тієї площі.'::text,'наб''ються'::text,'наб''ються'::text,'набиватимуться'::text,'Подруго, кажуть, до першої люди наб''ються в кожен куток тієї площі.'::text),
(344868,38319,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer, para la una la gente ... cada rincón de esa plaza.'::text,'habrá abarrotado'::text,'abarrotará'::text,'estará abarrotando'::text,'Amiga, al parecer, para la una la gente habrá abarrotado cada rincón de esa plaza.'::text),
(344867,38319,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment d''ici une heure, les gens ... dans chaque recoin de cette place.'::text,'se seront entassés'::text,'s''entasseront'::text,'seront en train de s''entasser'::text,'Ma belle, apparemment d''ici une heure, les gens se seront entassés dans chaque recoin de cette place.'::text),
(344870,38319,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre saat bire kadar insanlar o meydanın her köşesine ...'::text,'doluşmuş olacak'::text,'doluşacak'::text,'doluşuyor olacak'::text,'Kanka, duyduğuma göre saat bire kadar insanlar o meydanın her köşesine doluşmuş olacak.'::text),
(344871,38319,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag egy órára az emberek annak a térnek minden zugába ...'::text,'bezsúfolódnak'::text,'be fognak zsúfolódni'::text,'zsúfolódni fognak'::text,'Csajszi, állítólag egy órára az emberek annak a térnek minden zugába bezsúfolódnak.'::text),
(344874,38320,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre der Platz größer gewesen, ... sich die Leute nicht in der Mitte gedrängt.'::text,'hätten'::text,'werden'::text,'haben'::text,'Wäre der Platz größer gewesen, hätten sich die Leute nicht in der Mitte gedrängt.'::text),
(344878,38320,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби площа була більшою, люди не ... посередині.'::text,'скупчилися б'::text,'скупчаться'::text,'скупчилися'::text,'Якби площа була більшою, люди не скупчилися б посередині.'::text),
(344877,38320,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la plaza hubiera sido más grande, la gente no ... en el centro.'::text,'se habría apiñado'::text,'se apiñará'::text,'se apiñó'::text,'Si la plaza hubiera sido más grande, la gente no se habría apiñado en el centro.'::text),
(344876,38320,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la place avait été plus grande, les gens ... au milieu.'::text,'ne se seraient pas entassés'::text,'ne s''entasseront pas'::text,'ne se sont pas entassés'::text,'Si la place avait été plus grande, les gens ne se seraient pas entassés au milieu.'::text),
(344879,38320,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meydan daha büyük olsaydı insanlar ortada ...'::text,'toplanmazdı'::text,'toplanmayacak'::text,'toplanmadı'::text,'Meydan daha büyük olsaydı insanlar ortada toplanmazdı.'::text),
(344880,38320,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nagyobb lett volna a tér, az emberek nem ... össze középen.'::text,'zsúfolódtak volna'::text,'fognak zsúfolódni'::text,'zsúfolódtak'::text,'Ha nagyobb lett volna a tér, az emberek nem zsúfolódtak volna össze középen.'::text),
(344883,38321,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Wachmann warnte die Leute vor dem ... in die Mitte des Platzes.'::text,'Drängen'::text,'drängen'::text,'gedrängt'::text,'Der Wachmann warnte die Leute vor dem Drängen in die Mitte des Platzes.'::text),
(344887,38321,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Охоронець застеріг людей від ... до центру площі.'::text,'скупчення'::text,'скупчуватися'::text,'скупчилися'::text,'Охоронець застеріг людей від скупчення до центру площі.'::text),
(344886,38321,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El guardia advirtió a la gente que no ... hacia el centro de la plaza.'::text,'se apiñara'::text,'apiñarse'::text,'apiñada'::text,'El guardia advirtió a la gente que no se apiñara hacia el centro de la plaza.'::text),
(344885,38321,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gardien a déconseillé aux gens de ... au centre de la place.'::text,'s''entasser'::text,'s''entasser'::text,'entassés'::text,'Le gardien a déconseillé aux gens de s''entasser au centre de la place.'::text),
(344888,38321,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Görevli insanları meydanın ortasına ... karşı uyardı.'::text,'doluşmaya'::text,'doluşmak'::text,'doluştu'::text,'Görevli insanları meydanın ortasına doluşmaya karşı uyardı.'::text),
(344889,38321,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az őr óva intette az embereket attól, hogy ... a tér közepére.'::text,'betóduljanak'::text,'betódulni'::text,'betódultak'::text,'Az őr óva intette az embereket attól, hogy betóduljanak a tér közepére.'::text),
(344892,38322,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Veranstalter hätten die Leute nicht auf so engem Raum auf dem Platz ...'::text,'zusammendrängen sollen'::text,'zusammendrängen dürfen'::text,'zusammendrängen können'::text,'Die Veranstalter hätten die Leute nicht auf so engem Raum auf dem Platz zusammendrängen sollen.'::text),
(344896,38322,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Організатори ... людей на такий малий простір на площі.'::text,'не мали зганяти'::text,'не сміли зганяти'::text,'не могли зігнати'::text,'Організатори не мали зганяти людей на такий малий простір на площі.'::text),
(344895,38322,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los organizadores no ... a la gente en un espacio tan pequeño de la plaza.'::text,'deberían haber metido'::text,'tenían que haber metido'::text,'podían meter'::text,'Los organizadores no deberían haber metido a la gente en un espacio tan pequeño de la plaza.'::text),
(344894,38322,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les organisateurs ... les gens dans un espace aussi petit sur la place.'::text,'n''auraient pas dû entasser'::text,'ne devaient pas entasser'::text,'ne pouvaient pas entasser'::text,'Les organisateurs n''auraient pas dû entasser les gens dans un espace aussi petit sur la place.'::text),
(344897,38322,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Organizatörler insanları meydanda bu kadar küçük bir alana ...'::text,'doldurmamalıydı'::text,'doldurmamalıydı'::text,'dolduramazdı'::text,'Organizatörler insanları meydanda bu kadar küçük bir alana doldurmamalıydı.'::text),
(344898,38322,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szervezőknek nem ... bezsúfolniuk az embereket ilyen kis helyre a téren.'::text,'kellett volna'::text,'lett volna szabad'::text,'tudták'::text,'A szervezőknek nem kellett volna bezsúfolniuk az embereket ilyen kis helyre a téren.'::text),
(344901,38323,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Veranstalter ließen die Wachleute die Leute in die Mitte des Platzes ...'::text,'drängen'::text,'zu drängen'::text,'gedrängt'::text,'Die Veranstalter ließen die Wachleute die Leute in die Mitte des Platzes drängen.'::text),
(344905,38323,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Організатори доручили охоронцям ... людей до центру площі.'::text,'зігнати'::text,'зігнати'::text,'зігнаних'::text,'Організатори доручили охоронцям зігнати людей до центру площі.'::text),
(344904,38323,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los organizadores hicieron que los guardias ... a la gente hacia el centro de la plaza.'::text,'empujaran'::text,'empujaran'::text,'empujada'::text,'Los organizadores hicieron que los guardias empujaran a la gente hacia el centro de la plaza.'::text),
(344903,38323,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les organisateurs ont fait ... les gens au centre de la place par les gardes.'::text,'entasser'::text,'à entasser'::text,'entassés'::text,'Les organisateurs ont fait entasser les gens au centre de la place par les gardes.'::text),
(344906,38323,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Organizatörler görevlilere insanları meydanın ortasına ...'::text,'yığdırdı'::text,'yığmayı'::text,'yığılmış'::text,'Organizatörler görevlilere insanları meydanın ortasına yığdırdı.'::text),
(344907,38323,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szervezők az őrökkel ... az embereket a tér közepére.'::text,'tereltették'::text,'terelni'::text,'terelt'::text,'A szervezők az őrökkel tereltették az embereket a tér közepére.'::text),
(344919,38325,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Platz, ... Fliesen verschwinden, während sich die Leute hineindrängen, wird zum totalen Albtraum!'::text,'dessen'::text,'welcher'::text,'wo'::text,'Der Platz, dessen Fliesen verschwinden, während sich die Leute hineindrängen, wird zum totalen Albtraum!'::text),
(344923,38325,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Площа, ... плитка зникає, коли люди юрмляться, перетворюється на повний жах!'::text,'чия'::text,'яка'::text,'де'::text,'Площа, чия плитка зникає, коли люди юрмляться, перетворюється на повний жах!'::text),
(344922,38325,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La plaza, ... baldosas desaparecen a medida que la gente se apiña, se convierte en una pesadilla total!'::text,'cuyas'::text,'la cual'::text,'donde'::text,'¡La plaza, cuyas baldosas desaparecen a medida que la gente se apiña, se convierte en una pesadilla total!'::text),
(344921,38325,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La place, ... les dalles disparaissent à mesure que les gens s''entassent, devient un vrai cauchemar !'::text,'dont'::text,'laquelle'::text,'où'::text,'La place, dont les dalles disparaissent à mesure que les gens s''entassent, devient un vrai cauchemar !'::text),
(344924,38325,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnsanlar doluştukça ... karoları kaybolan meydan tam bir kâbusa dönüşüyor!'::text,''::text,NULL::text,NULL::text,'İnsanlar doluştukça karoları kaybolan meydan tam bir kâbusa dönüşüyor!'::text),
(344925,38325,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tér, ... járólapjai eltűnnek, ahogy az emberek betódulnak, totális rémálommá válik!'::text,'amelynek a'::text,'amely'::text,'ahol'::text,'A tér, amelynek a járólapjai eltűnnek, ahogy az emberek betódulnak, totális rémálommá válik!'::text),
(344928,38326,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Leute drängen sich weiter auf den Platz, ... absolut kein Platz mehr ist!'::text,'obwohl'::text,'trotz'::text,'falls'::text,'Die Leute drängen sich weiter auf den Platz, obwohl absolut kein Platz mehr ist!'::text),
(344932,38326,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Люди й далі юрмляться на площі, ... місця зовсім не лишилося!'::text,'хоча'::text,'попри'::text,'на випадок, якщо'::text,'Люди й далі юрмляться на площі, хоча місця зовсім не лишилося!'::text),
(344931,38326,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La gente sigue apiñándose en la plaza ... no queda absolutamente nada de espacio!'::text,'aunque'::text,'a pesar de'::text,'por si'::text,'¡La gente sigue apiñándose en la plaza aunque no queda absolutamente nada de espacio!'::text),
(344930,38326,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les gens continuent de s''entasser sur la place ... plus aucune place n''est libre !'::text,'même si'::text,'malgré'::text,'au cas où'::text,'Les gens continuent de s''entasser sur la place même si plus aucune place n''est libre !'::text),
(344933,38326,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hiç yer kalmamasına ... insanlar meydana doluşmaya devam ediyor!'::text,'rağmen'::text,'rağmen'::text,'diye'::text,'Hiç yer kalmamasına rağmen insanlar meydana doluşmaya devam ediyor!'::text),
(344934,38326,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az emberek tovább tódulnak a térre, ... egyáltalán nem maradt hely!'::text,'pedig'::text,'annak ellenére'::text,'arra az esetre, ha'::text,'Az emberek tovább tódulnak a térre, pedig egyáltalán nem maradt hely!'::text),
(344937,38327,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag werden sich Tausende Leute auf diesen Platz ..., ein kompletter Albtraum!'::text,'gedrängt haben'::text,'drängen'::text,'drängen'::text,'Bis Mittag werden sich Tausende Leute auf diesen Platz gedrängt haben, ein kompletter Albtraum!'::text),
(344941,38327,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До полудня тисячі людей ... на цю площу, повний жах!'::text,'наб''ються'::text,'наб''ються'::text,'набиваються'::text,'До полудня тисячі людей наб''ються на цю площу, повний жах!'::text),
(344940,38327,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para el mediodía, miles de personas ... en esta plaza, una pesadilla total!'::text,'se habrán apiñado'::text,'se apiñarán'::text,'se apiñan'::text,'¡Para el mediodía, miles de personas se habrán apiñado en esta plaza, una pesadilla total!'::text),
(344939,38327,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici midi, des milliers de personnes ... sur cette place, un vrai cauchemar !'::text,'se seront entassées'::text,'s''entasseront'::text,'s''entassent'::text,'D''ici midi, des milliers de personnes se seront entassées sur cette place, un vrai cauchemar !'::text),
(344942,38327,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar binlerce kişi bu meydana ..., tam bir kâbus!'::text,'doluşmuş olacak'::text,'doluşacak'::text,'doluşuyor'::text,'Öğlene kadar binlerce kişi bu meydana doluşmuş olacak, tam bir kâbus!'::text),
(344943,38327,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre emberek ezrei ... erre a térre, teljes rémálom!'::text,'zsúfolódnak be'::text,'fognak bezsúfolódni'::text,'zsúfolódnak'::text,'Délre emberek ezrei zsúfolódnak be erre a térre, teljes rémálom!'::text),
(381414,42380,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, morgen um diese Zeit ... er wieder auf dieser riskanten Slackline, ohne Witz.'::text,'balanciert gerade'::text,'wird balancieren'::text,'balanciert'::text,'Digga, morgen um diese Zeit balanciert gerade er wieder auf dieser riskanten Slackline, ohne Witz.'::text),
(381418,42380,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, завтра в цей час він знову ... тим ризикованим слеклайном, без брехні.'::text,'ходитиме'::text,'пройде'::text,'ходить'::text,'Бро, завтра в цей час він знову ходитиме тим ризикованим слеклайном, без брехні.'::text),
(381417,42380,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, mañana a esta hora ... otra vez por ese slackline tan arriesgado, sin mentira.'::text,'estará caminando'::text,'caminará'::text,'camina'::text,'Bro, mañana a esta hora estará caminando otra vez por ese slackline tan arriesgado, sin mentira.'::text),
(381416,42380,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, demain à la même heure, il ... encore sur cette slackline risquée, sans mentir.'::text,'sera en train de marcher'::text,'marchera'::text,'marche'::text,'Frérot, demain à la même heure, il sera en train de marcher encore sur cette slackline risquée, sans mentir.'::text),
(381419,42380,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yarın bu saatlerde yine o riskli slackline''da ..., yalan yok.'::text,'yürüyor olacak'::text,'yürüyecek'::text,'yürüyor'::text,'Kanka, yarın bu saatlerde yine o riskli slackline''da yürüyor olacak, yalan yok.'::text),
(381420,42380,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, holnap ilyenkor megint azon a rizikós slackline-on ..., nem kamu.'::text,'fog egyensúlyozni'::text,'fog egyensúlyozni'::text,'egyensúlyozik'::text,'Tesó, holnap ilyenkor megint azon a rizikós slackline-on fog egyensúlyozni, nem kamu.'::text),
(381423,42381,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wir garantieren, dass der riskante Menschenturm laut Agenda 6 Ebenen ...'::text,'erreichen wird'::text,'gerade erreichen wird'::text,'gerade erreicht'::text,'Wir garantieren, dass der riskante Menschenturm laut Agenda 6 Ebenen erreichen wird.'::text),
(381427,42381,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гарантуємо, що ризикована людська вежа ... 6 ярусів, згідно з програмою.'::text,'досягне'::text,'досягатиме'::text,'досягає'::text,'Гарантуємо, що ризикована людська вежа досягне 6 ярусів, згідно з програмою.'::text),
(381426,42381,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Garantizamos que la arriesgada torre humana ... 6 niveles, según la agenda.'::text,'alcanzará'::text,'estará alcanzando'::text,'está alcanzando'::text,'Garantizamos que la arriesgada torre humana alcanzará 6 niveles, según la agenda.'::text),
(381425,42381,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nous garantissons que la tour humaine risquée ... 6 niveaux, conformément au programme.'::text,'atteindra'::text,'sera en train d''atteindre'::text,'est en train d''atteindre'::text,'Nous garantissons que la tour humaine risquée atteindra 6 niveaux, conformément au programme.'::text),
(381428,42381,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Riskli insan kulesinin gündeme göre 6 kata ... garanti ediyoruz.'::text,'ulaşacağını'::text,'ulaşıyor olacağını'::text,'ulaştığını'::text,'Riskli insan kulesinin gündeme göre 6 kata ulaşacağını garanti ediyoruz.'::text),
(381429,42381,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Garantáljuk, hogy a rizikós emberi torony a napirend szerint ... a 6 szintet.'::text,'eléri'::text,'el fogja érni'::text,'éppen eléri'::text,'Garantáljuk, hogy a rizikós emberi torony a napirend szerint eléri a 6 szintet.'::text),
(381432,42382,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Stapel Stühle im Wind schwankt, ... es riskant, darunter zu stehen.'::text,'ist'::text,'wird'::text,'war'::text,'Wenn ein Stapel Stühle im Wind schwankt, ist es riskant, darunter zu stehen.'::text),
(381436,42382,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли стос стільців хитається на вітрі, стояти під ним ... ризиковано.'::text,''::text,'буде'::text,'було'::text,'Коли стос стільців хитається на вітрі, стояти під ним ризиковано.'::text),
(381435,42382,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si una pila de sillas se balancea con el viento, ... arriesgado ponerse debajo.'::text,'es'::text,'será'::text,'era'::text,'Si una pila de sillas se balancea con el viento, es arriesgado ponerse debajo.'::text),
(381434,42382,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand une pile de chaises oscille dans le vent, il ... risqué de se tenir dessous.'::text,'est'::text,'sera'::text,'était'::text,'Quand une pile de chaises oscille dans le vent, il est risqué de se tenir dessous.'::text),
(381437,42382,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir sandalye yığını rüzgârda sallanırsa altında durmak riskli ...'::text,''::text,'olacak'::text,'oldu'::text,'Bir sandalye yığını rüzgârda sallanırsa altında durmak riskli.'::text),
(381438,42382,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy székrakás inog a szélben, ... kockázatos alatta állni.'::text,''::text,'lesz'::text,'volt'::text,'Ha egy székrakás inog a szélben, kockázatos alatta állni.'::text),
(381441,42383,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der riskante Stuhlturm ... von jemandem gebaut, der ein perfektes Foto wollte.'::text,'wurde'::text,'baute'::text,'bauend'::text,'Der riskante Stuhlturm wurde von jemandem gebaut, der ein perfektes Foto wollte.'::text),
(381445,42383,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ризикована вежа зі стільців ... кимось, хто хотів ідеальне фото.'::text,'була збудована'::text,'збудувала'::text,'будуючи'::text,'Ризикована вежа зі стільців була збудована кимось, хто хотів ідеальне фото.'::text),
(381444,42383,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La arriesgada torre de sillas ... por alguien que quería una foto perfecta.'::text,'fue construida'::text,'construyó'::text,'construyendo'::text,'La arriesgada torre de sillas fue construida por alguien que quería una foto perfecta.'::text),
(381443,42383,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tour de chaises risquée ... par quelqu''un qui voulait une photo parfaite.'::text,'a été construite'::text,'a construit'::text,'construisant'::text,'La tour de chaises risquée a été construite par quelqu''un qui voulait une photo parfaite.'::text),
(381446,42383,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Riskli sandalye kulesi, mükemmel bir fotoğraf isteyen biri tarafından ...'::text,'yapıldı'::text,'yaptı'::text,'yaparak'::text,'Riskli sandalye kulesi, mükemmel bir fotoğraf isteyen biri tarafından yapıldı.'::text),
(381447,42383,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rizikós széktornyot valaki ..., aki tökéletes fotót akart.'::text,'építette'::text,'épített'::text,'építve'::text,'A rizikós széktornyot valaki építette, aki tökéletes fotót akart.'::text),
(381459,42385,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, angeblich ist der Typ, ... über diese riskante Slackline gelaufen ist, ein totaler Anfänger.'::text,'der'::text,'was'::text,'dessen'::text,'Girl, angeblich ist der Typ, der über diese riskante Slackline gelaufen ist, ein totaler Anfänger.'::text),
(381463,42385,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, хлопець, ... пройшов тим ризикованим слеклайном, — повний новачок.'::text,'який'::text,'що'::text,'чий'::text,'Подруго, кажуть, хлопець, який пройшов тим ризикованим слеклайном, — повний новачок.'::text),
(381462,42385,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer, el chico ... cruzó ese slackline tan arriesgado es un principiante total.'::text,'que'::text,'el cual'::text,'cuyo'::text,'Tía, al parecer, el chico que cruzó ese slackline tan arriesgado es un principiante total.'::text),
(381461,42385,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment le mec ... a traversé cette slackline risquée est un vrai débutant.'::text,'qui'::text,'lequel'::text,'dont'::text,'Meuf, apparemment le mec qui a traversé cette slackline risquée est un vrai débutant.'::text),
(381464,42385,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre o riskli slackline''da yürüyen ... çocuk tamamen acemiymiş.'::text,''::text,NULL::text,NULL::text,'Kızım, duyduğuma göre o riskli slackline''da yürüyen çocuk tamamen acemiymiş.'::text),
(381465,42385,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a srác, ... végigment azon a rizikós slackline-on, teljesen kezdő.'::text,'aki'::text,'amely'::text,'akinek a'::text,'Csajszi, állítólag a srác, aki végigment azon a rizikós slackline-on, teljesen kezdő.'::text),
(381468,42386,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir gesagt, die Slackline ... weniger riskant, als sie aussah.'::text,'sei'::text,'ist'::text,'werde'::text,'Hör zu, er hat mir gesagt, die Slackline sei weniger riskant, als sie aussah.'::text),
(381472,42386,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що слеклайн ... менш ризикований, ніж здавався.'::text,'був'::text,'є'::text,'буде'::text,'Слухай, він сказав мені, що слеклайн був менш ризикований, ніж здавався.'::text),
(381471,42386,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que el slackline ... menos arriesgado de lo que parecía.'::text,'era'::text,'es'::text,'será'::text,'Oye, me dijo que el slackline era menos arriesgado de lo que parecía.'::text),
(381470,42386,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit que la slackline ... moins risquée qu''elle n''en avait l''air.'::text,'était'::text,'est'::text,'sera'::text,'Écoute, il m''a dit que la slackline était moins risquée qu''elle n''en avait l''air.'::text),
(381473,42386,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana slackline''ın göründüğünden daha az riskli ... söyledi.'::text,'olduğunu'::text,'olduğunu'::text,'olacağını'::text,'Dinle, bana slackline''ın göründüğünden daha az riskli olduğunu söyledi.'::text),
(381474,42386,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy a slackline kevésbé ... rizikós, mint amilyennek látszott.'::text,'volt'::text,NULL::text,'lesz'::text,'Figyelj, azt mondta, hogy a slackline kevésbé volt rizikós, mint amilyennek látszott.'::text),
(381477,42387,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Na ja, jedenfalls hab ich gehört, dass die Jungs früher riskante Stunts ..., bevor sie Türme bauten.'::text,'hassten'::text,'hassten immer'::text,'gewohnt waren zu hassen'::text,'Na ja, jedenfalls hab ich gehört, dass die Jungs früher riskante Stunts hassten, bevor sie Türme bauten.'::text),
(381481,42387,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, я чула, що ті хлопці ... ризиковані трюки, поки не почали будувати вежі.'::text,'колись ненавиділи'::text,'бувало, ненавиділи'::text,'звикли ненавидіти'::text,'Коротше, я чула, що ті хлопці колись ненавиділи ризиковані трюки, поки не почали будувати вежі.'::text),
(381480,42387,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En fin, he oído que esos chicos ... las acrobacias arriesgadas antes de construir torres.'::text,'solían odiar'::text,'odiaban'::text,'estaban acostumbrados a odiar'::text,'En fin, he oído que esos chicos solían odiar las acrobacias arriesgadas antes de construir torres.'::text),
(381479,42387,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bref, j''ai entendu dire que ces mecs ... les cascades risquées avant de construire des tours.'::text,'détestaient'::text,'détestaient souvent'::text,'avaient l''habitude de détester'::text,'Bref, j''ai entendu dire que ces mecs détestaient les cascades risquées avant de construire des tours.'::text),
(381482,42387,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neyse, duyduğuma göre o çocuklar kule yapmadan önce riskli numaralardan ...'::text,'nefret ederlermiş'::text,'nefret ederlermiş'::text,'nefret etmeye alışkınmış'::text,'Neyse, duyduğuma göre o çocuklar kule yapmadan önce riskli numaralardan nefret ederlermiş.'::text),
(381483,42387,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, azt hallottam, hogy azok a srácok régen ... a rizikós mutatványokat, mielőtt tornyokat építettek.'::text,'utálták'::text,'utálták'::text,'hozzá voltak szokva utálni'::text,'Szóval, azt hallottam, hogy azok a srácok régen utálták a rizikós mutatványokat, mielőtt tornyokat építettek.'::text),
(381486,42388,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie genießen das ... auf den Schultern der anderen. Überhaupt nicht riskant, offensichtlich.'::text,'Stehen'::text,'zu stehen'::text,'stehen'::text,'Sie genießen das Stehen auf den Schultern der anderen. Überhaupt nicht riskant, offensichtlich.'::text),
(381490,42388,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їм подобається ... одне в одного на плечах. Анітрохи не ризиковано, звісно.'::text,'стояти'::text,'стояти'::text,'стояти'::text,'Їм подобається стояти одне в одного на плечах. Анітрохи не ризиковано, звісно.'::text),
(381489,42388,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Disfrutan de ... unos sobre los hombros de otros. Nada arriesgado, obviamente.'::text,'estar de pie'::text,'estar de pie'::text,'estar de pie'::text,'Disfrutan de estar de pie unos sobre los hombros de otros. Nada arriesgado, obviamente.'::text),
(381488,42388,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils adorent ... sur les épaules les uns des autres. Pas risqué du tout, évidemment.'::text,'se tenir debout'::text,'se tenir debout'::text,'se tenir debout'::text,'Ils adorent se tenir debout sur les épaules les uns des autres. Pas risqué du tout, évidemment.'::text),
(381491,42388,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Birbirlerinin omuzlarında ... bayılıyorlar. Hiç riskli değil, belli ki.'::text,'durmaya'::text,'durmaya'::text,'durmak'::text,'Birbirlerinin omuzlarında durmaya bayılıyorlar. Hiç riskli değil, belli ki.'::text),
(381492,42388,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Élvezik, hogy ... egymás vállán. Egyáltalán nem rizikós, nyilván.'::text,'állnak'::text,'állni'::text,'áll'::text,'Élvezik, hogy állnak egymás vállán. Egyáltalán nem rizikós, nyilván.'::text),
(381504,42390,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, der Typ ganz oben ... ewig, bevor der riskante Turm endlich hielt, irgendwie gruselig.'::text,'wackelte'::text,'wackelt'::text,'wackelt'::text,'Digga, der Typ ganz oben wackelte ewig, bevor der riskante Turm endlich hielt, irgendwie gruselig.'::text),
(381508,42390,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, той, що нагорі, ... цілу вічність, поки ризикована вежа нарешті не втрималася, реально страшно.'::text,'хитався'::text,'хитається'::text,'хитається'::text,'Бро, той, що нагорі, хитався цілу вічність, поки ризикована вежа нарешті не втрималася, реально страшно.'::text),
(381507,42390,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, el de arriba ... durante siglos antes de que la arriesgada torre por fin aguantara, bastante escalofriante.'::text,'había estado tambaleándose'::text,'ha estado tambaleándose'::text,'se tambalea'::text,'Bro, el de arriba había estado tambaleándose durante siglos antes de que la arriesgada torre por fin aguantara, bastante escalofriante.'::text),
(381506,42390,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, le mec tout en haut ... pendant des lustres avant que la tour risquée tienne enfin, un peu flippant.'::text,'avait vacillé'::text,'a vacillé'::text,'vacille'::text,'Frérot, le mec tout en haut avait vacillé pendant des lustres avant que la tour risquée tienne enfin, un peu flippant.'::text),
(381509,42390,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, en üstteki çocuk riskli kule sonunda sabitlenene kadar yıllarca ..., resmen korkutucu.'::text,'sallanıp durmuştu'::text,'sallanıp duruyor'::text,'sallanıyor'::text,'Kanka, en üstteki çocuk riskli kule sonunda sabitlenene kadar yıllarca sallanıp durmuştu, resmen korkutucu.'::text),
(381510,42390,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a legfelső srác egy örökkévalóságig ..., mire a rizikós torony végre megállt, elég ijesztő.'::text,'imbolygott'::text,'imbolyog'::text,'imbolyog'::text,'Tesó, a legfelső srác egy örökkévalóságig imbolygott, mire a rizikós torony végre megállt, elég ijesztő.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
where l.id = v.id and l.exercise_id = v.eid and l.language_code = v.lang and l.intro_text is not distinct from v.o_intro_text and l.correct_answer is not distinct from v.o_correct_answer and l.distractor_1 is not distinct from v.o_distractor_1 and l.distractor_2 is not distinct from v.o_distractor_2 and l.full_sentence is not distinct from v.o_full_sentence
returning l.id;
commit;
